/// Wavelet transform declared by the default coding style marker.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WaveletTransform {
    Irreversible97,
    Reversible53,
}

/// Component-level quantization parameters after QCD/QCC resolution.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ComponentQuantization {
    pub style: transform::QuantizationStyle,
    pub guard_bits: u8,
    /// One resolved entry per subband in LL, then resolution-order HL/LH/HH.
    pub steps: Vec<transform::IrreversibleQuantizationStep>,
}

impl ComponentQuantization {
    fn available_bitplanes(&self, subband_index: usize, entropy_coder: EntropyCoder) -> Result<u8> {
        let exponent = self
            .steps
            .get(subband_index)
            .ok_or(CodestreamError::SizeOverflow)?
            .exponent;
        let available = if self.style == transform::QuantizationStyle::NoQuantization
            && entropy_coder == EntropyCoder::HtBlockCoding
        {
            // The HT transfer resolves its QCD guard-bit contribution after
            // packet planning, so retain the exponent representation here.
            exponent.checked_add(1)
        } else {
            exponent
                .checked_add(self.guard_bits)
                .and_then(|value| value.checked_sub(1))
        };
        available.filter(|value| *value != 0).ok_or_else(|| {
            invalid(
                None,
                Some(Marker::Qcd),
                "quantization exponent and guard bits produce no decodable magnitude bitplanes",
            )
        })
    }

    fn irreversible_step(
        &self,
        subband_index: usize,
    ) -> Option<transform::IrreversibleQuantizationStep> {
        (self.style != transform::QuantizationStyle::NoQuantization)
            .then(|| self.steps.get(subband_index).copied())
            .flatten()
    }
}

#[cfg(test)]
mod reversible_quantization_tests {
    use super::*;

    fn reversible_quantization(guard_bits: u8, exponents: &[u8]) -> ComponentQuantization {
        ComponentQuantization {
            style: transform::QuantizationStyle::NoQuantization,
            guard_bits,
            steps: exponents
                .iter()
                .map(|&exponent| transform::IrreversibleQuantizationStep::new(exponent, 0).unwrap())
                .collect(),
        }
    }

    #[test]
    fn derives_reversible_magnitude_planes_from_each_qcd_field() {
        for (guard_bits, exponent, expected) in
            [(0, 2, 1), (1, 9, 9), (2, 8, 9), (3, 7, 9), (7, 31, 37)]
        {
            let quantization = reversible_quantization(guard_bits, &[exponent]);
            assert_eq!(
                quantization
                    .available_bitplanes(0, EntropyCoder::ClassicTier1)
                    .unwrap(),
                expected
            );
        }
    }

    #[test]
    fn applies_reversible_magnitude_planes_to_every_resolved_subband() {
        let quantization = reversible_quantization(3, &[7, 8, 9, 10]);
        let available = (0..4)
            .map(|index| {
                quantization
                    .available_bitplanes(index, EntropyCoder::ClassicTier1)
                    .unwrap()
            })
            .collect::<Vec<_>>();
        assert_eq!(available, [9, 10, 11, 12]);
    }

    #[test]
    fn rejects_reversible_qcd_without_a_magnitude_plane() {
        for (guard_bits, exponent) in [(0, 0), (0, 1), (1, 0)] {
            let quantization = reversible_quantization(guard_bits, &[exponent]);
            assert!(matches!(
                quantization.available_bitplanes(0, EntropyCoder::ClassicTier1),
                Err(CodestreamError::InvalidMarker {
                    marker: Some(Marker::Qcd),
                    ..
                })
            ));
        }

        let quantization = reversible_quantization(u8::MAX, &[31]);
        assert!(matches!(
            quantization.available_bitplanes(0, EntropyCoder::ClassicTier1),
            Err(CodestreamError::InvalidMarker {
                marker: Some(Marker::Qcd),
                ..
            })
        ));
    }

    #[test]
    fn guard_bit_equivalent_reversible_qcd_decodes_identically() {
        let samples = (0_u8..16).collect::<Vec<_>>();
        let baseline = encode_planar_u8_no_decomp_test_fixture(4, 4, &[&samples]).unwrap();
        let qcd = find_marker(&baseline, 0, Marker::Qcd).unwrap();
        let baseline_exponent = baseline[qcd + 5] >> 3;
        assert_eq!(baseline[qcd + 4] >> 5, 2);
        assert_eq!(baseline[qcd + 5] & 0x07, 0);

        for (guard_bits, exponent) in [
            (1, baseline_exponent + 1),
            (2, baseline_exponent),
            (3, baseline_exponent - 1),
        ] {
            let mut codestream = baseline.clone();
            codestream[qcd + 4] = guard_bits << 5;
            codestream[qcd + 5] = exponent << 3;

            let decoded = decode_baseline_owned_components(&codestream).unwrap();
            assert_eq!(decoded.width, 4);
            assert_eq!(decoded.height, 4);
            assert_eq!(decoded.components.len(), 1);
            assert_eq!(decoded.components[0].samples, samples);
        }
    }

    #[test]
    fn preserves_ht_packet_planning_exponent_representation() {
        let quantization = reversible_quantization(3, &[7]);
        assert_eq!(
            quantization
                .available_bitplanes(0, EntropyCoder::HtBlockCoding)
                .unwrap(),
            8
        );
    }

    #[test]
    fn benchmark_profile_uses_qcd_magnitude_planes() {
        let samples = (0_u8..16).collect::<Vec<_>>();
        let mut codestream = encode_planar_u8_no_decomp_test_fixture(4, 4, &[&samples]).unwrap();
        let qcd = find_marker(&codestream, 0, Marker::Qcd).unwrap();
        let exponent = codestream[qcd + 5] >> 3;
        codestream[qcd + 4] = 3 << 5;

        let segments = profile_code_block_segments_for_bench(&codestream).unwrap();
        assert_eq!(segments.len(), 1);
        assert_eq!(segments[0].spec.available_bitplanes, exponent + 2);
    }
}

#[cfg(test)]
mod ht_one_decomp_u16_transform_tests {
    use super::*;

    #[test]
    fn full_range_checkerboards_produce_signed_17_bit_hh_coefficients() {
        for (samples, expected_hh) in [
            ([0_u16, u16::MAX, u16::MAX, 0], -131_070),
            ([u16::MAX, 0, 0, u16::MAX], 131_070),
        ] {
            let mut coefficients = samples.map(|sample| i32::from(sample) - 32_768).to_vec();
            forward_reversible_5_3_levels(
                2,
                2,
                &mut coefficients,
                1,
                "2x2 checkerboard transform failed",
            )
            .unwrap();
            assert_eq!(coefficients, [0, 0, 0, expected_hh]);

            let specs = decomp_subband_specs(2, 2, 1).unwrap();
            assert_eq!(
                subband_available_bitplanes(2, &coefficients, specs[3].x, specs[3].y, 1, 1)
                    .unwrap(),
                17
            );

            let native = samples
                .iter()
                .flat_map(|sample| sample.to_le_bytes())
                .collect::<Vec<_>>();
            let encoded = encode_htj2k_grayscale_u16_le_one_decomp_with_precision(
                GrayscaleU16LeEncode {
                    width: 2,
                    height: 2,
                    samples: &native,
                    stride_bytes: 4,
                },
                16,
            )
            .unwrap();
            let qcd = find_marker(&encoded, 0, Marker::Qcd).unwrap();
            assert_eq!(encoded[qcd + 8] >> 3, 17);
        }
    }
}

/// Marker-level codestream summary available before packet decode.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Codestream {
    pub kind: CodestreamKind,
    pub siz: SizMarker,
    pub coding_style: Option<CodingStyleMarker>,
    /// Main-header component coding-style overrides, resolved over COD.
    pub component_coding_styles: Vec<ComponentCodingStyleMarker>,
    pub capability: Option<CapabilityMarker>,
    /// Part 1 profile declaration retained for CPF correspondence checks.
    pub profile: Option<ProfileMarker>,
    /// Optional Part 15 corresponding-profile declaration.
    pub corresponding_profile: Option<CorrespondingProfileMarker>,
    /// Main-header TLM entries reconciled with observed tile parts.
    pub tile_part_lengths: Option<TilePartLengthTable>,
    pub markers: Vec<MarkerSegment>,
    pub tiles: Vec<TilePartState>,
    pub progression: ProgressionState,
}

impl Codestream {
    pub fn image_width(&self) -> u32 {
        self.siz.reference_grid_width - self.siz.image_origin_x
    }

    pub fn image_height(&self) -> u32 {
        self.siz.reference_grid_height - self.siz.image_origin_y
    }

    /// Return the effective main-header coding style for one component.
    ///
    /// ISO/IEC 15444-1:2024, Annex A, A.6.1 and A.6.2, PDF pages 46–51,
    /// defines COD as the default and COC as the component-specific override.
    /// This project-authored representation keeps COD's image-wide fields and
    /// replaces only the component-local fields carried by COC. The reviewed
    /// retrieval revision is `34e5d1639b9f121807e620c001893ca9d2c8f977`.
    pub fn effective_coding_style(&self, component_index: u16) -> Option<CodingStyleMarker> {
        if component_index >= self.siz.component_count() {
            return None;
        }
        self.component_coding_styles
            .iter()
            .find(|style| style.component_index == component_index)
            .map(|style| style.coding_style)
            .or(self.coding_style)
    }

    /// Return the effective coding style when every component resolves alike.
    ///
    /// Decoder paths that do not yet support heterogeneous component styles
    /// use this boundary so classification, planning, and reconstruction
    /// cannot accidentally mix raw COD defaults with resolved COC fields.
    pub fn uniform_effective_coding_style(&self) -> Option<CodingStyleMarker> {
        let first = self.effective_coding_style(0)?;
        (1..self.siz.component_count())
            .all(|component_index| self.effective_coding_style(component_index) == Some(first))
            .then_some(first)
    }
}

/// Image and tile size marker (`SIZ`) contents.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SizMarker {
    pub capabilities: u16,
    pub reference_grid_width: u32,
    pub reference_grid_height: u32,
    pub image_origin_x: u32,
    pub image_origin_y: u32,
    pub tile_width: u32,
    pub tile_height: u32,
    pub tile_origin_x: u32,
    pub tile_origin_y: u32,
    pub components: Vec<ComponentParameters>,
}

impl SizMarker {
    /// Checked absolute half-open image area on the Part 1 reference grid.
    pub fn image_reference_rect(&self) -> Result<ReferenceGridRect> {
        ReferenceGridRect::new(
            self.image_origin_x,
            self.image_origin_y,
            self.reference_grid_width,
            self.reference_grid_height,
        )
    }

    /// Translate a full-resolution image-relative request to the absolute
    /// Part 1 reference grid.
    pub fn absolute_reference_region(
        &self,
        region: TileRegionRequest,
    ) -> Result<ReferenceGridRect> {
        ReferenceGridRect::from_image_relative(
            self.image_reference_rect()?,
            region.x,
            region.y,
            region.width,
            region.height,
        )
    }

    pub fn component_count(&self) -> u16 {
        self.components.len() as u16
    }

    pub fn tile_count_x(&self) -> Result<u32> {
        ceil_div(
            self.reference_grid_width
                .checked_sub(self.tile_origin_x)
                .ok_or(CodestreamError::InvalidMarker {
                    offset: None,
                    marker: Some(Marker::Siz),
                    message: "tile origin must not exceed reference grid width",
                })?,
            self.tile_width,
        )
    }

    pub fn tile_count_y(&self) -> Result<u32> {
        ceil_div(
            self.reference_grid_height
                .checked_sub(self.tile_origin_y)
                .ok_or(CodestreamError::InvalidMarker {
                    offset: None,
                    marker: Some(Marker::Siz),
                    message: "tile origin must not exceed reference grid height",
                })?,
            self.tile_height,
        )
    }
}

/// Per-component SIZ parameters.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ComponentParameters {
    pub bits_per_sample: u8,
    pub signed: bool,
    pub horizontal_separation: u8,
    pub vertical_separation: u8,
}

/// Default coding style marker (`COD`) contents.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CodingStyleMarker {
    pub entropy_coder: EntropyCoder,
    pub sop_markers: bool,
    pub eph_markers: bool,
    pub progression_order: ProgressionOrder,
    pub layers: u16,
    pub multiple_component_transform: bool,
    pub decomposition_levels: u8,
    pub code_block_width_exponent: u8,
    pub code_block_height_exponent: u8,
    pub code_block_style: u8,
    pub transform: WaveletTransform,
    pub precincts_declared: bool,
    pub precinct_width_exponent: Option<u8>,
    pub precinct_height_exponent: Option<u8>,
    /// Packed precinct exponents in resolution order, low resolution first.
    /// Only the first `decomposition_levels + 1` entries are meaningful.
    pub precinct_exponents: [u8; 33],
}

/// Main-header component coding-style marker (`COC`) resolved over COD.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ComponentCodingStyleMarker {
    pub component_index: u16,
    pub coding_style: CodingStyleMarker,
}

/// Entropy coding family declared or inferred from marker syntax.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EntropyCoder {
    ClassicTier1,
    HtBlockCoding,
}

/// Extended capabilities marker (`CAP`) contents.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CapabilityMarker {
    /// Compatibility view of the raw `Pcap` field retained by the previous
    /// public model. A structurally valid CAP marker always contributes one
    /// entry; new code should prefer [`Self::pcap`].
    pub pcaps: Vec<u32>,
    /// Part 1 capability presence bitmap. Bit 31 is `Pcap^1`.
    pub pcap: u32,
    /// One value for every set `Pcap` bit, ordered by capability index.
    pub parameters: Vec<CapabilityParameter>,
    /// Structured Part 15 capability when `Pcap^15` is set.
    pub part15: Option<Part15Capability>,
}

/// One `Ccap^i` value selected by the corresponding `Pcap^i` bit.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CapabilityParameter {
    pub index: u8,
    pub value: u16,
}

/// Part 15 code-block population declared by bits 14–15 of `Ccap^15`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Part15CodeBlockMode {
    HtOnly,
    HtDeclared,
    Mixed,
}

/// Semantic `Ccap^15` fields used for validity and native admission.
