impl<'a> HtCodestreamCodeBlockInput<'a> {
    fn decode_request(self) -> ht::HtCodeBlockDecodeRequest<'a> {
        if self.coding_passes > 1 {
            ht::HtCodeBlockDecodeRequest::new_with_active_dimensions_and_pass_segment_layout(
                self.candidate.marker_candidate,
                self.active_dimensions,
                self.missing_most_significant_bitplanes,
                self.coding_passes,
                self.segment_layout,
                self.segment_layout.lcup(),
                self.segment,
            )
        } else {
            ht::HtCodeBlockDecodeRequest::new_with_active_dimensions_and_cleanup_pass_segment_layout(
                self.candidate.marker_candidate,
                self.active_dimensions,
                self.missing_most_significant_bitplanes,
                self.coding_passes,
                self.segment_layout,
                self.segment,
            )
        }
    }

    #[allow(dead_code)]
    fn cleanup_pass_segment_layout(self) -> ht::HtCleanupPassSegmentLayout {
        self.segment_layout
    }

    #[allow(dead_code)]
    fn cleanup_pass_segment_views(
        self,
    ) -> core::result::Result<ht::HtCleanupPassSegmentViews<'a>, ht::HtLayoutError> {
        self.segment_layout.split_segment(self.segment)
    }

    #[allow(dead_code)]
    fn cleanup_pass_segment_bit_cursors(
        self,
    ) -> core::result::Result<ht::HtCleanupPassSegmentBitCursors<'a>, ht::HtLayoutError> {
        self.cleanup_pass_segment_views()?.bit_cursors()
    }

    fn coefficient_count(self) -> usize {
        self.active_dimensions.coefficient_count()
    }
}

