/// Work attributed to the Tier-1 backend that actually decoded a block.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Tier1BackendWorkCounters {
    pub blocks: u64,
    pub segment_bytes: u64,
    pub coefficients: u64,
    pub mq_bytes: u64,
    pub raw_bypass_bytes: u64,
}

impl Tier1BackendWorkCounters {
    fn add_assign(&mut self, other: &Self) {
        self.blocks = self.blocks.saturating_add(other.blocks);
        self.segment_bytes = self.segment_bytes.saturating_add(other.segment_bytes);
        self.coefficients = self.coefficients.saturating_add(other.coefficients);
        self.mq_bytes = self.mq_bytes.saturating_add(other.mq_bytes);
        self.raw_bypass_bytes = self.raw_bypass_bytes.saturating_add(other.raw_bypass_bytes);
    }
}

/// Recommended and executed Tier-1 routes kept separate so profiling never
/// presents a policy recommendation as work that actually ran.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Tier1RouteCounters {
    pub recommended_checked_blocks: u64,
    pub recommended_packed_dense_blocks: u64,
    pub recommended_packed_sparse_blocks: u64,
    pub executed_checked: Tier1BackendWorkCounters,
    pub executed_packed_dense: Tier1BackendWorkCounters,
    pub executed_packed_sparse: Tier1BackendWorkCounters,
}

impl Tier1RouteCounters {
    fn add_assign(&mut self, other: &Self) {
        self.recommended_checked_blocks = self
            .recommended_checked_blocks
            .saturating_add(other.recommended_checked_blocks);
        self.recommended_packed_dense_blocks = self
            .recommended_packed_dense_blocks
            .saturating_add(other.recommended_packed_dense_blocks);
        self.recommended_packed_sparse_blocks = self
            .recommended_packed_sparse_blocks
            .saturating_add(other.recommended_packed_sparse_blocks);
        self.executed_checked.add_assign(&other.executed_checked);
        self.executed_packed_dense
            .add_assign(&other.executed_packed_dense);
        self.executed_packed_sparse
            .add_assign(&other.executed_packed_sparse);
    }
}

/// Partitioning policy used by one prepared single-tile Tier-1 execution.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tier1ShardStrategy {
    /// Preserve the pre-Goal-38 equal-code-block-count partitioning.
    #[default]
    EqualCount,
    /// Partition contiguous packet-order contributions by estimated cost.
    CostWeighted,
}

impl Tier1ShardStrategy {
    pub const fn name(self) -> &'static str {
        match self {
            Self::EqualCount => "equal-count",
            Self::CostWeighted => "cost-weighted-contiguous",
        }
    }
}

/// Segment-acquisition shape used by one prepared single-tile Tier-1
/// execution.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tier1AcquisitionRoute {
    /// Acquire every selected segment, cross a barrier, and then decode. This
    /// pre-Goal-38 route remains available as a differential oracle.
    Split,
    /// Acquire and decode one block at a time inside its assigned shard.
    #[default]
    Fused,
}

impl Tier1AcquisitionRoute {
    pub const fn name(self) -> &'static str {
        match self {
            Self::Split => "split-acquisition-decode",
            Self::Fused => "fused-acquisition-decode",
        }
    }
}

