/// Dependency-, workspace-, lifting-, and copy-aware crossover inputs.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct SynthesisCrossoverEstimate {
    pub bounded_dependency_samples: u64,
    pub full_active_samples: u64,
    pub cropped_output_samples: u64,
    pub bounded_workspace_bytes: u64,
    pub full_workspace_bytes: u64,
    pub bounded_lifting_updates: u64,
    pub full_lifting_updates: u64,
    pub bounded_copy_samples: u64,
    pub full_copy_samples: u64,
    pub bounded_score: u64,
    pub full_score: u64,
}

impl SynthesisCrossoverEstimate {
    fn add_assign(&mut self, other: Self) {
        self.bounded_dependency_samples = self
            .bounded_dependency_samples
            .saturating_add(other.bounded_dependency_samples);
        self.full_active_samples = self
            .full_active_samples
            .saturating_add(other.full_active_samples);
        self.cropped_output_samples = self
            .cropped_output_samples
            .saturating_add(other.cropped_output_samples);
        self.bounded_workspace_bytes = self
            .bounded_workspace_bytes
            .saturating_add(other.bounded_workspace_bytes);
        self.full_workspace_bytes = self
            .full_workspace_bytes
            .saturating_add(other.full_workspace_bytes);
        self.bounded_lifting_updates = self
            .bounded_lifting_updates
            .saturating_add(other.bounded_lifting_updates);
        self.full_lifting_updates = self
            .full_lifting_updates
            .saturating_add(other.full_lifting_updates);
        self.bounded_copy_samples = self
            .bounded_copy_samples
            .saturating_add(other.bounded_copy_samples);
        self.full_copy_samples = self
            .full_copy_samples
            .saturating_add(other.full_copy_samples);
        self.bounded_score = self.bounded_score.saturating_add(other.bounded_score);
        self.full_score = self.full_score.saturating_add(other.full_score);
    }
}

/// Provenance for the executed crop/full crossover route.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum SynthesisCrossoverPolicy {
    #[default]
    Adaptive,
    Forced,
}

impl SynthesisCrossoverPolicy {
    pub const fn name(self) -> &'static str {
        match self {
            Self::Adaptive => "adaptive",
            Self::Forced => "forced",
        }
    }
}

impl PhaseWorkerTelemetry {
    fn add_assign(&mut self, other: &Self) {
        self.requested_workers = self.requested_workers.max(other.requested_workers);
        self.executed_workers = self.executed_workers.max(other.executed_workers);
        self.work_units = self.work_units.saturating_add(other.work_units);
        self.units_per_worker = if self.executed_workers == 0 {
            0
        } else {
            self.work_units
                .div_ceil(u64::try_from(self.executed_workers).unwrap_or(u64::MAX))
        };
        self.startup_and_barrier_ns = self
            .startup_and_barrier_ns
            .saturating_add(other.startup_and_barrier_ns);
        self.kernel_ns = self.kernel_ns.saturating_add(other.kernel_ns);
    }
}

