impl DecodeStageTimings {
    /// Derive balance and estimate-quality diagnostics from detailed records.
    pub fn tier1_shard_summary(&self) -> Tier1ShardSummary {
        let shard_count = self.tier1_shards.len();
        if shard_count == 0 {
            return Tier1ShardSummary::default();
        }
        let maximum_actual_ns = self
            .tier1_shards
            .iter()
            .map(|shard| shard.actual_ns)
            .max()
            .unwrap_or(0);
        let total_actual_ns = self
            .tier1_shards
            .iter()
            .fold(0_u128, |total, shard| total.saturating_add(shard.actual_ns));
        let maximum_estimated_work = self
            .tier1_shards
            .iter()
            .map(|shard| shard.estimated_work)
            .max()
            .unwrap_or(0);
        let total_estimated_work = self.tier1_shards.iter().fold(0_u64, |total, shard| {
            total.saturating_add(shard.estimated_work)
        });
        let shard_count_u128 = u128::try_from(shard_count).unwrap_or(u128::MAX);
        let shard_count_u64 = u64::try_from(shard_count).unwrap_or(u64::MAX);
        let mean_actual_ns = total_actual_ns / shard_count_u128;
        let mean_estimated_work = total_estimated_work / shard_count_u64;
        let maximum_actual_over_mean_x1000 = u64::try_from(
            maximum_actual_ns
                .saturating_mul(shard_count_u128)
                .saturating_mul(1_000)
                .checked_div(total_actual_ns)
                .unwrap_or(0),
        )
        .unwrap_or(u64::MAX);
        let maximum_estimated_over_mean_x1000 = maximum_estimated_work
            .saturating_mul(shard_count_u64)
            .saturating_mul(1_000)
            .checked_div(total_estimated_work)
            .unwrap_or(0);
        let critical_shard_index = self
            .tier1_shards
            .iter()
            .max_by_key(|shard| (shard.actual_ns, core::cmp::Reverse(shard.shard_index)))
            .map_or(0, |shard| shard.shard_index);

        let estimated_actual_rank_correlation_ppm = if shard_count < 2 {
            1_000_000
        } else {
            let mut squared_rank_difference = 0_i128;
            for (index, shard) in self.tier1_shards.iter().enumerate() {
                let estimated_rank = self
                    .tier1_shards
                    .iter()
                    .enumerate()
                    .filter(|(other_index, other)| {
                        (other.estimated_work, *other_index) < (shard.estimated_work, index)
                    })
                    .count() as i128;
                let actual_rank = self
                    .tier1_shards
                    .iter()
                    .enumerate()
                    .filter(|(other_index, other)| {
                        (other.actual_ns, *other_index) < (shard.actual_ns, index)
                    })
                    .count() as i128;
                let difference = estimated_rank - actual_rank;
                squared_rank_difference =
                    squared_rank_difference.saturating_add(difference.saturating_mul(difference));
            }
            let n = shard_count as i128;
            let denominator = n.saturating_mul(n.saturating_mul(n).saturating_sub(1));
            if denominator == 0 {
                1_000_000
            } else {
                i64::try_from(
                    1_000_000_i128.saturating_sub(
                        6_i128
                            .saturating_mul(squared_rank_difference)
                            .saturating_mul(1_000_000)
                            / denominator,
                    ),
                )
                .unwrap_or(i64::MIN)
            }
        };

        Tier1ShardSummary {
            shard_count,
            maximum_actual_ns,
            mean_actual_ns,
            maximum_actual_over_mean_x1000,
            maximum_estimated_work,
            mean_estimated_work,
            maximum_estimated_over_mean_x1000,
            estimated_actual_rank_correlation_ppm,
            critical_shard_index,
        }
    }

    pub fn add_assign(&mut self, other: &Self) {
        let other_collects_tier1_work_counters = other.collect_tier1_work_counters;
        self.collect_tier1_work_counters |= other_collects_tier1_work_counters;
        self.prepare_ns += other.prepare_ns;
        self.execute_ns += other.execute_ns;
        self.packets_parsed = self.packets_parsed.saturating_add(other.packets_parsed);
        self.packet_headers_parsed = self
            .packet_headers_parsed
            .saturating_add(other.packet_headers_parsed);
        self.packet_headers_reparsed = self
            .packet_headers_reparsed
            .saturating_add(other.packet_headers_reparsed);
        self.packets_skipped_via_plt = self
            .packets_skipped_via_plt
            .saturating_add(other.packets_skipped_via_plt);
        self.packet_bytes_skipped_via_plt = self
            .packet_bytes_skipped_via_plt
            .saturating_add(other.packet_bytes_skipped_via_plt);
        self.tile_parts_skipped_via_tlm = self
            .tile_parts_skipped_via_tlm
            .saturating_add(other.tile_parts_skipped_via_tlm);
        self.tile_part_bytes_skipped_via_tlm = self
            .tile_part_bytes_skipped_via_tlm
            .saturating_add(other.tile_part_bytes_skipped_via_tlm);
        self.packet_body_bytes_skipped = self
            .packet_body_bytes_skipped
            .saturating_add(other.packet_body_bytes_skipped);
        self.code_blocks_planned = self
            .code_blocks_planned
            .saturating_add(other.code_blocks_planned);
        self.prepared_code_blocks = self
            .prepared_code_blocks
            .saturating_add(other.prepared_code_blocks);
        self.code_blocks_decoded = self
            .code_blocks_decoded
            .saturating_add(other.code_blocks_decoded);
        self.executed_code_blocks = self
            .executed_code_blocks
            .saturating_add(other.executed_code_blocks);
        self.tile_payloads_prepared = self
            .tile_payloads_prepared
            .saturating_add(other.tile_payloads_prepared);
        self.tile_part_spans_prepared = self
            .tile_part_spans_prepared
            .saturating_add(other.tile_part_spans_prepared);
        self.tier1_codeword_bytes = self
            .tier1_codeword_bytes
            .saturating_add(other.tier1_codeword_bytes);
        self.tier1_coefficients = self
            .tier1_coefficients
            .saturating_add(other.tier1_coefficients);
        if self.tier1_shards.is_empty() {
            self.tier1_shard_strategy = other.tier1_shard_strategy;
            self.tier1_acquisition_route = other.tier1_acquisition_route;
        }
        let shard_index_base = self.tier1_shards.len();
        self.tier1_shards
            .extend(
                other
                    .tier1_shards
                    .iter()
                    .copied()
                    .enumerate()
                    .map(|(index, mut shard)| {
                        shard.shard_index = shard_index_base.saturating_add(index);
                        shard
                    }),
            );
        self.tier1_phase_workers
            .add_assign(&other.tier1_phase_workers);
        self.recommended_phase_worker_plan
            .max_assign(other.recommended_phase_worker_plan);
        self.executed_phase_worker_plan
            .max_assign(other.executed_phase_worker_plan);
        if other.phase_worker_plan_policy == PhaseWorkerPlanPolicy::Forced {
            self.phase_worker_plan_policy = PhaseWorkerPlanPolicy::Forced;
        }
        self.synthesis_crossover_estimate
            .add_assign(other.synthesis_crossover_estimate);
        if other.recommended_synthesis_crossover_route == SynthesisCrossoverRoute::Full {
            self.recommended_synthesis_crossover_route = SynthesisCrossoverRoute::Full;
        }
        if other.executed_synthesis_crossover_route == SynthesisCrossoverRoute::Full {
            self.executed_synthesis_crossover_route = SynthesisCrossoverRoute::Full;
        }
        if other.synthesis_crossover_policy == SynthesisCrossoverPolicy::Forced {
            self.synthesis_crossover_policy = SynthesisCrossoverPolicy::Forced;
        }
        self.tier1_routes.add_assign(&other.tier1_routes);
        self.tier1_checked_blocks = self
            .tier1_checked_blocks
            .saturating_add(other.tier1_checked_blocks);
        self.tier1_packed_blocks = self
            .tier1_packed_blocks
            .saturating_add(other.tier1_packed_blocks);
        self.tier1_raw_bypass_blocks = self
            .tier1_raw_bypass_blocks
            .saturating_add(other.tier1_raw_bypass_blocks);
        for (destination, source) in self
            .tier1_segment_bytes_histogram
            .iter_mut()
            .zip(other.tier1_segment_bytes_histogram)
        {
            *destination = destination.saturating_add(source);
        }
        for (destination, source) in self
            .tier1_coefficients_per_coded_byte_histogram
            .iter_mut()
            .zip(other.tier1_coefficients_per_coded_byte_histogram)
        {
            *destination = destination.saturating_add(source);
        }
        self.dwt_samples = self.dwt_samples.saturating_add(other.dwt_samples);
        self.synthesis_coefficients_loaded = self
            .synthesis_coefficients_loaded
            .saturating_add(other.synthesis_coefficients_loaded);
        self.synthesis_horizontal_values = self
            .synthesis_horizontal_values
            .saturating_add(other.synthesis_horizontal_values);
        self.synthesis_vertical_values = self
            .synthesis_vertical_values
            .saturating_add(other.synthesis_vertical_values);
        self.synthesis_lifting_updates = self
            .synthesis_lifting_updates
            .saturating_add(other.synthesis_lifting_updates);
        self.synthesis_output_samples = self
            .synthesis_output_samples
            .saturating_add(other.synthesis_output_samples);
        self.synthesis_output_bytes_written = self
            .synthesis_output_bytes_written
            .saturating_add(other.synthesis_output_bytes_written);
        self.windowed_synthesis_component_tiles = self
            .windowed_synthesis_component_tiles
            .saturating_add(other.windowed_synthesis_component_tiles);
        self.full_synthesis_component_tiles = self
            .full_synthesis_component_tiles
            .saturating_add(other.full_synthesis_component_tiles);
        self.windowed_coefficient_samples = self
            .windowed_coefficient_samples
            .saturating_add(other.windowed_coefficient_samples);
        self.full_coefficient_plane_samples_avoided = self
            .full_coefficient_plane_samples_avoided
            .saturating_add(other.full_coefficient_plane_samples_avoided);
        self.windowed_synthesis_value_bytes = self
            .windowed_synthesis_value_bytes
            .max(other.windowed_synthesis_value_bytes);
        self.output_samples = self.output_samples.saturating_add(other.output_samples);
        self.tile_part_copy_bytes = self
            .tile_part_copy_bytes
            .saturating_add(other.tile_part_copy_bytes);
        self.peak_scratch_bytes = self.peak_scratch_bytes.max(other.peak_scratch_bytes);
        self.full_output_allocation_bytes = self
            .full_output_allocation_bytes
            .saturating_add(other.full_output_allocation_bytes);
        self.full_coefficient_plane_capacity = self
            .full_coefficient_plane_capacity
            .max(other.full_coefficient_plane_capacity);
        self.full_transform_scratch_capacity = self
            .full_transform_scratch_capacity
            .max(other.full_transform_scratch_capacity);
        self.full_synthesis_estimated_bytes = self
            .full_synthesis_estimated_bytes
            .max(other.full_synthesis_estimated_bytes);
        self.full_synthesis_admitted_bytes = self
            .full_synthesis_admitted_bytes
            .max(other.full_synthesis_admitted_bytes);
        self.full_synthesis_request_admitted_bytes = self
            .full_synthesis_request_admitted_bytes
            .max(other.full_synthesis_request_admitted_bytes);
        self.full_synthesis_wave_jobs = self
            .full_synthesis_wave_jobs
            .max(other.full_synthesis_wave_jobs);
        self.full_synthesis_internal_workers = self
            .full_synthesis_internal_workers
            .max(other.full_synthesis_internal_workers);
        self.full_plane_clear_bytes = self
            .full_plane_clear_bytes
            .saturating_add(other.full_plane_clear_bytes);
        self.full_intermediate_output_bytes = self
            .full_intermediate_output_bytes
            .saturating_add(other.full_intermediate_output_bytes);
        self.caller_output_bytes = self
            .caller_output_bytes
            .saturating_add(other.caller_output_bytes);
        self.full_synthesis_backend =
            match (self.full_synthesis_backend, other.full_synthesis_backend) {
                (None, backend) => backend,
                (backend, None) => backend,
                (Some(current), Some(other)) if current == other => Some(current),
                (Some(_), Some(_)) => None,
            };
        self.full_legacy_scalar_component_tiles = self
            .full_legacy_scalar_component_tiles
            .saturating_add(other.full_legacy_scalar_component_tiles);
        self.full_parallel_striped_component_tiles = self
            .full_parallel_striped_component_tiles
            .saturating_add(other.full_parallel_striped_component_tiles);
        self.full_parallel_transpose_component_tiles = self
            .full_parallel_transpose_component_tiles
            .saturating_add(other.full_parallel_transpose_component_tiles);
        if self.execution_axis == DecodeParallelAxis::Scalar {
            self.execution_axis = other.execution_axis;
        }
        self.execution_workers = self.execution_workers.max(other.execution_workers);
        self.total_ns += other.total_ns;
        self.marker_parse_ns += other.marker_parse_ns;
        self.support_classification_ns += other.support_classification_ns;
        self.tile_payload_ns += other.tile_payload_ns;
        self.packet_header_parse_ns += other.packet_header_parse_ns;
        self.code_block_segment_acquisition_ns += other.code_block_segment_acquisition_ns;
        self.tier1_decode_ns += other.tier1_decode_ns;
        self.tier1_scratch_prepare_ns += other.tier1_scratch_prepare_ns;
        self.tier1_cleanup_pass_ns += other.tier1_cleanup_pass_ns;
        self.tier1_significance_propagation_pass_ns += other.tier1_significance_propagation_pass_ns;
        self.tier1_magnitude_refinement_pass_ns += other.tier1_magnitude_refinement_pass_ns;
        self.tier1_coefficient_copy_out_ns += other.tier1_coefficient_copy_out_ns;
        if other_collects_tier1_work_counters {
            self.tier1_work_counters
                .add_assign(&other.tier1_work_counters);
        }
        self.coefficient_placement_ns += other.coefficient_placement_ns;
        self.full_plane_prepare_ns += other.full_plane_prepare_ns;
        self.inverse_reversible_5_3_ns += other.inverse_reversible_5_3_ns;
        self.inverse_irreversible_9_7_ns += other.inverse_irreversible_9_7_ns;
        self.horizontal_synthesis_ns += other.horizontal_synthesis_ns;
        self.vertical_synthesis_ns += other.vertical_synthesis_ns;
        self.horizontal_synthesis_workers
            .add_assign(&other.horizontal_synthesis_workers);
        self.vertical_synthesis_workers
            .add_assign(&other.vertical_synthesis_workers);
        self.level_preparation_ns += other.level_preparation_ns;
        self.inverse_rct_ns += other.inverse_rct_ns;
        self.sample_conversion_ns += other.sample_conversion_ns;
        self.sample_conversion_workers
            .add_assign(&other.sample_conversion_workers);
        self.caller_buffer_placement_ns += other.caller_buffer_placement_ns;
    }

    #[cfg(feature = "std")]
    fn add_tier1_code_block_timings(&mut self, timings: &tier1::CodeBlockDecodeTimings) {
        self.tier1_scratch_prepare_ns += timings.scratch_prepare_ns;
        self.tier1_cleanup_pass_ns += timings.cleanup_pass_ns;
        self.tier1_significance_propagation_pass_ns += timings.significance_propagation_pass_ns;
        self.tier1_magnitude_refinement_pass_ns += timings.magnitude_refinement_pass_ns;
        self.tier1_coefficient_copy_out_ns += timings.coefficient_copy_out_ns;
    }

    #[cfg(feature = "std")]
    fn add_tier1_code_block_work_counters(
        &mut self,
        counters: &tier1::CodeBlockDecodeWorkCounters,
    ) {
        self.tier1_work_counters.add_assign(counters);
    }
}

#[cfg(feature = "std")]
#[derive(Debug, Clone, Copy)]
enum DecodeStage {
    TilePayload,
    PacketHeaderParse,
    CodeBlockSegmentAcquisition,
    Tier1Decode,
    CoefficientPlacement,
    InverseReversible53,
    InverseIrreversible97,
    InverseRct,
    SampleConversion,
}

#[cfg(feature = "std")]
fn record_stage(
    timings: &mut Option<&mut DecodeStageTimings>,
    stage: DecodeStage,
    elapsed: std::time::Duration,
) {
    let Some(timings) = timings.as_deref_mut() else {
        return;
    };
    let elapsed_ns = elapsed.as_nanos();
    match stage {
        DecodeStage::TilePayload => timings.tile_payload_ns += elapsed_ns,
        DecodeStage::PacketHeaderParse => timings.packet_header_parse_ns += elapsed_ns,
        DecodeStage::CodeBlockSegmentAcquisition => {
            timings.code_block_segment_acquisition_ns += elapsed_ns
        }
        DecodeStage::Tier1Decode => timings.tier1_decode_ns += elapsed_ns,
        DecodeStage::CoefficientPlacement => timings.coefficient_placement_ns += elapsed_ns,
        DecodeStage::InverseReversible53 => timings.inverse_reversible_5_3_ns += elapsed_ns,
        DecodeStage::InverseIrreversible97 => timings.inverse_irreversible_9_7_ns += elapsed_ns,
        DecodeStage::InverseRct => timings.inverse_rct_ns += elapsed_ns,
        DecodeStage::SampleConversion => timings.sample_conversion_ns += elapsed_ns,
    }
}

fn record_window_synthesis_report(
    timings: &mut DecodeStageTimings,
    report: transform::WindowSynthesisReport,
) {
    timings.synthesis_coefficients_loaded = timings
        .synthesis_coefficients_loaded
        .saturating_add(report.work.coefficients_loaded);
    timings.synthesis_horizontal_values = timings
        .synthesis_horizontal_values
        .saturating_add(report.work.horizontal_values);
    timings.synthesis_vertical_values = timings
        .synthesis_vertical_values
        .saturating_add(report.work.vertical_values);
    timings.synthesis_lifting_updates = timings
        .synthesis_lifting_updates
        .saturating_add(report.work.lifting_updates);
    timings.synthesis_output_samples = timings
        .synthesis_output_samples
        .saturating_add(report.work.output_samples);
    timings.horizontal_synthesis_ns = timings
        .horizontal_synthesis_ns
        .saturating_add(report.stages.horizontal_ns);
    timings.vertical_synthesis_ns = timings
        .vertical_synthesis_ns
        .saturating_add(report.stages.vertical_ns);
    timings.level_preparation_ns = timings
        .level_preparation_ns
        .saturating_add(report.stages.level_preparation_ns);
}

#[cfg(feature = "parallel")]
fn record_phase_worker_telemetry(
    destination: &mut PhaseWorkerTelemetry,
    requested_workers: usize,
    executed_workers: usize,
    work_units: u64,
    kernel_ns: u128,
    startup_and_barrier_ns: u128,
) {
    let executed_workers = executed_workers.max(1);
    destination.add_assign(&PhaseWorkerTelemetry {
        requested_workers: requested_workers.max(1),
        executed_workers,
        work_units,
        units_per_worker: work_units.div_ceil(u64::try_from(executed_workers).unwrap_or(u64::MAX)),
        startup_and_barrier_ns,
        kernel_ns,
    });
}

#[cfg(feature = "parallel")]
struct PhaseTaskTimer {
    enabled: bool,
    maximum_ns: core::sync::atomic::AtomicU64,
}

#[cfg(feature = "parallel")]
impl PhaseTaskTimer {
    fn new(enabled: bool) -> Self {
        Self {
            enabled,
            maximum_ns: core::sync::atomic::AtomicU64::new(0),
        }
    }

    #[cfg(feature = "std")]
    fn start(&self) -> Option<std::time::Instant> {
        self.enabled.then(std::time::Instant::now)
    }

    #[cfg(not(feature = "std"))]
    fn start(&self) -> Option<()> {
        None
    }

    #[cfg(feature = "std")]
    fn finish(&self, started: Option<std::time::Instant>) {
        use core::sync::atomic::Ordering;

        let elapsed = started.map_or(0, |started| started.elapsed().as_nanos());
        self.maximum_ns.fetch_max(
            u64::try_from(elapsed).unwrap_or(u64::MAX),
            Ordering::Relaxed,
        );
    }

    #[cfg(not(feature = "std"))]
    fn finish(&self, _started: Option<()>) {}

    fn maximum_ns(&self) -> u128 {
        use core::sync::atomic::Ordering;

        u128::from(self.maximum_ns.load(Ordering::Relaxed))
    }
}

#[cfg(feature = "parallel")]
fn record_parallel_window_phase_workers(
    timings: &mut DecodeStageTimings,
    report: transform::WindowSynthesisReport,
    horizontal_requested_workers: usize,
    vertical_requested_workers: usize,
) {
    let horizontal_workers = horizontal_requested_workers
        .min(usize::try_from(report.work.horizontal_values).unwrap_or(usize::MAX))
        .max(1);
    let vertical_workers = vertical_requested_workers
        .min(usize::try_from(report.work.vertical_values).unwrap_or(usize::MAX))
        .max(1);
    record_phase_worker_telemetry(
        &mut timings.horizontal_synthesis_workers,
        horizontal_requested_workers,
        horizontal_workers,
        report.work.horizontal_values,
        report.stages.horizontal_kernel_ns,
        report.stages.horizontal_startup_and_barrier_ns,
    );
    record_phase_worker_telemetry(
        &mut timings.vertical_synthesis_workers,
        vertical_requested_workers,
        vertical_workers,
        report.work.vertical_values,
        report.stages.vertical_kernel_ns,
        report.stages.vertical_startup_and_barrier_ns,
    );
}

fn full_synthesis_work(
    width: u32,
    height: u32,
    levels: u8,
    transform_kind: WaveletTransform,
) -> Result<transform::WindowSynthesisWork> {
    let output_samples = u64::from(width).saturating_mul(u64::from(height));
    let mut work = transform::WindowSynthesisWork {
        coefficients_loaded: output_samples,
        output_samples,
        ..transform::WindowSynthesisWork::default()
    };
    for resolution in 1..=levels {
        let (level_width, level_height) = resolution_dimensions(width, height, levels, resolution)?;
        let values = u64::from(level_width).saturating_mul(u64::from(level_height));
        work.horizontal_values = work.horizontal_values.saturating_add(values);
        work.vertical_values = work.vertical_values.saturating_add(values);
        let updates_per_axis = match transform_kind {
            WaveletTransform::Reversible53 => values,
            WaveletTransform::Irreversible97 => values.saturating_mul(2),
        };
        work.lifting_updates = work
            .lifting_updates
            .saturating_add(updates_per_axis.saturating_mul(2));
    }
    Ok(work)
}

fn record_full_synthesis_work(
    timings: &mut DecodeStageTimings,
    width: u32,
    height: u32,
    levels: u8,
    transform_kind: WaveletTransform,
) -> Result<()> {
    let work = full_synthesis_work(width, height, levels, transform_kind)?;
    record_window_synthesis_report(
        timings,
        transform::WindowSynthesisReport {
            work,
            ..transform::WindowSynthesisReport::default()
        },
    );
    Ok(())
}

fn decode_tier1_code_block_fast(
    segment: &[u8],
    coding_segments: &[tier1::CodeBlockSegment],
    decode_spec: tier1::CodeBlockDecodeSpec,
    coefficients: &mut [i32],
    scratch: &mut tier1::CodeBlockDecodeScratch,
) -> tier1::Result<tier1::CodeBlockDecodeOutcome> {
    let uses_segment_boundaries = decode_spec.style.bits()
        & (tier1::CodeBlockStyle::SELECTIVE_ARITHMETIC_BYPASS
            | tier1::CodeBlockStyle::TERMINATE_EACH_PASS)
        != 0;
    if uses_segment_boundaries {
        tier1::decode_baseline_code_block_segments_with_adaptive_scratch_outcome(
            segment,
            coding_segments,
            decode_spec,
            coefficients,
            scratch,
        )
    } else {
        tier1::decode_baseline_code_block_with_adaptive_scratch_outcome(
            segment,
            decode_spec,
            coefficients,
            scratch,
        )
    }
}

#[cfg(feature = "std")]
fn decode_tier1_code_block_with_optional_profile(
    segment: &[u8],
    coding_segments: &[tier1::CodeBlockSegment],
    decode_spec: tier1::CodeBlockDecodeSpec,
    coefficients: &mut [i32],
    scratch: &mut tier1::CodeBlockDecodeScratch,
    timings: &mut Option<&mut DecodeStageTimings>,
) -> tier1::Result<tier1::CodeBlockDecodeOutcome> {
    let uses_segment_boundaries = decode_spec.style.bits()
        & (tier1::CodeBlockStyle::SELECTIVE_ARITHMETIC_BYPASS
            | tier1::CodeBlockStyle::TERMINATE_EACH_PASS)
        != 0;
    let Some(stage_timings) = timings.as_deref_mut() else {
        return decode_tier1_code_block_fast(
            segment,
            coding_segments,
            decode_spec,
            coefficients,
            scratch,
        );
    };

    let mut code_block_timings = tier1::CodeBlockDecodeTimings::default();
    if stage_timings.collect_tier1_work_counters {
        let mut work_counters = tier1::CodeBlockDecodeWorkCounters::default();
        let decoded = if uses_segment_boundaries {
            tier1::decode_baseline_code_block_segments_with_scratch_profiled_and_counters(
                segment,
                coding_segments,
                decode_spec,
                coefficients,
                scratch,
                &mut code_block_timings,
                &mut work_counters,
            )
        } else {
            tier1::decode_baseline_code_block_with_scratch_profiled_and_counters(
                segment,
                decode_spec,
                coefficients,
                scratch,
                &mut code_block_timings,
                &mut work_counters,
            )
        }?;
        stage_timings.add_tier1_code_block_timings(&code_block_timings);
        stage_timings.add_tier1_code_block_work_counters(&work_counters);
        return tier1::checked_decode_outcome(decoded, coding_segments, decode_spec);
    }

    let decoded = if uses_segment_boundaries {
        tier1::decode_baseline_code_block_segments_with_scratch_profiled(
            segment,
            coding_segments,
            decode_spec,
            coefficients,
            scratch,
            &mut code_block_timings,
        )
    } else {
        tier1::decode_baseline_code_block_with_scratch_profiled(
            segment,
            decode_spec,
            coefficients,
            scratch,
            &mut code_block_timings,
        )
    }?;
    stage_timings.add_tier1_code_block_timings(&code_block_timings);
    tier1::checked_decode_outcome(decoded, coding_segments, decode_spec)
}

#[cfg(feature = "std")]
fn decode_irreversible_tier1_code_block_with_optional_profile(
    segment: &[u8],
    coding_segments: &[tier1::CodeBlockSegment],
    decode_spec: tier1::CodeBlockDecodeSpec,
    doubled_half_step_coefficients: &mut [i32],
    scratch: &mut tier1::CodeBlockDecodeScratch,
    timings: &mut Option<&mut DecodeStageTimings>,
) -> tier1::Result<tier1::CodeBlockDecodeOutcome> {
    let Some(stage_timings) = timings.as_deref_mut() else {
        return tier1::decode_irreversible_code_block_segments_with_adaptive_scratch_outcome(
            segment,
            coding_segments,
            decode_spec,
            doubled_half_step_coefficients,
            scratch,
        );
    };

    let mut code_block_timings = tier1::CodeBlockDecodeTimings::default();
    if stage_timings.collect_tier1_work_counters {
        let mut work_counters = tier1::CodeBlockDecodeWorkCounters::default();
        let decoded =
            tier1::decode_irreversible_code_block_segments_with_scratch_profiled_and_counters(
                segment,
                coding_segments,
                decode_spec,
                doubled_half_step_coefficients,
                scratch,
                &mut code_block_timings,
                &mut work_counters,
            )?;
        stage_timings.add_tier1_code_block_timings(&code_block_timings);
        stage_timings.add_tier1_code_block_work_counters(&work_counters);
        return tier1::checked_decode_outcome(decoded, coding_segments, decode_spec);
    }

    let decoded = tier1::decode_irreversible_code_block_segments_with_scratch_profiled(
        segment,
        coding_segments,
        decode_spec,
        doubled_half_step_coefficients,
        scratch,
        &mut code_block_timings,
    )?;
    stage_timings.add_tier1_code_block_timings(&code_block_timings);
    tier1::checked_decode_outcome(decoded, coding_segments, decode_spec)
}

/// Packet contribution for the narrow one-code-block LRCP profile.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PacketCodeBlock {
    pub missing_most_significant_bitplanes: u8,
    pub coding_passes: u16,
    pub codeword_len: usize,
    pub header_len: usize,
    pub payload_offset: usize,
}

/// Subband kind for a code-block contribution in an LRCP packet.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PacketSubbandKind {
    LowLow,
    HighLow,
    LowHigh,
    HighHigh,
}

impl PacketSubbandKind {
    /// Return the tier-1 subband context used for zero-coding labels.
    pub fn tier1_subband(self) -> tier1::Subband {
        match self {
            Self::LowLow => tier1::Subband::LowLow,
            Self::HighLow => tier1::Subband::HighLow,
            Self::LowHigh => tier1::Subband::LowHigh,
            Self::HighHigh => tier1::Subband::HighHigh,
        }
    }
}

/// One packet contribution for a code-block in the default-precinct baseline
/// profile.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PacketCodeBlockContribution {
    pub component_index: u16,
    pub resolution: u8,
    pub subband: PacketSubbandKind,
    pub subband_index: u8,
    pub code_block_x: u16,
    pub code_block_y: u16,
    pub x: u32,
    pub y: u32,
    pub width: u16,
    pub height: u16,
    pub available_bitplanes: u8,
    /// Irreversible QCD/QCC step for this subband. Reversible contributions
    /// retain `None` and preserve their integer coefficient contract.
    pub irreversible_quantization_step: Option<transform::IrreversibleQuantizationStep>,
    pub missing_most_significant_bitplanes: u8,
    pub coding_passes: u16,
    /// Total bytes contributed for this code-block across all parsed layers.
    pub codeword_len: usize,
    /// First segment offset. Contiguous callers can use this with
    /// `codeword_len`; fragmented multi-layer callers must use
    /// `segment_ranges`.
    pub payload_offset: usize,
    /// Fragmented payload ranges in coding-layer order. Empty means the
    /// contribution is one contiguous range described by `payload_offset` and
    /// `codeword_len`; populated vectors contain every range, including the
    /// first.
    pub segment_ranges: Vec<PacketCodeBlockSegmentRange>,
    /// Independently terminated Tier-1 segment lengths in coding-pass order.
    /// Empty means the code-block uses one continuous arithmetic segment.
    pub coding_segments: Vec<tier1::CodeBlockSegment>,
    /// Whether this contribution uses HT block coding. For one HT set, the
    /// existing contribution fields describe that set without another
    /// allocation.
    pub ht_coded: bool,
    /// All independently decodable HT coding sets when more than one set is
    /// retained. Empty for classic Tier-1 and the common one-set HT case.
    pub expanded_ht_coding_sets: Option<Box<[HtCodeBlockCodingSet]>>,
}

impl PacketCodeBlockContribution {
    fn inline_ht_coding_set(&self) -> Option<HtCodeBlockCodingSet> {
        self.ht_coded.then(|| HtCodeBlockCodingSet {
            byte_offset: 0,
            byte_len: self.codeword_len,
            cleanup_byte_len: self
                .coding_segments
                .first()
                .map_or(self.codeword_len, |segment| segment.byte_len),
            coding_passes: self.coding_passes,
            missing_most_significant_bitplanes: self.missing_most_significant_bitplanes,
        })
    }

    /// Returns all independently decodable HT coding sets in packet/layer
    /// order.
    pub fn ht_coding_sets(&self) -> impl Iterator<Item = HtCodeBlockCodingSet> + '_ {
        let expanded = self.expanded_ht_coding_sets.as_deref().unwrap_or(&[]);
        let inline = expanded
            .is_empty()
            .then(|| self.inline_ht_coding_set())
            .flatten();
        inline.into_iter().chain(expanded.iter().copied())
    }

    /// Returns the last independently decodable HT coding set.
    pub fn final_ht_coding_set(&self) -> Option<HtCodeBlockCodingSet> {
        self.expanded_ht_coding_sets
            .as_deref()
            .and_then(<[HtCodeBlockCodingSet]>::last)
            .copied()
            .or_else(|| self.inline_ht_coding_set())
    }

    /// Returns the number of independently decodable HT coding sets.
    pub fn ht_coding_set_count(&self) -> usize {
        self.expanded_ht_coding_sets
            .as_deref()
            .map_or_else(|| usize::from(self.ht_coded), <[HtCodeBlockCodingSet]>::len)
    }
}

/// One independently decodable HT Cleanup plus optional SPP/MRP set.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtCodeBlockCodingSet {
    /// Byte offset within the contribution's concatenated code-block bytes.
    pub byte_offset: usize,
    /// Total Cleanup plus refinement bytes in this set.
    pub byte_len: usize,
    /// Cleanup segment prefix length within this set.
    pub cleanup_byte_len: usize,
    /// One Cleanup plus zero, one, or two refinement passes.
    pub coding_passes: u16,
    /// Missing most-significant bitplanes for this set's Cleanup pass.
    pub missing_most_significant_bitplanes: u8,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PacketCodeBlockSegmentRange {
    pub payload_offset: usize,
    pub codeword_len: usize,
}

