/// Checked native output geometry and sample representation for one selected
/// Part 1 component plane.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Part1ComponentOutputInfo {
    pub component_index: u16,
    pub x_origin: u32,
    pub y_origin: u32,
    pub width: u32,
    pub height: u32,
    pub horizontal_separation: u8,
    pub vertical_separation: u8,
    pub bits_per_sample: u8,
    pub signed: bool,
}

/// Structurally validated selective Part 1 work retained for one or more
/// executions into caller-owned component planes.
///
/// The plan borrows packet bodies from the original codestream. Packet headers,
/// tile-part spans, selected-component routing, and code-block ranges are
/// resolved during preparation and are not rediscovered during execution.
#[derive(Debug)]
pub struct PreparedPart1ComponentDecode<'a> {
    codestream: Codestream,
    coding_style: CodingStyleMarker,
    component_indices: Vec<u16>,
    source_to_output: Vec<u16>,
    region: TileRegionRequest,
    output_region: TileRegionRequest,
    component_outputs: Vec<Part1ComponentOutputInfo>,
    native_component_geometry: bool,
    discard_levels: u8,
    component_sample_bytes: Vec<usize>,
    tiles: Vec<PreparedPart1TileDecode<'a>>,
    preparation_timings: DecodeStageTimings,
}

impl PreparedPart1ComponentDecode<'_> {
    /// Full-resolution request retained by this plan.
    pub fn region(&self) -> TileRegionRequest {
        self.region
    }

    /// Output dimensions after applying the retained discard level.
    pub fn output_dimensions(&self) -> (u32, u32) {
        (self.output_region.width, self.output_region.height)
    }

    /// Per-selected-component native output descriptors in caller plane order.
    pub fn component_outputs(&self) -> &[Part1ComponentOutputInfo] {
        &self.component_outputs
    }

    /// Whether any SIZ component in the complete source codestream uses
    /// non-unit sampling, independently of the selected output components.
    #[doc(hidden)]
    pub fn codestream_has_subsampled_components(&self) -> bool {
        self.codestream.siz.components.iter().any(|component| {
            component.horizontal_separation != 1 || component.vertical_separation != 1
        })
    }

    /// Whether the complete codestream satisfies the bounded native
    /// subsampled profile and can retain the requested resolution.
    #[doc(hidden)]
    pub fn codestream_supports_native_subsampled_discard(&self, discard_levels: u8) -> bool {
        validate_supported_native_subsampled_component_profile(&self.codestream).is_ok_and(
            |coding_style| {
                coding_style.transform == WaveletTransform::Reversible53
                    && coding_style.decomposition_levels >= discard_levels
            },
        )
    }

    /// Whether the complete codestream has the exact bounded quality-layer
    /// structure admitted by the facade.
    #[doc(hidden)]
    pub fn codestream_supports_native_quality_layers(&self) -> bool {
        is_supported_part1_native_quality_layer_component_profile(&self.codestream)
    }

    /// Declared quality-layer count when one effective coding style exists.
    #[doc(hidden)]
    pub fn codestream_declared_quality_layers(&self) -> Option<u16> {
        self.codestream
            .uniform_effective_coding_style()
            .map(|style| style.layers)
    }

    /// Full image dimensions retained from SIZ.
    #[doc(hidden)]
    pub fn codestream_image_dimensions(&self) -> (u32, u32) {
        (
            self.codestream.image_width(),
            self.codestream.image_height(),
        )
    }

    /// Selected source components in caller-visible output order.
    pub fn component_indices(&self) -> &[u16] {
        &self.component_indices
    }

    /// Uniform sample representation of the selected component planes.
    ///
    /// The current caller-planar profile requires one byte width across the
    /// selection. `None` is retained for future heterogeneous source profiles
    /// that cannot be described by the packed [`DecodedImage`] sample model.
    pub fn selected_sample_format(&self) -> Option<(u8, bool)> {
        let first_index = *self.component_indices.first()?;
        let first = self
            .codestream
            .siz
            .components
            .get(usize::from(first_index))?;
        self.component_indices
            .iter()
            .all(|index| {
                self.codestream
                    .siz
                    .components
                    .get(usize::from(*index))
                    .is_some_and(|component| {
                        component.bits_per_sample == first.bits_per_sample
                            && component.signed == first.signed
                    })
            })
            .then_some((first.bits_per_sample, first.signed))
    }

    /// Number of selected logical tile payloads retained by the plan.
    pub fn selected_tile_count(&self) -> usize {
        self.tiles.len()
    }

    /// Preparation work and timing counters captured when the plan was built.
    pub fn preparation_timings(&self) -> DecodeStageTimings {
        self.preparation_timings.clone()
    }

    /// Capacity-based retained topology accounting.
    pub fn memory_accounting(&self) -> PreparedPart1PlanMemory {
        prepared_part1_plan_memory(self)
    }

    /// Per-tile subband dependency plans in selected tile order.
    pub fn synthesis_windows(&self) -> impl Iterator<Item = (u16, &SynthesisWindowPlan)> {
        self.tiles
            .iter()
            .map(|tile| (tile.planned.tile.tile_index, &tile.synthesis_window))
    }

    /// Adaptive execution axis and bounded worker count for the current Rayon
    /// pool. The executor dispatches only this one axis for a prepared run.
    pub fn execution_parallelism(&self) -> (DecodeParallelAxis, usize) {
        prepared_part1_execution_parallelism(self, DecodeExecutionParallelism::Adaptive)
    }

    #[cfg(test)]
    fn force_full_synthesis_oracle(&mut self) {
        let mut prepared_code_blocks = 0_u64;
        for tile in &mut self.tiles {
            tile.synthesis_window.use_windowed_synthesis = false;
            tile.force_full_synthesis_oracle = true;
            tile.selected_contribution_indices.clear();
            tile.selected_contribution_indices
                .extend_from_slice(&tile.full_selected_contribution_indices);
            for component in &mut tile.component_plans {
                component.synthesis_window.use_windowed_synthesis = false;
                component.selected_contribution_indices.clear();
                component
                    .selected_contribution_indices
                    .extend_from_slice(&component.full_selected_contribution_indices);
            }
            prepared_code_blocks = prepared_code_blocks
                .saturating_add(tile.full_selected_contribution_indices.len() as u64);
        }
        self.preparation_timings.prepared_code_blocks = prepared_code_blocks;
    }
}

fn prepared_part1_execution_parallelism(
    _prepared: &PreparedPart1ComponentDecode<'_>,
    parallelism: DecodeExecutionParallelism,
) -> (DecodeParallelAxis, usize) {
    #[cfg(feature = "parallel")]
    {
        let available_workers = match parallelism {
            DecodeExecutionParallelism::Adaptive => rayon::current_num_threads(),
            DecodeExecutionParallelism::Serial => 1,
            DecodeExecutionParallelism::MaxWorkers(limit) => {
                rayon::current_num_threads().min(limit)
            }
        };
        if available_workers <= 1 {
            return (DecodeParallelAxis::Scalar, 1);
        }
        let prepared = _prepared;
        if prepared.native_component_geometry {
            return (DecodeParallelAxis::Scalar, 1);
        }
        let selected_code_blocks = prepared
            .tiles
            .iter()
            .map(|tile| tile.selected_contribution_indices.len())
            .sum::<usize>();
        let estimated_work = prepared.tiles.iter().fold(0_u64, |total, tile| {
            total.saturating_add(code_block_estimated_work_for_indices(
                &tile.contributions,
                &tile.selected_contribution_indices,
            ))
        });
        if prepared.tiles.len() >= MIN_PARALLEL_TILES
            && estimated_work >= MIN_PARALLEL_CODE_BLOCK_COEFFICIENTS
        {
            return (
                DecodeParallelAxis::Tiles,
                available_workers.min(prepared.tiles.len()),
            );
        }
        if prepared.component_indices.len() >= 2
            && estimated_work >= MIN_PARALLEL_CODE_BLOCK_COEFFICIENTS
        {
            return (
                DecodeParallelAxis::Components,
                available_workers.min(prepared.component_indices.len()),
            );
        }
        if prepared.tiles.len() == 1
            && prepared.component_indices.len() == 1
            && should_parallel_decode_code_block_work(selected_code_blocks, estimated_work)
        {
            return (
                DecodeParallelAxis::CodeBlocks,
                available_workers.min(selected_code_blocks),
            );
        }
    }
    let _ = parallelism;
    (DecodeParallelAxis::Scalar, 1)
}

fn capacity_bytes<T>(capacity: usize) -> u64 {
    (capacity as u64).saturating_mul(core::mem::size_of::<T>() as u64)
}

fn div_ceil_or_zero(bytes: u64, count: u64) -> u64 {
    if count == 0 { 0 } else { bytes.div_ceil(count) }
}

fn prepared_part1_plan_memory(
    prepared: &PreparedPart1ComponentDecode<'_>,
) -> PreparedPart1PlanMemory {
    let mut retained_heap_bytes = capacity_bytes::<u16>(prepared.component_indices.capacity())
        .saturating_add(capacity_bytes::<u16>(prepared.source_to_output.capacity()))
        .saturating_add(capacity_bytes::<usize>(
            prepared.component_sample_bytes.capacity(),
        ))
        .saturating_add(capacity_bytes::<Part1ComponentOutputInfo>(
            prepared.component_outputs.capacity(),
        ))
        .saturating_add(capacity_bytes::<PreparedPart1TileDecode<'_>>(
            prepared.tiles.capacity(),
        ))
        .saturating_add(capacity_bytes::<ComponentParameters>(
            prepared.codestream.siz.components.capacity(),
        ))
        .saturating_add(capacity_bytes::<MarkerSegment>(
            prepared.codestream.markers.capacity(),
        ))
        .saturating_add(capacity_bytes::<TilePartState>(
            prepared.codestream.tiles.capacity(),
        ));
    if let Some(table) = &prepared.codestream.tile_part_lengths {
        retained_heap_bytes =
            retained_heap_bytes.saturating_add(capacity_bytes::<TilePartLengthEntry>(
                table.entries.capacity(),
            ));
    }
    if let Some(capability) = &prepared.codestream.capability {
        retained_heap_bytes =
            retained_heap_bytes.saturating_add(capacity_bytes::<CapabilityParameter>(
                capability.parameters.capacity(),
            ));
        retained_heap_bytes =
            retained_heap_bytes.saturating_add(capacity_bytes::<u32>(capability.pcaps.capacity()));
    }
    if let Some(profile) = &prepared.codestream.profile {
        retained_heap_bytes =
            retained_heap_bytes.saturating_add(capacity_bytes::<u16>(profile.words.capacity()));
    }
    if let Some(profile) = &prepared.codestream.corresponding_profile {
        retained_heap_bytes =
            retained_heap_bytes.saturating_add(capacity_bytes::<u16>(profile.words.capacity()));
    }

    let mut prepared_code_block_count = 0_u64;
    let mut prepared_range_count = 0_u64;
    for tile in &prepared.tiles {
        retained_heap_bytes = retained_heap_bytes
            .saturating_add(tile.payload.span_heap_bytes())
            .saturating_add(capacity_bytes::<PacketCodeBlockContribution>(
                tile.contributions.capacity(),
            ))
            .saturating_add(capacity_bytes::<usize>(
                tile.selected_contribution_indices.capacity(),
            ))
            .saturating_add(capacity_bytes::<usize>(
                tile.bounded_selected_contribution_indices.capacity(),
            ))
            .saturating_add(capacity_bytes::<usize>(
                tile.full_selected_contribution_indices.capacity(),
            ))
            .saturating_add(capacity_bytes::<ResolutionWindowPlan>(
                tile.synthesis_window.levels.capacity(),
            ))
            .saturating_add(capacity_bytes::<PreparedPart1TileComponentDecode>(
                tile.component_plans.capacity(),
            ));
        for component in &tile.component_plans {
            retained_heap_bytes = retained_heap_bytes
                .saturating_add(capacity_bytes::<usize>(
                    component.selected_contribution_indices.capacity(),
                ))
                .saturating_add(capacity_bytes::<usize>(
                    component.bounded_selected_contribution_indices.capacity(),
                ))
                .saturating_add(capacity_bytes::<usize>(
                    component.full_selected_contribution_indices.capacity(),
                ))
                .saturating_add(capacity_bytes::<ResolutionWindowPlan>(
                    component.synthesis_window.levels.capacity(),
                ));
        }
        prepared_range_count =
            prepared_range_count.saturating_add(tile.payload.span_count() as u64);
        for contribution_index in &tile.full_selected_contribution_indices {
            let Some(contribution) = tile.contributions.get(*contribution_index) else {
                continue;
            };
            prepared_code_block_count = prepared_code_block_count.saturating_add(1);
            prepared_range_count = prepared_range_count
                .saturating_add(contribution.segment_ranges.len().max(1) as u64);
        }
        for contribution in &tile.contributions {
            retained_heap_bytes = retained_heap_bytes
                .saturating_add(capacity_bytes::<PacketCodeBlockSegmentRange>(
                    contribution.segment_ranges.capacity(),
                ))
                .saturating_add(capacity_bytes::<tier1::CodeBlockSegment>(
                    contribution.coding_segments.capacity(),
                ));
            if let Some(sets) = &contribution.expanded_ht_coding_sets {
                retained_heap_bytes = retained_heap_bytes.saturating_add(
                    (sets.len() as u64)
                        .saturating_mul(core::mem::size_of::<HtCodeBlockCodingSet>() as u64),
                );
            }
        }
    }
    let prepared_packet_count = prepared.preparation_timings.packet_headers_parsed;
    PreparedPart1PlanMemory {
        retained_heap_bytes,
        prepared_packet_count,
        prepared_code_block_count,
        prepared_range_count,
        bytes_per_prepared_packet: div_ceil_or_zero(retained_heap_bytes, prepared_packet_count),
        bytes_per_prepared_code_block: div_ceil_or_zero(
            retained_heap_bytes,
            prepared_code_block_count,
        ),
    }
}

/// Image-space tile rectangle derived from SIZ.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TileRect {
    pub tile_index: u16,
    pub tile_x: u32,
    pub tile_y: u32,
    pub x: u32,
    pub y: u32,
    pub width: u32,
    pub height: u32,
}

/// Tile-part payload selected by a decode work plan.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PlannedTilePart {
    pub tile_index: u16,
    pub tile_part_index: u8,
    pub payload_offset: usize,
    pub payload_len: usize,
}

/// Minimal internal work plan for a tile-region request.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TileRegionWorkPlan {
    pub request: TileRegionRequest,
    pub tiles: Vec<PlannedTileRegion>,
}

/// Per-tile work selected by a tile-region request.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PlannedTileRegion {
    pub tile: TileRect,
    pub intersection: TileRegionRequest,
    pub tile_parts: Vec<PlannedTilePart>,
}

/// Packet progression scaffolding derived from the default coding style.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct ProgressionState {
    pub order: Option<ProgressionOrder>,
    pub layers: Option<u16>,
    pub next_packet: PacketCursor,
}

/// Cursor scaffold for future packet iteration.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct PacketCursor {
    pub layer: u16,
    pub resolution: u8,
    pub component: u16,
    pub precinct: u32,
}

/// Stable identity for one packet visited inside a tile.
///
/// Keeping the tile and precinct axes explicit lets selective job builders
/// filter work without baking the current one-effective-precinct profile into
/// packet identity.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, PartialOrd, Ord)]
pub struct PacketKey {
    pub tile: u16,
    pub layer: u16,
    pub resolution: u8,
    pub component: u16,
    pub precinct: u32,
}

/// Raw marker segment record retained for diagnostics and future parser passes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MarkerSegment {
    pub marker: Marker,
    pub offset: usize,
    pub data_offset: usize,
    pub data_len: usize,
}

/// JPEG 2000 marker codes recognized by the metadata parser.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Marker {
    Soc,
    Sot,
    Sod,
    Eoc,
    Siz,
    Cod,
    Coc,
    Rgn,
    Qcd,
    Qcc,
    Poc,
    Tlm,
    Plm,
    Plt,
    Ppm,
    Ppt,
    Crg,
    Prf,
    Cpf,
    Sop,
    Eph,
    Cap,
    Com,
    Unknown(u16),
}

impl Marker {
    pub fn code(self) -> u16 {
        match self {
            Self::Soc => 0xff4f,
            Self::Sot => 0xff90,
            Self::Sod => 0xff93,
            Self::Eoc => 0xffd9,
            Self::Siz => 0xff51,
            Self::Cod => 0xff52,
            Self::Coc => 0xff53,
            Self::Rgn => 0xff5e,
            Self::Qcd => 0xff5c,
            Self::Qcc => 0xff5d,
            Self::Poc => 0xff5f,
            Self::Tlm => 0xff55,
            Self::Plm => 0xff57,
            Self::Plt => 0xff58,
            Self::Ppm => 0xff60,
            Self::Ppt => 0xff61,
            Self::Crg => 0xff63,
            Self::Prf => 0xff56,
            Self::Cpf => 0xff59,
            Self::Sop => 0xff91,
            Self::Eph => 0xff92,
            Self::Cap => 0xff50,
            Self::Com => 0xff64,
            Self::Unknown(code) => code,
        }
    }

    pub fn from_code(code: u16) -> Self {
        match code {
            0xff4f => Self::Soc,
            0xff90 => Self::Sot,
            0xff93 => Self::Sod,
            0xffd9 => Self::Eoc,
            0xff51 => Self::Siz,
            0xff52 => Self::Cod,
            0xff53 => Self::Coc,
            0xff5e => Self::Rgn,
            0xff5c => Self::Qcd,
            0xff5d => Self::Qcc,
            0xff5f => Self::Poc,
            0xff55 => Self::Tlm,
            0xff57 => Self::Plm,
            0xff58 => Self::Plt,
            0xff60 => Self::Ppm,
            0xff61 => Self::Ppt,
            0xff63 => Self::Crg,
            0xff56 => Self::Prf,
            0xff59 => Self::Cpf,
            0xff91 => Self::Sop,
            0xff92 => Self::Eph,
            0xff50 => Self::Cap,
            0xff64 => Self::Com,
            value => Self::Unknown(value),
        }
    }

    fn has_segment(self) -> bool {
        !matches!(self, Self::Soc | Self::Sod | Self::Eoc | Self::Eph)
            && !self.is_reserved_parameterless()
    }

    fn is_reserved_parameterless(self) -> bool {
        matches!(self, Self::Unknown(0xff30..=0xff3f))
    }

    fn is_part1_defined(self) -> bool {
        !matches!(self, Self::Cpf | Self::Unknown(_))
    }
}

impl fmt::Display for Marker {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Unknown(code) => write!(f, "0x{code:04x}"),
            marker => write!(f, "{marker:?}"),
        }
    }
}

/// Codestream parser and classifier error.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CodestreamError {
    Source {
        offset: u64,
        requested: u64,
        available: u64,
        message: String,
    },
    TruncatedInput {
        offset: usize,
        needed: usize,
        remaining: usize,
    },
    InvalidMarker {
        offset: Option<usize>,
        marker: Option<Marker>,
        message: &'static str,
    },
    Unsupported {
        offset: Option<usize>,
        marker: Option<Marker>,
        construct: UnsupportedConstruct,
        message: &'static str,
    },
    SizeOverflow,
}

/// Unsupported codestream constructs reported before decode is attempted.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum UnsupportedConstruct {
    MarkerSegment,
    ProgressionOrder,
    WaveletTransform,
    EntropyCoder,
    SamplePrecision,
    ComponentCount,
    ComponentSampling,
    MultipleTiles,
    Part2Capabilities,
    HtBlockDecode,
    PacketDecode,
    Tier1Decode,
    Transform,
}

impl fmt::Display for CodestreamError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Source {
                offset,
                requested,
                available,
                message,
            } => write!(
                f,
                "codestream source failure at byte {offset}: requested {requested} bytes, available {available} ({message})"
            ),
            Self::TruncatedInput {
                offset,
                needed,
                remaining,
            } => write!(
                f,
                "truncated codestream input at byte {offset}: needed {needed} bytes, had {remaining}"
            ),
            Self::InvalidMarker {
                offset,
                marker,
                message,
            } => match (offset, marker) {
                (Some(offset), Some(marker)) => {
                    write!(f, "invalid {marker} marker at byte {offset}: {message}")
                }
                (Some(offset), None) => write!(f, "invalid marker at byte {offset}: {message}"),
                (None, Some(marker)) => write!(f, "invalid {marker} marker: {message}"),
                (None, None) => write!(f, "invalid marker: {message}"),
            },
            Self::Unsupported {
                offset,
                marker,
                construct,
                message,
            } => match (offset, marker) {
                (Some(offset), Some(marker)) => write!(
                    f,
                    "unsupported {construct:?} in {marker} marker at byte {offset}: {message}"
                ),
                (Some(offset), None) => {
                    write!(f, "unsupported {construct:?} at byte {offset}: {message}")
                }
                (None, Some(marker)) => {
                    write!(f, "unsupported {construct:?} in {marker} marker: {message}")
                }
                (None, None) => write!(f, "unsupported {construct:?}: {message}"),
            },
            Self::SizeOverflow => f.write_str("codestream size overflowed usize"),
        }
    }
}

#[cfg(feature = "std")]
impl std::error::Error for CodestreamError {}

/// Convenient result alias for codestream operations.
pub type Result<T> = core::result::Result<T, CodestreamError>;

impl From<source::SourceError> for CodestreamError {
    fn from(error: source::SourceError) -> Self {
        Self::Source {
            offset: error.offset,
            requested: error.requested,
            available: error.available,
            message: error.message,
        }
    }
}

impl From<transform::TransformError> for CodestreamError {
    fn from(_error: transform::TransformError) -> Self {
        Self::SizeOverflow
    }
}

fn source_error_in_phase(error: source::SourceError, phase: &'static str) -> CodestreamError {
    CodestreamError::Source {
        offset: error.offset,
        requested: error.requested,
        available: error.available,
        message: format!("{phase}: {}", error.message),
    }
}

/// Boundary marker for future marker parser state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CodestreamBoundary {
    pub kind: CodestreamKind,
}

/// Parse marker-level codestream metadata from a byte slice.
pub fn parse(input: &[u8]) -> Result<Codestream> {
    let (codestream, work) = parse_with_selected_region(input, None)?;
    validate_packet_organisation_markers(input, &codestream, &work.tile_part_order)?;
    Ok(codestream)
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct TilePartParseWork {
    tile_parts_skipped_via_tlm: u64,
    tile_part_bytes_skipped_via_tlm: u64,
    tile_part_order: Vec<TilePartOrderEntry>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TilePartOrderEntry {
    tile_index: u16,
    tile_part_index: u8,
    payload_len: Option<usize>,
}

struct SourceHeaderScan {
    marker_bytes: Vec<u8>,
    codestream: Codestream,
    payload_spans: BTreeMap<u16, Vec<SourcePayloadSpan>>,
    work: TilePartParseWork,
}

fn source_marker(source: &dyn source::CodestreamSource, offset: u64) -> Result<Marker> {
    let mut bytes = [0_u8; 2];
    source.read_exact_at(offset, &mut bytes)?;
    if bytes[0] != 0xff {
        return Err(CodestreamError::Source {
            offset,
            requested: 2,
            available: 2,
            message: String::from("expected a JPEG 2000 marker prefix"),
        });
    }
    Ok(Marker::from_code(u16::from_be_bytes(bytes)))
}

fn scan_part1_source_headers(
    source: &dyn source::CodestreamSource,
    selected_region: TileRegionRequest,
) -> Result<SourceHeaderScan> {
    // Two-byte marker windows avoid speculatively pulling packet bodies across
    // SOT/SOD while segment payloads are still coalesced into exact reads.
    const HEADER_WINDOW_BYTES: usize = 2;

    let mut cursor = source::BufferedSourceCursor::new(source, 0, HEADER_WINDOW_BYTES)?;
    let mut marker_bytes = Vec::new();
    let mut marker_code = [0_u8; 2];
    cursor.read_exact(&mut marker_code)?;
    marker_bytes.extend_from_slice(&marker_code);
    if Marker::from_code(u16::from_be_bytes(marker_code)) != Marker::Soc {
        return Err(invalid(
            Some(0),
            Some(Marker::from_code(u16::from_be_bytes(marker_code))),
            "codestream source must start with SOC marker",
        ));
    }

    let mut siz = None;
    let mut coding_style = None;
    let mut capability = None;
    let mut profile = None;
    let mut corresponding_profile = None;
    let mut markers = Vec::new();
    let first_sot_source_offset = loop {
        let source_offset = cursor.position();
        cursor.read_exact(&mut marker_code)?;
        let marker = Marker::from_code(u16::from_be_bytes(marker_code));
        if marker == Marker::Sot {
            cursor.seek(source_offset)?;
            break source_offset;
        }
        let marker_offset = marker_bytes.len();
        marker_bytes.extend_from_slice(&marker_code);
        if !marker.has_segment() {
            markers.push(MarkerSegment {
                marker,
                offset: marker_offset,
                data_offset: marker_bytes.len(),
                data_len: 0,
            });
            if marker.is_reserved_parameterless() {
                continue;
            }
            return Err(invalid(
                usize::try_from(source_offset).ok(),
                Some(marker),
                "source main header ended before SOT",
            ));
        }
        let mut length_bytes = [0_u8; 2];
        cursor.read_exact(&mut length_bytes)?;
        marker_bytes.extend_from_slice(&length_bytes);
        let segment_len = usize::from(u16::from_be_bytes(length_bytes));
        if segment_len < 2 {
            return Err(invalid(
                Some(marker_offset),
                Some(marker),
                "marker segment length must include its length field",
            ));
        }
        let data_offset = marker_bytes.len();
        let data_len = segment_len - 2;
        let old_len = marker_bytes.len();
        marker_bytes.resize(
            old_len
                .checked_add(data_len)
                .ok_or(CodestreamError::SizeOverflow)?,
            0,
        );
        cursor.read_exact(&mut marker_bytes[old_len..])?;
        let segment = &marker_bytes[data_offset..data_offset + data_len];
        markers.push(MarkerSegment {
            marker,
            offset: marker_offset,
            data_offset,
            data_len,
        });
        match marker {
            Marker::Siz => siz = Some(parse_siz(segment, marker_offset)?),
            Marker::Cod => coding_style = Some(parse_cod(segment, marker_offset)?),
            Marker::Cap => set_once(
                &mut capability,
                parse_cap(segment, marker_offset)?,
                marker_offset,
                Marker::Cap,
                "codestream main header contains more than one CAP marker",
            )?,
            Marker::Prf => set_once(
                &mut profile,
                parse_profile_words(segment, marker_offset, Marker::Prf)?,
                marker_offset,
                Marker::Prf,
                "codestream main header contains more than one PRF marker",
            )?,
            Marker::Cpf => set_once(
                &mut corresponding_profile,
                parse_corresponding_profile(segment, marker_offset)?,
                marker_offset,
                Marker::Cpf,
                "codestream main header contains more than one CPF marker",
            )?,
            _ => {}
        }
    };
    let main_header_end = marker_bytes.len();

    let siz = siz.ok_or(CodestreamError::InvalidMarker {
        offset: None,
        marker: Some(Marker::Siz),
        message: "codestream main header must contain SIZ marker",
    })?;
    validate_siz(&siz)?;
    let strict_native_origin = siz.image_origin_x != 0
        || siz.image_origin_y != 0
        || siz.tile_origin_x != 0
        || siz.tile_origin_y != 0;
    if strict_native_origin
        && (markers.len() != 3
            || markers.iter().map(|segment| segment.marker).ne([
                Marker::Siz,
                Marker::Cod,
                Marker::Qcd,
            ]))
    {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "non-zero-origin source decode requires exactly one ordered main-header SOC, SIZ, COD and QCD sequence",
        ));
    }
    let declared =
        parse_declared_tile_part_lengths(&marker_bytes, &siz, &markers, marker_bytes.len())?;
    let tile_rects = tile_rects_for_siz(&siz)?;
    let mut selected_tiles = alloc::vec![false; tile_rects.len()];
    for tile in &tile_rects {
        if tile_intersects_region(*tile, selected_region) {
            *selected_tiles
                .get_mut(usize::from(tile.tile_index))
                .ok_or(CodestreamError::SizeOverflow)? = true;
        }
    }

    let mut all_tiles = Vec::new();
    let mut selected_tile_states = Vec::new();
    let mut payload_spans = BTreeMap::<u16, Vec<SourcePayloadSpan>>::new();
    let mut work = TilePartParseWork::default();
    let mut next_source_offset = first_sot_source_offset;
    let mut declared_index = 0_usize;
    loop {
        if let Some(declared) = declared.as_ref() {
            if declared_index == declared.len() {
                if source_marker(source, next_source_offset)? != Marker::Eoc {
                    return Err(invalid(
                        declared.last().map(|entry| entry.marker_offset),
                        Some(Marker::Tlm),
                        "complete source TLM coverage must end at EOC",
                    ));
                }
                break;
            }
        } else if source_marker(source, next_source_offset)? == Marker::Eoc {
            break;
        }

        let mut sot_bytes = [0_u8; 12];
        source.read_exact_at(next_source_offset, &mut sot_bytes)?;
        if Marker::from_code(u16::from_be_bytes([sot_bytes[0], sot_bytes[1]])) != Marker::Sot
            || u16::from_be_bytes([sot_bytes[2], sot_bytes[3]]) != 10
        {
            return Err(CodestreamError::Source {
                offset: next_source_offset,
                requested: 12,
                available: 12,
                message: String::from("tile-part index does not point to a valid SOT segment"),
            });
        }
        let tile = parse_sot(
            &sot_bytes[4..],
            usize::try_from(next_source_offset).unwrap_or(0),
        )?;
        let psot = tile.tile_part_length.ok_or_else(|| {
            unsupported(
                usize::try_from(next_source_offset).ok(),
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "source-backed scanning requires a bounded SOT Psot length",
            )
        })?;
        if let Some(declared) = declared.as_ref() {
            let entry = declared
                .get(declared_index)
                .ok_or(CodestreamError::SizeOverflow)?;
            if entry.tile_index != tile.tile_index || entry.tile_part_length != psot {
                return Err(invalid(
                    Some(entry.marker_offset),
                    Some(Marker::Tlm),
                    "source TLM entry disagrees with SOT Isot/Psot",
                ));
            }
        }
        all_tiles.push(tile);
        let selected = selected_tiles
            .get(usize::from(tile.tile_index))
            .copied()
            .unwrap_or(false);
        let retained_payload_len;
        if selected {
            let selected_marker_start = markers.len();
            let (selected_tile, span) = scan_selected_source_tile_part_header(
                source,
                next_source_offset,
                psot,
                &mut marker_bytes,
                &mut markers,
            )?;
            if strict_native_origin
                && markers[selected_marker_start..]
                    .iter()
                    .map(|segment| segment.marker)
                    .ne([Marker::Sot, Marker::Sod])
            {
                return Err(unsupported(
                    usize::try_from(next_source_offset).ok(),
                    Some(Marker::Sot),
                    UnsupportedConstruct::MarkerSegment,
                    "non-zero-origin source decode requires an exact SOT/SOD header for every selected tile-part",
                ));
            }
            retained_payload_len = Some(span.len);
            selected_tile_states.push(selected_tile);
            payload_spans.entry(tile.tile_index).or_default().push(span);
        } else {
            retained_payload_len = None;
            if strict_native_origin
                && source_marker(
                    source,
                    next_source_offset
                        .checked_add(12)
                        .ok_or(CodestreamError::SizeOverflow)?,
                )? != Marker::Sod
            {
                return Err(unsupported(
                    usize::try_from(next_source_offset).ok(),
                    Some(Marker::Sot),
                    UnsupportedConstruct::MarkerSegment,
                    "non-zero-origin source decode requires an exact SOT/SOD header for every unselected tile-part",
                ));
            }
            let inspected_header_bytes = if strict_native_origin { 14 } else { 12 };
            let unread = u64::from(psot).saturating_sub(inspected_header_bytes);
            source.record_bytes_not_read(unread, 0);
            if declared.is_some() {
                work.tile_parts_skipped_via_tlm = work.tile_parts_skipped_via_tlm.saturating_add(1);
                work.tile_part_bytes_skipped_via_tlm = work
                    .tile_part_bytes_skipped_via_tlm
                    .saturating_add(u64::from(psot));
            } else {
                // Psot scanning observed and sequence-validates every SOT while
                // leaving unselected optional headers/bodies unread. Retain a
                // metadata-only tile state so the existing profile validator
                // can prove full SIZ tile coverage; regional planning never
                // asks the payload factory for this tile.
                let mut metadata_only = tile;
                metadata_only.payload_offset = Some(0);
                metadata_only.payload_len =
                    Some(usize::try_from(psot).map_err(|_| CodestreamError::SizeOverflow)?);
                selected_tile_states.push(metadata_only);
            }
        }
        work.tile_part_order.push(TilePartOrderEntry {
            tile_index: tile.tile_index,
            tile_part_index: tile.tile_part_index,
            payload_len: retained_payload_len,
        });
        next_source_offset = next_source_offset
            .checked_add(u64::from(psot))
            .ok_or(CodestreamError::SizeOverflow)?;
        declared_index += 1;
    }
    validate_indexed_tile_part_sequence(&siz, &all_tiles)?;
    if strict_native_origin
        && next_source_offset
            .checked_add(2)
            .ok_or(CodestreamError::SizeOverflow)?
            != source.len()?
    {
        return Err(unsupported(
            usize::try_from(next_source_offset).ok(),
            Some(Marker::Eoc),
            UnsupportedConstruct::MarkerSegment,
            "non-zero-origin source decode requires EOC to terminate the raw codestream bytes",
        ));
    }

    let eoc_offset = marker_bytes.len();
    marker_bytes.extend_from_slice(&Marker::Eoc.code().to_be_bytes());
    markers.push(MarkerSegment {
        marker: Marker::Eoc,
        offset: eoc_offset,
        data_offset: eoc_offset + 2,
        data_len: 0,
    });
    let kind = validate_main_header_signalling(
        &siz,
        capability.as_ref(),
        profile.as_ref(),
        corresponding_profile.as_ref(),
        &markers,
    )?;
    if kind == CodestreamKind::Htj2k
        && let Some(style) = &mut coding_style
    {
        style.entropy_coder = EntropyCoder::HtBlockCoding;
    }
    let header_state = resolve_effective_header_state(&marker_bytes, &siz, kind, &markers)?;
    validate_part15_capability_constraints(
        &marker_bytes,
        &markers,
        &siz,
        capability.as_ref(),
        &header_state,
    )?;
    let component_coding_styles = parse_main_component_coding_styles(
        &marker_bytes,
        &siz,
        coding_style,
        &markers,
        main_header_end,
    )?;
    let progression = ProgressionState {
        order: coding_style.map(|style| style.progression_order),
        layers: coding_style.map(|style| style.layers),
        next_packet: PacketCursor::default(),
    };
    let tile_part_lengths = declared.as_ref().map(|declared| TilePartLengthTable {
        entries: declared
            .iter()
            .map(|entry| TilePartLengthEntry {
                tile_index: entry.tile_index,
                tile_part_length: entry.tile_part_length,
                // Source-backed prepared topology retains the authoritative
                // physical `u64` offsets in `SourcePayloadSpan`; these compact
                // entries exist only to preserve complete-TLM validation state.
                sot_offset: 0,
                marker_offset: entry.marker_offset,
            })
            .collect(),
        fully_covers_codestream: true,
    });
    Ok(SourceHeaderScan {
        marker_bytes,
        codestream: Codestream {
            kind,
            siz,
            coding_style,
            component_coding_styles,
            capability,
            profile,
            corresponding_profile,
            tile_part_lengths,
            markers,
            tiles: selected_tile_states,
            progression,
        },
        payload_spans,
        work,
    })
}

fn scan_selected_source_tile_part_header(
    source: &dyn source::CodestreamSource,
    sot_source_offset: u64,
    psot: u32,
    marker_bytes: &mut Vec<u8>,
    markers: &mut Vec<MarkerSegment>,
) -> Result<(TilePartState, SourcePayloadSpan)> {
    const TILE_HEADER_WINDOW_BYTES: usize = 2;
    let mut cursor =
        source::BufferedSourceCursor::new(source, sot_source_offset, TILE_HEADER_WINDOW_BYTES)?;
    let mut parsed_tile: Option<TilePartState> = None;
    loop {
        let marker_source_offset = cursor.position();
        let marker_offset = marker_bytes.len();
        let mut code = [0_u8; 2];
        cursor.read_exact(&mut code)?;
        marker_bytes.extend_from_slice(&code);
        let marker = Marker::from_code(u16::from_be_bytes(code));
        if !marker.has_segment() {
            markers.push(MarkerSegment {
                marker,
                offset: marker_offset,
                data_offset: marker_bytes.len(),
                data_len: 0,
            });
            if marker.is_reserved_parameterless() {
                continue;
            }
            if marker != Marker::Sod {
                return Err(invalid(
                    Some(marker_offset),
                    Some(marker),
                    "selected source tile header ended before SOD",
                ));
            }
            let payload_source_offset = cursor.position();
            let header_len = payload_source_offset
                .checked_sub(sot_source_offset)
                .ok_or(CodestreamError::SizeOverflow)?;
            let payload_len = u64::from(psot).checked_sub(header_len).ok_or_else(|| {
                invalid(
                    Some(marker_offset),
                    Some(Marker::Sot),
                    "SOT Psot ends before the selected SOD payload",
                )
            })?;
            let mut tile = parsed_tile.ok_or(CodestreamError::SizeOverflow)?;
            tile.payload_offset = Some(marker_bytes.len());
            tile.payload_len =
                Some(usize::try_from(payload_len).map_err(|_| CodestreamError::SizeOverflow)?);
            return Ok((
                tile,
                SourcePayloadSpan {
                    logical_offset: 0,
                    source_offset: payload_source_offset,
                    len: usize::try_from(payload_len).map_err(|_| CodestreamError::SizeOverflow)?,
                },
            ));
        }

        let mut length_bytes = [0_u8; 2];
        cursor.read_exact(&mut length_bytes)?;
        marker_bytes.extend_from_slice(&length_bytes);
        let segment_len = usize::from(u16::from_be_bytes(length_bytes));
        if segment_len < 2 {
            return Err(invalid(
                Some(marker_offset),
                Some(marker),
                "tile marker segment length must include its length field",
            ));
        }
        let data_offset = marker_bytes.len();
        let data_len = segment_len - 2;
        let old_len = marker_bytes.len();
        marker_bytes.resize(
            old_len
                .checked_add(data_len)
                .ok_or(CodestreamError::SizeOverflow)?,
            0,
        );
        cursor.read_exact(&mut marker_bytes[old_len..])?;
        markers.push(MarkerSegment {
            marker,
            offset: marker_offset,
            data_offset,
            data_len,
        });
        if marker == Marker::Sot {
            if marker_source_offset != sot_source_offset || segment_len != 10 {
                return Err(invalid(
                    Some(marker_offset),
                    Some(Marker::Sot),
                    "selected tile-part must begin with a ten-byte SOT segment",
                ));
            }
            let tile = parse_sot(
                &marker_bytes[data_offset..data_offset + data_len],
                marker_offset,
            )?;
            if tile.tile_part_length != Some(psot) {
                return Err(invalid(
                    Some(marker_offset),
                    Some(Marker::Sot),
                    "selected SOT Psot changed during header scanning",
                ));
            }
            parsed_tile = Some(tile);
        }
        if cursor.position().saturating_sub(sot_source_offset) >= u64::from(psot) {
            return Err(invalid(
                Some(marker_offset),
                Some(Marker::Sot),
                "selected tile header reaches Psot before SOD",
            ));
        }
    }
}

fn parse_with_selected_region(
    input: &[u8],
    selected_region: Option<TileRegionRequest>,
) -> Result<(Codestream, TilePartParseWork)> {
    if input.is_empty() {
        return Err(CodestreamError::TruncatedInput {
            offset: 0,
            needed: 2,
            remaining: 0,
        });
    }

    let mut offset = 0;
    let soc = read_marker(input, offset)?;
    if soc != Marker::Soc {
        return Err(invalid(
            Some(offset),
            Some(soc),
            "codestream must start with SOC marker",
        ));
    }
    offset += 2;

    let mut siz = None;
    let mut coding_style = None;
    let mut capability = None;
    let mut profile = None;
    let mut corresponding_profile = None;
    let mut markers = Vec::new();
    let mut tiles = Vec::new();
    let mut saw_payload_boundary = false;
    let mut tile_part_lengths_override = None;
    let mut parse_work = TilePartParseWork::default();

    while offset < input.len() {
        let marker_offset = offset;
        let marker = read_marker(input, marker_offset)?;
        offset += 2;

        if !marker.has_segment() {
            markers.push(MarkerSegment {
                marker,
                offset: marker_offset,
                data_offset: offset,
                data_len: 0,
            });
            if matches!(marker, Marker::Sod | Marker::Eoc) {
                saw_payload_boundary = true;
                break;
            }
            continue;
        }

        let segment_len = read_u16(input, offset)? as usize;
        if segment_len < 2 {
            return Err(invalid(
                Some(marker_offset),
                Some(marker),
                "marker segment length must include the two-byte length field",
            ));
        }
        let data_offset = offset + 2;
        let data_len = segment_len - 2;
        require(input, data_offset, data_len)?;
        let segment = checked_slice(input, data_offset, data_len)?;
        if marker == Marker::Sot
            && tiles.is_empty()
            && let (Some(region), Some(siz)) = (selected_region, siz.as_ref())
            && let Some(indexed) =
                parse_selected_tile_parts_from_tlm(input, siz, &markers, marker_offset, region)?
        {
            markers.extend(indexed.markers);
            tiles = indexed.tiles;
            tile_part_lengths_override = Some(indexed.tile_part_lengths);
            parse_work = indexed.work;
            saw_payload_boundary = true;
            break;
        }
        markers.push(MarkerSegment {
            marker,
            offset: marker_offset,
            data_offset,
            data_len,
        });

        match marker {
            Marker::Siz => siz = Some(parse_siz(segment, marker_offset)?),
            Marker::Cod => coding_style = Some(parse_cod(segment, marker_offset)?),
            Marker::Cap => set_once(
                &mut capability,
                parse_cap(segment, marker_offset)?,
                marker_offset,
                Marker::Cap,
                "codestream main header contains more than one CAP marker",
            )?,
            Marker::Prf => set_once(
                &mut profile,
                parse_profile_words(segment, marker_offset, Marker::Prf)?,
                marker_offset,
                Marker::Prf,
                "codestream main header contains more than one PRF marker",
            )?,
            Marker::Cpf => set_once(
                &mut corresponding_profile,
                parse_corresponding_profile(segment, marker_offset)?,
                marker_offset,
                Marker::Cpf,
                "codestream main header contains more than one CPF marker",
            )?,
            Marker::Sot => {
                let mut tile = parse_sot(segment, marker_offset)?;
                offset = data_offset
                    .checked_add(data_len)
                    .ok_or(CodestreamError::SizeOverflow)?;
                offset = retain_tile_part_header_markers(input, offset, &mut markers)?;
                let payload_len =
                    tile_payload_len(input, marker_offset, offset, tile.tile_part_length)?;
                tile.payload_offset = Some(offset);
                tile.payload_len = Some(payload_len);
                tiles.push(tile);
                saw_payload_boundary = true;
                if tile.tile_part_length.is_none() {
                    break;
                }
                offset = offset
                    .checked_add(payload_len)
                    .ok_or(CodestreamError::SizeOverflow)?;
                continue;
            }
            _ => {}
        }

        offset = data_offset
            .checked_add(data_len)
            .ok_or(CodestreamError::SizeOverflow)?;
    }

    let siz = siz.ok_or(CodestreamError::InvalidMarker {
        offset: None,
        marker: Some(Marker::Siz),
        message: "codestream main header must contain SIZ marker",
    })?;
    validate_siz(&siz)?;
    let selected_via_tlm = tile_part_lengths_override.is_some();
    let tile_part_lengths = match tile_part_lengths_override {
        Some(table) => Some(table),
        None => parse_tile_part_length_table(input, &siz, &markers, &tiles)?,
    };
    if !selected_via_tlm {
        validate_indexed_tile_part_sequence(&siz, &tiles)?;
        parse_work.tile_part_order = tiles
            .iter()
            .map(|tile| TilePartOrderEntry {
                tile_index: tile.tile_index,
                tile_part_index: tile.tile_part_index,
                payload_len: tile.payload_len,
            })
            .collect();
    }
    let main_header_end = markers
        .iter()
        .find(|segment| segment.marker == Marker::Sot)
        .map_or(input.len(), |segment| segment.offset);
    let kind = validate_main_header_signalling(
        &siz,
        capability.as_ref(),
        profile.as_ref(),
        corresponding_profile.as_ref(),
        &markers,
    )?;
    if kind == CodestreamKind::Htj2k
        && let Some(coding_style) = &mut coding_style
    {
        coding_style.entropy_coder = EntropyCoder::HtBlockCoding;
    }
    let header_state = resolve_effective_header_state(input, &siz, kind, &markers)?;
    validate_part15_capability_constraints(
        input,
        &markers,
        &siz,
        capability.as_ref(),
        &header_state,
    )?;
    let component_coding_styles =
        parse_main_component_coding_styles(input, &siz, coding_style, &markers, main_header_end)?;
    let progression = ProgressionState {
        order: coding_style.map(|cod| cod.progression_order),
        layers: coding_style.map(|cod| cod.layers),
        next_packet: PacketCursor::default(),
    };

    if !saw_payload_boundary && input.last().copied() != Some(0xd9) {
        return Err(invalid(
            None,
            None,
            "codestream ended before SOT, SOD, or EOC marker",
        ));
    }

    Ok((
        Codestream {
            kind,
            siz,
            coding_style,
            component_coding_styles,
            capability,
            profile,
            corresponding_profile,
            tile_part_lengths,
            markers,
            tiles,
            progression,
        },
        parse_work,
    ))
}

struct SelectedTilePartParse {
    markers: Vec<MarkerSegment>,
    tiles: Vec<TilePartState>,
    tile_part_lengths: TilePartLengthTable,
    work: TilePartParseWork,
}

fn parse_selected_tile_parts_from_tlm(
    input: &[u8],
    siz: &SizMarker,
    main_header_markers: &[MarkerSegment],
    first_sot_offset: usize,
    selected_region: TileRegionRequest,
) -> Result<Option<SelectedTilePartParse>> {
    let Some(declared) =
        parse_declared_tile_part_lengths(input, siz, main_header_markers, first_sot_offset)?
    else {
        return Ok(None);
    };
    let tile_count = siz
        .tile_count_x()?
        .checked_mul(siz.tile_count_y()?)
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut selected_tiles = alloc::vec![false; usize::try_from(tile_count)
        .map_err(|_| CodestreamError::SizeOverflow)?];
    let mut selected_tile_count = 0_usize;
    for tile in tile_rects_for_siz(siz)? {
        if tile_intersects_region(tile, selected_region) {
            let selected = selected_tiles
                .get_mut(usize::from(tile.tile_index))
                .ok_or(CodestreamError::SizeOverflow)?;
            selected_tile_count += usize::from(!*selected);
            *selected = true;
        }
    }
    if selected_tile_count == 0 {
        return Ok(None);
    }

    let mut offset = first_sot_offset;
    let mut entries = Vec::with_capacity(declared.len());
    let mut markers = Vec::new();
    let mut tiles = Vec::new();
    let mut observed_sots = Vec::with_capacity(declared.len());
    let mut work = TilePartParseWork::default();
    for declared in &declared {
        if read_marker(input, offset)? != Marker::Sot {
            return Err(invalid(
                Some(declared.marker_offset),
                Some(Marker::Tlm),
                "TLM tile-part offset does not point to SOT",
            ));
        }
        let segment_len = usize::from(read_u16(input, offset + 2)?);
        if segment_len != 10 {
            return Err(invalid(
                Some(offset),
                Some(Marker::Sot),
                "SOT marker segment length must be ten bytes",
            ));
        }
        let data_offset = offset.checked_add(4).ok_or(CodestreamError::SizeOverflow)?;
        let segment = checked_slice(input, data_offset, 8)?;
        let mut tile = parse_sot(segment, offset)?;
        if tile.tile_index != declared.tile_index {
            return Err(invalid(
                Some(declared.marker_offset),
                Some(Marker::Tlm),
                "TLM tile index disagrees with SOT Isot",
            ));
        }
        let Some(psot) = tile.tile_part_length else {
            return Ok(None);
        };
        if psot != declared.tile_part_length {
            return Err(invalid(
                Some(declared.marker_offset),
                Some(Marker::Tlm),
                "TLM tile-part length disagrees with SOT Psot",
            ));
        }
        let tile_part_len = usize::try_from(psot).map_err(|_| CodestreamError::SizeOverflow)?;
        require(input, offset, tile_part_len)?;
        observed_sots.push(tile);
        entries.push(TilePartLengthEntry {
            tile_index: declared.tile_index,
            tile_part_length: declared.tile_part_length,
            sot_offset: offset,
            marker_offset: declared.marker_offset,
        });

        if selected_tiles
            .get(usize::from(tile.tile_index))
            .copied()
            .unwrap_or(false)
        {
            markers.push(MarkerSegment {
                marker: Marker::Sot,
                offset,
                data_offset,
                data_len: 8,
            });
            let payload_offset = retain_tile_part_header_markers(
                input,
                data_offset
                    .checked_add(8)
                    .ok_or(CodestreamError::SizeOverflow)?,
                &mut markers,
            )?;
            let tile_part_end = offset
                .checked_add(tile_part_len)
                .ok_or(CodestreamError::SizeOverflow)?;
            if payload_offset > tile_part_end {
                return Err(invalid(
                    Some(offset),
                    Some(Marker::Sot),
                    "SOT tile-part length ends before selected SOD payload",
                ));
            }
            tile.payload_offset = Some(payload_offset);
            tile.payload_len = Some(tile_part_end - payload_offset);
            work.tile_part_order.push(TilePartOrderEntry {
                tile_index: tile.tile_index,
                tile_part_index: tile.tile_part_index,
                payload_len: tile.payload_len,
            });
            tiles.push(tile);
        } else {
            work.tile_part_order.push(TilePartOrderEntry {
                tile_index: tile.tile_index,
                tile_part_index: tile.tile_part_index,
                payload_len: None,
            });
            work.tile_parts_skipped_via_tlm = work.tile_parts_skipped_via_tlm.saturating_add(1);
            work.tile_part_bytes_skipped_via_tlm = work
                .tile_part_bytes_skipped_via_tlm
                .saturating_add(u64::from(psot));
        }
        offset = offset
            .checked_add(tile_part_len)
            .ok_or(CodestreamError::SizeOverflow)?;
    }

    if read_marker(input, offset)? != Marker::Eoc {
        return Ok(None);
    }
    validate_indexed_tile_part_sequence(siz, &observed_sots)?;
    markers.push(MarkerSegment {
        marker: Marker::Eoc,
        offset,
        data_offset: offset + 2,
        data_len: 0,
    });
    Ok(Some(SelectedTilePartParse {
        markers,
        tiles,
        tile_part_lengths: TilePartLengthTable {
            entries,
            fully_covers_codestream: true,
        },
        work,
    }))
}

fn validate_indexed_tile_part_sequence(siz: &SizMarker, tiles: &[TilePartState]) -> Result<()> {
    let tile_count = siz
        .tile_count_x()?
        .checked_mul(siz.tile_count_y()?)
        .ok_or(CodestreamError::SizeOverflow)?;
    #[derive(Clone, Copy, Default)]
    struct TilePartSequenceState {
        observed: usize,
        declared_total: Option<u8>,
    }

    let mut states = BTreeMap::<u16, TilePartSequenceState>::new();
    for tile in tiles {
        if u32::from(tile.tile_index) >= tile_count {
            return Err(invalid(
                None,
                Some(Marker::Sot),
                "SOT tile index is outside the SIZ tile grid",
            ));
        }
        let state = states.entry(tile.tile_index).or_default();
        if usize::from(tile.tile_part_index) != state.observed {
            return Err(invalid(
                None,
                Some(Marker::Sot),
                "SOT tile parts require dense TPsot values per tile",
            ));
        }
        state.observed = state
            .observed
            .checked_add(1)
            .ok_or(CodestreamError::SizeOverflow)?;
        if let Some(count) = tile.tile_part_count {
            if state
                .declared_total
                .is_some_and(|declared| declared != count)
            {
                return Err(invalid(
                    None,
                    Some(Marker::Sot),
                    "SOT TNsot must be consistent for every tile part",
                ));
            }
            state.declared_total = Some(count);
        }
    }

    if u32::try_from(states.len()).map_err(|_| CodestreamError::SizeOverflow)? != tile_count {
        return Err(invalid(
            None,
            Some(Marker::Sot),
            "codestream must contain at least one tile part for every SIZ tile",
        ));
    }
    for state in states.into_values() {
        if state
            .declared_total
            .is_some_and(|count| usize::from(count) != state.observed)
        {
            return Err(invalid(
                None,
                Some(Marker::Sot),
                "SOT TNsot must match the observed tile-part count",
            ));
        }
    }
    Ok(())
}

fn tile_intersects_region(tile: TileRect, region: TileRegionRequest) -> bool {
    let Some(region_end_x) = region.x.checked_add(region.width) else {
        return false;
    };
    let Some(region_end_y) = region.y.checked_add(region.height) else {
        return false;
    };
    let Some(tile_end_x) = tile.x.checked_add(tile.width) else {
        return false;
    };
    let Some(tile_end_y) = tile.y.checked_add(tile.height) else {
        return false;
    };
    region.width != 0
        && region.height != 0
        && region.x < tile_end_x
        && tile.x < region_end_x
        && region.y < tile_end_y
        && tile.y < region_end_y
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct DeclaredTilePartLength {
    tile_index: u16,
    tile_part_length: u32,
    marker_offset: usize,
}

fn parse_declared_tile_part_lengths(
    input: &[u8],
    siz: &SizMarker,
    markers: &[MarkerSegment],
    main_header_end: usize,
) -> Result<Option<Vec<DeclaredTilePartLength>>> {
    let tlm_segments = markers
        .iter()
        .filter(|segment| segment.marker == Marker::Tlm && segment.offset < main_header_end)
        .collect::<Vec<_>>();
    if tlm_segments.is_empty() {
        return Ok(None);
    }

    let tile_count = siz
        .tile_count_x()?
        .checked_mul(siz.tile_count_y()?)
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut declared = Vec::new();
    for (expected_index, marker) in tlm_segments.iter().enumerate() {
        let data = checked_slice(input, marker.data_offset, marker.data_len)?;
        if data.len() < 2 {
            return Err(invalid(
                Some(marker.offset),
                Some(Marker::Tlm),
                "TLM marker payload must contain Ztlm and Stlm",
            ));
        }
        if usize::from(data[0]) != expected_index {
            return Err(invalid(
                Some(marker.offset),
                Some(Marker::Tlm),
                "TLM marker indexes must start at zero and increase consecutively",
            ));
        }
        let stlm = data[1];
        if stlm & !0x70 != 0 {
            return Err(invalid(
                Some(marker.offset),
                Some(Marker::Tlm),
                "TLM Stlm reserved bits must be zero",
            ));
        }
        let tile_index_bytes = usize::from((stlm >> 4) & 0x03);
        if tile_index_bytes == 3 {
            return Err(invalid(
                Some(marker.offset),
                Some(Marker::Tlm),
                "TLM Stlm tile-index width three is reserved",
            ));
        }
        let tile_part_length_bytes = if stlm & 0x40 == 0 { 2 } else { 4 };
        let entry_len = tile_index_bytes
            .checked_add(tile_part_length_bytes)
            .ok_or(CodestreamError::SizeOverflow)?;
        let entries = &data[2..];
        if entries.is_empty() || entries.len() % entry_len != 0 {
            return Err(invalid(
                Some(marker.offset),
                Some(Marker::Tlm),
                "TLM entry bytes must contain complete tile/length records",
            ));
        }

        for entry in entries.chunks_exact(entry_len) {
            let tile_index = match tile_index_bytes {
                0 => u32::try_from(declared.len()).map_err(|_| CodestreamError::SizeOverflow)?,
                1 => u32::from(entry[0]),
                2 => u32::from(read_u16(entry, 0)?),
                _ => return Err(CodestreamError::SizeOverflow),
            };
            if tile_index >= tile_count || tile_index > u32::from(u16::MAX) {
                return Err(invalid(
                    Some(marker.offset),
                    Some(Marker::Tlm),
                    "TLM tile index is outside the SIZ tile grid",
                ));
            }
            let length_offset = tile_index_bytes;
            let tile_part_length = if tile_part_length_bytes == 2 {
                u32::from(read_u16(entry, length_offset)?)
            } else {
                read_u32(entry, length_offset)?
            };
            if tile_part_length < 14 {
                return Err(invalid(
                    Some(marker.offset),
                    Some(Marker::Tlm),
                    "TLM tile-part length is shorter than SOT and SOD syntax",
                ));
            }
            declared.push(DeclaredTilePartLength {
                tile_index: u16::try_from(tile_index).map_err(|_| CodestreamError::SizeOverflow)?,
                tile_part_length,
                marker_offset: marker.offset,
            });
        }
    }

    Ok(Some(declared))
}

fn parse_tile_part_length_table(
    input: &[u8],
    siz: &SizMarker,
    markers: &[MarkerSegment],
    tiles: &[TilePartState],
) -> Result<Option<TilePartLengthTable>> {
    let first_sot_offset = markers
        .iter()
        .find(|segment| segment.marker == Marker::Sot)
        .map_or(input.len(), |segment| segment.offset);
    let Some(declared) = parse_declared_tile_part_lengths(input, siz, markers, first_sot_offset)?
    else {
        return Ok(None);
    };

    let sot_markers = markers
        .iter()
        .filter(|segment| segment.marker == Marker::Sot)
        .collect::<Vec<_>>();
    if declared.len() > tiles.len() || sot_markers.len() != tiles.len() {
        return Err(invalid(
            declared.first().map(|entry| entry.marker_offset),
            Some(Marker::Tlm),
            "TLM contains entries outside the observed tile-part progression",
        ));
    }

    let mut entries: Vec<TilePartLengthEntry> = Vec::with_capacity(declared.len());
    for (entry_index, (declared, tile)) in declared.iter().zip(tiles).enumerate() {
        let sot_offset = sot_markers[entry_index].offset;
        if tile.tile_index != declared.tile_index {
            return Err(invalid(
                Some(declared.marker_offset),
                Some(Marker::Tlm),
                "TLM tile index disagrees with SOT Isot",
            ));
        }
        let observed_length = if let Some(observed) = tile.tile_part_length {
            observed
        } else {
            let tile_part_end = find_marker(
                input,
                tile.payload_offset.ok_or(CodestreamError::SizeOverflow)?,
                Marker::Eoc,
            )
            .ok_or_else(|| {
                invalid(
                    Some(sot_offset),
                    Some(Marker::Tlm),
                    "TLM cannot resolve an open-ended final tile part without EOC",
                )
            })?;
            u32::try_from(
                tile_part_end
                    .checked_sub(sot_offset)
                    .ok_or(CodestreamError::SizeOverflow)?,
            )
            .map_err(|_| CodestreamError::SizeOverflow)?
        };
        if observed_length != declared.tile_part_length {
            return Err(invalid(
                Some(declared.marker_offset),
                Some(Marker::Tlm),
                "TLM tile-part length disagrees with SOT Psot",
            ));
        }
        if let Some(previous) = entries.last() {
            let expected_offset = previous
                .sot_offset
                .checked_add(
                    usize::try_from(previous.tile_part_length)
                        .map_err(|_| CodestreamError::SizeOverflow)?,
                )
                .ok_or(CodestreamError::SizeOverflow)?;
            if sot_offset != expected_offset {
                return Err(invalid(
                    Some(declared.marker_offset),
                    Some(Marker::Tlm),
                    "TLM tile-part lengths do not follow the observed SOT progression",
                ));
            }
        }
        entries.push(TilePartLengthEntry {
            tile_index: declared.tile_index,
            tile_part_length: declared.tile_part_length,
            sot_offset,
            marker_offset: declared.marker_offset,
        });
    }

    let fully_covers_codestream = if entries.len() == tiles.len() {
        let last = entries.last().ok_or(CodestreamError::SizeOverflow)?;
        let eoc_offset = last
            .sot_offset
            .checked_add(
                usize::try_from(last.tile_part_length)
                    .map_err(|_| CodestreamError::SizeOverflow)?,
            )
            .ok_or(CodestreamError::SizeOverflow)?;
        read_marker(input, eoc_offset).map_err(|_| {
            invalid(
                Some(last.marker_offset),
                Some(Marker::Tlm),
                "complete TLM coverage must end at EOC",
            )
        })? == Marker::Eoc
    } else {
        false
    };
    if entries.len() == tiles.len() && !fully_covers_codestream {
        return Err(invalid(
            entries.last().map(|entry| entry.marker_offset),
            Some(Marker::Tlm),
            "complete TLM coverage must end at EOC",
        ));
    }

    Ok(Some(TilePartLengthTable {
        entries,
        fully_covers_codestream,
    }))
}

/// Encode a single-tile unsigned 8-bit grayscale Part 1 codestream using the
/// repo-owned no-decomposition baseline slice.
pub fn encode_grayscale_u8_no_decomp(input: GrayscaleU8Encode<'_>) -> Result<Vec<u8>> {
    validate_grayscale_u8_encode(input)?;
    let component = level_shift_grayscale_component(input)?;
    encode_native_no_decomp(NativeNoDecompEncode {
        width: input.width,
        height: input.height,
        bits_per_sample: 8,
        components: &[component],
        multiple_component_transform: false,
    })
}

/// Build a deterministic planar unsigned 8-bit fixture for cross-crate
/// component-selection tests.
///
/// This is not a general encode API. It deliberately exposes the existing
/// no-decomposition test profile so higher API layers can verify component
/// counts that image-oriented grayscale/RGB encoders cannot express.
#[doc(hidden)]
pub fn encode_planar_u8_no_decomp_test_fixture(
    width: u32,
    height: u32,
    component_planes: &[&[u8]],
) -> Result<Vec<u8>> {
    if component_planes.is_empty() || component_planes.len() > usize::from(u8::MAX) {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "planar test fixture requires one to 255 components",
        ));
    }
    let sample_count = checked_component_sample_count(width, height)?;
    let components = component_planes
        .iter()
        .map(|samples| {
            if samples.len() != sample_count {
                return Err(CodestreamError::SizeOverflow);
            }
            Ok(NativeNoDecompComponent {
                coefficients: samples
                    .iter()
                    .map(|sample| i32::from(*sample) - 128)
                    .collect(),
                available_bitplanes: 8,
            })
        })
        .collect::<Result<Vec<_>>>()?;
    encode_native_no_decomp(NativeNoDecompEncode {
        width,
        height,
        bits_per_sample: 8,
        components: &components,
        multiple_component_transform: false,
    })
}

/// One project-authored native component plane for a deterministic subsampled
/// Part 1 test fixture.
#[doc(hidden)]
pub struct SubsampledU8TestComponent<'a> {
    pub horizontal_separation: u8,
    pub vertical_separation: u8,
    pub samples: &'a [u8],
}

/// Build a deterministic raw Part 1 fixture whose component planes use their
/// declared native sampling grids.
///
/// This is test support rather than a general encoder surface.
#[doc(hidden)]
pub fn encode_planar_u8_subsampled_no_decomp_test_fixture(
    reference_width: u32,
    reference_height: u32,
    component_planes: &[SubsampledU8TestComponent<'_>],
) -> Result<Vec<u8>> {
    if component_planes.is_empty() || component_planes.len() > usize::from(u8::MAX) {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "subsampled planar test fixture requires one to 255 components",
        ));
    }
    let components = component_planes
        .iter()
        .map(|component| {
            if component.horizontal_separation == 0 || component.vertical_separation == 0 {
                return Err(CodestreamError::SizeOverflow);
            }
            let width = reference_width.div_ceil(u32::from(component.horizontal_separation));
            let height = reference_height.div_ceil(u32::from(component.vertical_separation));
            let sample_count = checked_component_sample_count(width, height)?;
            if component.samples.len() != sample_count {
                return Err(CodestreamError::SizeOverflow);
            }
            Ok((
                width,
                height,
                NativeNoDecompComponent {
                    coefficients: component
                        .samples
                        .iter()
                        .map(|sample| i32::from(*sample) - 128)
                        .collect(),
                    available_bitplanes: 8,
                },
            ))
        })
        .collect::<Result<Vec<_>>>()?;

    let mut segments = Vec::new();
    let mut encoded = Vec::with_capacity(components.len());
    let mut tier1_encode_scratch = tier1::CodeBlockEncodeScratch::new();
    for (width, height, component) in &components {
        let cols =
            u16::try_from(ceil_div(*width, 64)?).map_err(|_| CodestreamError::SizeOverflow)?;
        let rows =
            u16::try_from(ceil_div(*height, 64)?).map_err(|_| CodestreamError::SizeOverflow)?;
        let blocks = encode_no_decomp_component_blocks(
            *width,
            *height,
            component,
            cols,
            rows,
            &mut segments,
            &mut tier1_encode_scratch,
        )?;
        encoded.push((cols, rows, blocks));
    }

    let mut packet = Vec::new();
    for (cols, rows, blocks) in &encoded {
        write_native_no_decomp_packets(
            &mut packet,
            *cols,
            *rows,
            core::slice::from_ref(blocks),
            &segments,
        )?;
    }
    let mut codestream = Vec::new();
    write_native_part1_main_header(
        &mut codestream,
        reference_width,
        reference_height,
        reference_width,
        reference_height,
        8,
        u16::try_from(component_planes.len()).map_err(|_| CodestreamError::SizeOverflow)?,
        false,
        0,
        &[8],
    )?;
    let siz = find_marker(&codestream, 0, Marker::Siz).ok_or(CodestreamError::SizeOverflow)?;
    for (index, component) in component_planes.iter().enumerate() {
        let entry = siz
            .checked_add(40)
            .and_then(|offset| offset.checked_add(index.checked_mul(3)?))
            .ok_or(CodestreamError::SizeOverflow)?;
        *codestream
            .get_mut(entry + 1)
            .ok_or(CodestreamError::SizeOverflow)? = component.horizontal_separation;
        *codestream
            .get_mut(entry + 2)
            .ok_or(CodestreamError::SizeOverflow)? = component.vertical_separation;
    }
    write_tile_part(&mut codestream, 0, &packet, true)?;
    Ok(codestream)
}

