fn encode_planar_u8_subsampled_decomp_test_fixture(
    reference_width: u32,
    reference_height: u32,
    component_planes: &[SubsampledU8TestComponent<'_>],
    decomposition_levels: u8,
) -> Result<Vec<u8>> {
    if !matches!(decomposition_levels, 1 | 2) {
        return Err(CodestreamError::SizeOverflow);
    }
    if component_planes.is_empty() || component_planes.len() > usize::from(u8::MAX) {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "subsampled planar test fixture requires one to 255 components",
        ));
    }

    let mut components = Vec::with_capacity(component_planes.len());
    for component in component_planes {
        if component.horizontal_separation == 0 || component.vertical_separation == 0 {
            return Err(CodestreamError::SizeOverflow);
        }
        let width = reference_width.div_ceil(u32::from(component.horizontal_separation));
        let height = reference_height.div_ceil(u32::from(component.vertical_separation));
        let sample_count = checked_component_sample_count(width, height)?;
        if component.samples.len() != sample_count {
            return Err(CodestreamError::SizeOverflow);
        }
        let mut coefficients = component
            .samples
            .iter()
            .map(|sample| i32::from(*sample) - 128)
            .collect::<Vec<_>>();
        forward_reversible_5_3_levels(
            width,
            height,
            &mut coefficients,
            decomposition_levels,
            "subsampled test fixture forward transform failed",
        )?;
        components.push((width, height, coefficients));
    }

    let exponent_count = 1_usize
        .checked_add(
            usize::from(decomposition_levels)
                .checked_mul(3)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut qcd_exponents = alloc::vec![1_u8; exponent_count];
    for (width, height, coefficients) in &components {
        for spec in decomp_subband_specs(*width, *height, decomposition_levels)? {
            let exponent = subband_available_bitplanes(
                *width,
                coefficients,
                spec.x,
                spec.y,
                spec.width,
                spec.height,
            )?;
            let output = qcd_exponents
                .get_mut(usize::from(spec.index))
                .ok_or(CodestreamError::SizeOverflow)?;
            *output = (*output).max(exponent);
        }
    }

    let mut segments = Vec::new();
    let mut component_subbands = Vec::with_capacity(components.len());
    let mut tier1_encode_scratch = tier1::CodeBlockEncodeScratch::new();
    for (width, height, coefficients) in &components {
        let mut subbands = Vec::with_capacity(exponent_count);
        for spec in decomp_subband_specs(*width, *height, decomposition_levels)? {
            let available_bitplanes = *qcd_exponents
                .get(usize::from(spec.index))
                .ok_or(CodestreamError::SizeOverflow)?;
            subbands.push(encode_decomp_subband(
                *width,
                coefficients,
                spec,
                available_bitplanes,
                &mut segments,
                &mut tier1_encode_scratch,
            )?);
        }
        component_subbands.push(subbands);
    }

    let mut packet = Vec::with_capacity(native_decomp_packet_capacity_hint(
        &component_subbands,
        &segments,
    )?);
    write_native_decomp_packets(
        &mut packet,
        decomposition_levels,
        &component_subbands,
        &segments,
    )?;

    let mut codestream = Vec::with_capacity(native_single_tile_codestream_capacity_hint(
        packet.len(),
        component_planes.len(),
        qcd_exponents.len(),
    )?);
    write_native_part1_main_header(
        &mut codestream,
        reference_width,
        reference_height,
        reference_width,
        reference_height,
        8,
        u16::try_from(component_planes.len()).map_err(|_| CodestreamError::SizeOverflow)?,
        false,
        decomposition_levels,
        &qcd_exponents,
    )?;
    let siz = find_marker(&codestream, 0, Marker::Siz).ok_or(CodestreamError::SizeOverflow)?;
    for (index, component) in component_planes.iter().enumerate() {
        let entry = siz
            .checked_add(40)
            .and_then(|offset| offset.checked_add(index.checked_mul(3)?))
            .ok_or(CodestreamError::SizeOverflow)?;
        *codestream
            .get_mut(entry + 1)
            .ok_or(CodestreamError::SizeOverflow)? = component.horizontal_separation;
        *codestream
            .get_mut(entry + 2)
            .ok_or(CodestreamError::SizeOverflow)? = component.vertical_separation;
    }
    write_tile_part(&mut codestream, 0, &packet, true)?;
    Ok(codestream)
}

#[cfg(test)]
#[test]
fn subsampled_reduced_window_matches_forced_full_synthesis_oracle() {
    let sampling = [(1_u8, 1_u8), (2, 1), (2, 2)];
    let planes = sampling
        .iter()
        .enumerate()
        .map(|(component, (horizontal, vertical))| {
            let width = 257_u32.div_ceil(u32::from(*horizontal));
            let height = 131_u32.div_ceil(u32::from(*vertical));
            (0..width * height)
                .map(|sample| ((sample * (17 + component as u32 * 8) + 31) % 251) as u8)
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>();
    let components = planes
        .iter()
        .zip(sampling)
        .map(
            |(samples, (horizontal_separation, vertical_separation))| SubsampledU8TestComponent {
                horizontal_separation,
                vertical_separation,
                samples,
            },
        )
        .collect::<Vec<_>>();
    let fixture =
        encode_planar_u8_subsampled_one_decomp_test_fixture(257, 131, &components).unwrap();
    let component_indices = [0_u16, 1, 2];
    let request = Part1ComponentDecodeRequest {
        component_indices: &component_indices,
        region: TileRegionRequest {
            x: 64,
            y: 32,
            width: 128,
            height: 64,
        },
        discard_levels: 1,
        max_layers: Some(1),
    };

    let execute = |prepared: &PreparedPart1ComponentDecode<'_>| {
        let mut buffers = prepared
            .component_outputs()
            .iter()
            .map(|output| vec![0_u8; usize::try_from(output.width * output.height).unwrap()])
            .collect::<Vec<_>>();
        let mut output_planes = buffers
            .iter_mut()
            .zip(prepared.component_outputs())
            .map(|(samples, output)| ComponentPlaneMut {
                samples,
                stride_bytes: usize::try_from(output.width).unwrap(),
            })
            .collect::<Vec<_>>();
        let timings = execute_prepared_part1_component_decode_into_with_workspace_and_options(
            prepared,
            &mut output_planes,
            &mut Part1ComponentDecodeWorkspace::new(),
            PreparedPart1ExecutionOptions {
                instrumentation: DecodeInstrumentation::WorkCounters,
                parallelism: DecodeExecutionParallelism::Serial,
                ..PreparedPart1ExecutionOptions::default()
            },
        )
        .unwrap();
        (buffers, timings)
    };

    let bounded = prepare_part1_component_decode(&fixture, request).unwrap();
    let (bounded_buffers, bounded_work) = execute(&bounded);
    let mut oracle = prepare_part1_component_decode(&fixture, request).unwrap();
    oracle.force_full_synthesis_oracle();
    let (oracle_buffers, oracle_work) = execute(&oracle);
    assert_eq!(bounded_buffers, oracle_buffers);
    assert!(bounded_work.executed_code_blocks < oracle_work.executed_code_blocks);
    assert_eq!(bounded_work.full_output_allocation_bytes, 0);
}

#[cfg(test)]
#[test]
fn reserved_parameterless_markers_are_skipped_in_main_and_tile_headers() {
    let samples = (0_u8..16).collect::<Vec<_>>();
    let mut codestream =
        encode_planar_u8_no_decomp_test_fixture(4, 4, &[&samples]).expect("fixture encodes");
    let sot = find_marker(&codestream, 0, Marker::Sot).expect("fixture has SOT");
    codestream.splice(sot..sot, [0xff, 0x30]);

    let shifted_sot = sot + 2;
    let sod = find_marker(&codestream, shifted_sot, Marker::Sod).expect("fixture has SOD");
    codestream.splice(sod..sod, [0xff, 0x3f]);
    let psot = read_u32(&codestream, shifted_sot + 6).expect("fixture has Psot");
    codestream[shifted_sot + 6..shifted_sot + 10].copy_from_slice(&(psot + 2).to_be_bytes());

    let parsed = parse(&codestream).expect("slice parser skips reserved markers");
    let reserved = parsed
        .markers
        .iter()
        .filter(|segment| segment.marker.is_reserved_parameterless())
        .collect::<Vec<_>>();
    assert_eq!(reserved.len(), 2);
    assert!(reserved.iter().all(|segment| segment.data_len == 0));
    assert!(is_supported_no_decomposition_encode_compatible_profile(
        &parsed
    ));

    let source = source::SliceSource::new(&codestream);
    let components = [0_u16];
    let prepared = prepare_part1_component_decode_from_source(
        &source,
        Part1ComponentDecodeRequest {
            component_indices: &components,
            region: TileRegionRequest {
                x: 0,
                y: 0,
                width: 4,
                height: 4,
            },
            discard_levels: 0,
            max_layers: None,
        },
    )
    .expect("source parser skips reserved markers");
    assert_eq!(prepared.output_dimensions(), (4, 4));
}

/// Build a deterministic no-decomposition CPRL fixture with a 2x2 grid of
/// 64x64 precincts.
///
/// This is test infrastructure for packet-grid interoperability, not a public
/// general-purpose precinct encoder.
#[doc(hidden)]
pub fn encode_grayscale_u8_cprl_precinct_test_fixture(
    input: GrayscaleU8Encode<'_>,
) -> Result<Vec<u8>> {
    validate_grayscale_u8_encode(input)?;
    if input.width != 128 || input.height != 128 {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "CPRL precinct test fixture requires an exact 128x128 image",
        ));
    }
    let component = level_shift_grayscale_component(input)?;
    let mut segments = Vec::new();
    let mut scratch = tier1::CodeBlockEncodeScratch::new();
    let code_blocks = encode_no_decomp_component_blocks(
        input.width,
        input.height,
        &component,
        2,
        2,
        &mut segments,
        &mut scratch,
    )?;
    if code_blocks.len() != 4 {
        return Err(CodestreamError::SizeOverflow);
    }

    let mut packets = Vec::new();
    for block in code_blocks {
        let mut local_block = block;
        local_block.x = 0;
        local_block.y = 0;
        let mut writer = PacketBitWriter::new();
        writer.write_bit(u32::from(local_block.included))?;
        if local_block.included {
            write_component_packet_header(&mut writer, 1, 1, core::slice::from_ref(&local_block))?;
        }
        writer.align();
        packets.extend_from_slice(writer.bytes());
        if local_block.included {
            packets.extend_from_slice(checked_slice(
                &segments,
                local_block.segment_offset,
                local_block.segment_len,
            )?);
        }
    }

    let mut codestream = Vec::new();
    write_native_part1_main_header(
        &mut codestream,
        input.width,
        input.height,
        input.width,
        input.height,
        8,
        1,
        false,
        0,
        &[8],
    )?;
    let cod = codestream
        .windows(2)
        .position(|bytes| bytes == [0xff, 0x52])
        .ok_or(CodestreamError::SizeOverflow)?;
    let segment_len = u16::from_be_bytes([codestream[cod + 2], codestream[cod + 3]]);
    codestream[cod + 2..cod + 4].copy_from_slice(
        &segment_len
            .checked_add(1)
            .ok_or(CodestreamError::SizeOverflow)?
            .to_be_bytes(),
    );
    codestream[cod + 4] |= 0x01;
    codestream[cod + 5] = 4;
    codestream.insert(cod + 2 + usize::from(segment_len), 0x66);
    write_tile_part(&mut codestream, 0, &packets, true)?;
    Ok(codestream)
}

/// Build a deterministic one-decomposition CPRL fixture whose two resolution
/// levels share a 2x2 precinct lattice in the image reference grid.
///
/// This is test infrastructure for decomposed packet-grid interoperability,
/// not a public general-purpose precinct encoder.
#[doc(hidden)]
pub fn encode_grayscale_u8_one_decomp_cprl_precinct_test_fixture(
    input: GrayscaleU8Encode<'_>,
) -> Result<Vec<u8>> {
    validate_grayscale_u8_encode(input)?;
    if input.width != 256 || input.height != 192 {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "decomposed CPRL precinct test fixture requires an exact 256x192 image",
        ));
    }

    let mut coefficients = level_shift_grayscale_plane(input)?;
    forward_reversible_5_3_levels(
        input.width,
        input.height,
        &mut coefficients,
        1,
        "forward reversible 5/3 transform failed for decomposed CPRL test fixture",
    )?;
    let subband_specs = decomp_subband_specs(input.width, input.height, 1)?;
    let component_planes = [coefficients.as_slice()];
    let qcd_exponents = subband_specs
        .iter()
        .map(|spec| {
            max_component_subband_available_bitplanes(input.width, &component_planes, *spec)
        })
        .collect::<Result<Vec<_>>>()?;
    let mut segments = Vec::new();
    let mut component_subbands = Vec::new();
    encode_decomp_components_sequential(
        input.width,
        &component_planes,
        &subband_specs,
        &qcd_exponents,
        &mut component_subbands,
        &mut segments,
    )?;
    let subbands = component_subbands
        .first()
        .ok_or(CodestreamError::SizeOverflow)?;
    if subbands.iter().any(|subband| {
        subband.code_block_cols != 2
            || subband.code_block_rows != 2
            || subband.code_blocks.len() != 4
    }) {
        return Err(CodestreamError::SizeOverflow);
    }

    let mut packets = Vec::new();
    for precinct in 0..4_u16 {
        let precinct_x = precinct % 2;
        let precinct_y = precinct / 2;
        for resolution in 0..=1 {
            let packet_subbands = subbands
                .iter()
                .filter(|subband| subband.resolution == resolution)
                .collect::<Vec<_>>();
            let mut local_blocks = Vec::with_capacity(packet_subbands.len());
            for subband in &packet_subbands {
                let block_index = usize::from(precinct_y)
                    .checked_mul(usize::from(subband.code_block_cols))
                    .and_then(|offset| offset.checked_add(usize::from(precinct_x)))
                    .ok_or(CodestreamError::SizeOverflow)?;
                let mut block = subband
                    .code_blocks
                    .get(block_index)
                    .cloned()
                    .ok_or(CodestreamError::SizeOverflow)?;
                block.x = 0;
                block.y = 0;
                local_blocks.push(block);
            }

            let has_contribution = local_blocks.iter().any(|block| block.included);
            let mut writer = PacketBitWriter::new();
            writer.write_bit(u32::from(has_contribution))?;
            if has_contribution {
                for block in &local_blocks {
                    write_component_packet_header(&mut writer, 1, 1, core::slice::from_ref(block))?;
                }
            }
            writer.align();
            packets.extend_from_slice(writer.bytes());
            for block in local_blocks.iter().filter(|block| block.included) {
                packets.extend_from_slice(checked_slice(
                    &segments,
                    block.segment_offset,
                    block.segment_len,
                )?);
            }
        }
    }

    let mut codestream = Vec::new();
    write_native_part1_main_header(
        &mut codestream,
        input.width,
        input.height,
        input.width,
        input.height,
        8,
        1,
        false,
        1,
        &qcd_exponents,
    )?;
    let cod = codestream
        .windows(2)
        .position(|bytes| bytes == [0xff, 0x52])
        .ok_or(CodestreamError::SizeOverflow)?;
    let segment_len = u16::from_be_bytes([codestream[cod + 2], codestream[cod + 3]]);
    codestream[cod + 2..cod + 4].copy_from_slice(
        &segment_len
            .checked_add(2)
            .ok_or(CodestreamError::SizeOverflow)?
            .to_be_bytes(),
    );
    codestream[cod + 4] |= 0x01;
    codestream[cod + 5] = 4;
    let precinct_offset = cod
        .checked_add(2 + usize::from(segment_len))
        .ok_or(CodestreamError::SizeOverflow)?;
    codestream.splice(precinct_offset..precinct_offset, [0x66, 0x77]);
    write_tile_part(&mut codestream, 0, &packets, true)?;
    Ok(codestream)
}

