fn prepare_grayscale_u16_le_dwt2_tiles(
    input: GrayscaleU16LeEncode<'_>,
    tile_rects: &[TileRect],
) -> Result<Vec<NativeDecompTile>> {
    #[cfg(feature = "parallel")]
    {
        if should_parallel_decode_tiles(tile_rects, 1) {
            use rayon::prelude::*;

            return tile_rects
                .par_iter()
                .map_init(Vec::new, |transform_scratch, tile_rect| {
                    prepare_grayscale_u16_le_dwt2_tile_with_scratch(
                        input,
                        *tile_rect,
                        transform_scratch,
                    )
                })
                .collect();
        }
    }
    prepare_grayscale_u16_le_dwt2_tiles_sequential(input, tile_rects)
}

fn prepare_grayscale_u16_le_dwt2_tiles_sequential(
    input: GrayscaleU16LeEncode<'_>,
    tile_rects: &[TileRect],
) -> Result<Vec<NativeDecompTile>> {
    let mut transformed_tiles = Vec::with_capacity(tile_rects.len());
    let mut transform_scratch = Vec::new();
    for tile_rect in tile_rects {
        transformed_tiles.push(prepare_grayscale_u16_le_dwt2_tile_with_scratch(
            input,
            *tile_rect,
            &mut transform_scratch,
        )?);
    }
    Ok(transformed_tiles)
}

fn prepare_grayscale_u16_le_dwt2_tile_with_scratch(
    input: GrayscaleU16LeEncode<'_>,
    tile_rect: TileRect,
    transform_scratch: &mut Vec<i32>,
) -> Result<NativeDecompTile> {
    let mut coefficients = level_shift_grayscale_u16_le_tile_plane(input, tile_rect)?;
    forward_reversible_5_3_levels_with_scratch(
        tile_rect.width,
        tile_rect.height,
        &mut coefficients,
        2,
        "forward reversible 5/3 transform failed for native grayscale u16 multi-tile encode",
        transform_scratch,
    )?;
    Ok(NativeDecompTile {
        tile_rect,
        component_planes: alloc::vec![coefficients],
    })
}

