/// transform.
pub fn encode_rgb_u8_no_decomp(input: RgbU8Encode<'_>) -> Result<Vec<u8>> {
    validate_rgb_u8_encode(input)?;
    let components = forward_rct_rgb_components(input)?;
    encode_native_no_decomp(NativeNoDecompEncode {
        width: input.width,
        height: input.height,
        bits_per_sample: 8,
        components: &components,
        multiple_component_transform: true,
    })
}

