/// True when parsed codestream metadata is inside the broader native
/// component-mode multi-tile Part 1 profile used for local performance probes.
pub fn is_supported_native_component_multitile_profile(codestream: &Codestream) -> bool {
    !codestream
        .markers
        .iter()
        .any(|segment| segment.marker == Marker::Poc)
        && validate_supported_native_component_multitile_profile(codestream).is_ok()
}

/// True when bytes and parsed metadata satisfy the bounded main-header POC
/// component profile used by direct selective decode.
///
/// The ordinary metadata-only predicate remains conservative because it
/// cannot validate POC record fields without the marker bytes.
pub fn is_supported_part1_bounded_poc_component_profile(
    input: &[u8],
    codestream: &Codestream,
) -> bool {
    matches!(
        parse_bounded_main_header_poc(input, codestream),
        Ok(Some(_))
    ) && validate_supported_selective_native_component_profile(input, codestream).is_ok()
}

/// True when parsed metadata is inside the bounded native-grid component
/// sampling profile. This profile returns each component at its SIZ-declared
/// grid and does not imply rendered resampling support.
pub fn is_supported_part1_native_subsampled_component_profile(codestream: &Codestream) -> bool {
    validate_supported_native_subsampled_component_profile(codestream).is_ok()
}

/// True when parsed metadata is inside the native high-bit-depth grayscale
/// component profile.
pub fn is_supported_part1_high_bit_depth_component_profile(codestream: &Codestream) -> bool {
    validate_supported_part1_high_bit_depth_component_profile(codestream).is_ok()
}

/// True when parsed metadata is inside the native unsigned 8-bit multi-tile
/// grayscale profile.
pub fn is_supported_part1_multitile_grayscale_profile(codestream: &Codestream) -> bool {
    validate_supported_part1_multitile_grayscale_profile(codestream).is_ok()
}

fn no_decomposition_encode_compatible_unsupported_construct(
    codestream: &Codestream,
) -> Option<(UnsupportedConstruct, String)> {
    if let Some((marker, detail)) = unsupported_part1_profile_marker(codestream, false, false) {
        return Some((
            UnsupportedConstruct::MarkerSegment,
            detail_for_marker(marker, detail),
        ));
    }

    if codestream.kind != CodestreamKind::J2k {
        return Some((
            UnsupportedConstruct::EntropyCoder,
            "encode-compatible decode is limited to JPEG 2000 Part 1 codestreams".into(),
        ));
    }

    let first_component = codestream.siz.components.first()?;
    if first_component.signed || !matches!(first_component.bits_per_sample, 8 | 16) {
        return Some((
            UnsupportedConstruct::SamplePrecision,
            "encode-compatible decode accepts only unsigned 8-bit or unsigned 16-bit component samples"
                .into(),
        ));
    }
    if codestream.siz.components.iter().any(|component| {
        component.signed
            || component.bits_per_sample != first_component.bits_per_sample
            || component.horizontal_separation != 1
            || component.vertical_separation != 1
    }) {
        return Some((
            UnsupportedConstruct::ComponentSampling,
            "encode-compatible decode requires identical unsigned precision and unit sampling for every component"
                .into(),
        ));
    }

    if !matches!(codestream.siz.component_count(), 1 | 3) {
        return Some((
            UnsupportedConstruct::ComponentCount,
            "encode-compatible decode accepts only grayscale or RGB-shaped codestreams".into(),
        ));
    }

    if codestream.siz.tile_count_x().ok()? != 1 || codestream.siz.tile_count_y().ok()? != 1 {
        return Some((
            UnsupportedConstruct::MultipleTiles,
            "encode-compatible decode is limited to the single-tile no-decomposition encoder output"
                .into(),
        ));
    }

    let component_samples = native_part1_profile_component_samples(codestream)?;
    if component_samples == 0 || component_samples > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES {
        return Some((
            UnsupportedConstruct::PacketDecode,
            "encode-compatible decode is guarded to at most 16 Mi component samples".into(),
        ));
    }

    let Ok(coding_style) = uniform_effective_coding_style(codestream) else {
        return Some((
            UnsupportedConstruct::MarkerSegment,
            "COD and COC markers must resolve before encode-compatible decode support can be classified".into(),
        ));
    };

    if coding_style.entropy_coder != EntropyCoder::ClassicTier1 {
        return Some((
            UnsupportedConstruct::EntropyCoder,
            "encode-compatible decode accepts only classic tier-1 coding".into(),
        ));
    }
    if coding_style.decomposition_levels != 0 {
        return Some((
            UnsupportedConstruct::WaveletTransform,
            "encode-compatible decode is limited to zero-decomposition encoder output".into(),
        ));
    }
    if !default_precinct_progression_order_supported(coding_style.progression_order) {
        return Some((
            UnsupportedConstruct::ProgressionOrder,
            "encode-compatible decode accepts only LRCP/RLCP default-precinct progression".into(),
        ));
    }
    if coding_style.transform != WaveletTransform::Reversible53 {
        return Some((
            UnsupportedConstruct::WaveletTransform,
            "encode-compatible decode accepts only reversible 5/3 lossless coding".into(),
        ));
    }
    if !default_precinct_layer_count_supported(coding_style.layers) {
        return Some((
            UnsupportedConstruct::PacketDecode,
            "encode-compatible decode requires at least one quality layer".into(),
        ));
    }
    if coding_style.sop_markers || coding_style.eph_markers || coding_style.precincts_declared {
        return Some((
            UnsupportedConstruct::MarkerSegment,
            "SOP markers, EPH markers, and explicit precinct tables are outside the encode-compatible profile"
                .into(),
        ));
    }
    if !classic_tier1_code_block_style_supported(coding_style.code_block_style) {
        return Some((
            UnsupportedConstruct::Tier1Decode,
            "encode-compatible decode accepts only combinations of BYPASS, RESET, TERMALL, VSC, PTERM, and SEGSYM code-block styles"
                .into(),
        ));
    }
    if codestream.siz.component_count() == 3 && !coding_style.multiple_component_transform {
        return Some((
            UnsupportedConstruct::Transform,
            "RGB-shaped encode-compatible decode requires COD.mct=1 reversible color transform"
                .into(),
        ));
    }

    match codestream.tiles.as_slice() {
        [tile]
            if tile.tile_part_index == 0
                && !matches!(tile.tile_part_count, Some(count) if count != 1) => {}
        [] => {
            return Some((
                UnsupportedConstruct::MarkerSegment,
                "one tile-part payload is required before encode-compatible decode can run".into(),
            ));
        }
        [_] => {
            return Some((
                UnsupportedConstruct::MarkerSegment,
                "encode-compatible decode requires the first tile-part payload only".into(),
            ));
        }
        _ => {
            return Some((
                UnsupportedConstruct::MarkerSegment,
                "encode-compatible decode requires exactly one tile-part".into(),
            ));
        }
    }

    None
}

fn decomposition_encode_compatible_unsupported_construct(
    codestream: &Codestream,
    expected_decomposition_levels: u8,
    expected_bits_per_sample: u8,
    expected_component_count: Option<u16>,
    expected_mct: Option<bool>,
    profile_name: &'static str,
) -> Option<(UnsupportedConstruct, String)> {
    let level_name = match expected_decomposition_levels {
        1 => "one-decomposition",
        2 => "two-decomposition",
        _ => "decomposition",
    };
    if let Some((marker, detail)) = unsupported_part1_profile_marker(codestream, false, false) {
        return Some((
            UnsupportedConstruct::MarkerSegment,
            detail_for_marker(marker, detail),
        ));
    }

    if codestream.kind != CodestreamKind::J2k {
        return Some((
            UnsupportedConstruct::EntropyCoder,
            alloc::format!(
                "{level_name} encode-compatible decode is limited to JPEG 2000 Part 1 codestreams"
            ),
        ));
    }
    let component_count = codestream.siz.component_count();
    if let Some(expected_component_count) = expected_component_count {
        if component_count != expected_component_count {
            return Some((
                UnsupportedConstruct::ComponentCount,
                alloc::format!(
                    "{level_name} encode-compatible decode accepts only {profile_name} codestreams"
                ),
            ));
        }
    } else if !matches!(component_count, 1 | 3) {
        return Some((
            UnsupportedConstruct::ComponentCount,
            alloc::format!(
                "{level_name} encode-compatible decode accepts only {profile_name} codestreams"
            ),
        ));
    }
    if codestream
        .siz
        .components
        .iter()
        .any(|component| component.bits_per_sample != expected_bits_per_sample || component.signed)
    {
        return Some((
            UnsupportedConstruct::SamplePrecision,
            alloc::format!(
                "{level_name} encode-compatible decode accepts only unsigned {expected_bits_per_sample}-bit samples"
            ),
        ));
    }
    if codestream
        .siz
        .components
        .iter()
        .any(|component| component.horizontal_separation != 1 || component.vertical_separation != 1)
    {
        return Some((
            UnsupportedConstruct::ComponentSampling,
            alloc::format!(
                "{level_name} encode-compatible decode requires unit component sampling"
            ),
        ));
    }
    if codestream.siz.tile_count_x().ok()? != 1 || codestream.siz.tile_count_y().ok()? != 1 {
        return Some((
            UnsupportedConstruct::MultipleTiles,
            alloc::format!(
                "{level_name} encode-compatible decode is limited to single-tile encoder output"
            ),
        ));
    }
    let component_samples = native_part1_profile_component_samples(codestream)?;
    if component_samples == 0 || component_samples > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES {
        return Some((
            UnsupportedConstruct::PacketDecode,
            alloc::format!(
                "{level_name} encode-compatible decode is guarded to at most 16 Mi component samples"
            ),
        ));
    }

    let Ok(coding_style) = uniform_effective_coding_style(codestream) else {
        return Some((
            UnsupportedConstruct::MarkerSegment,
            alloc::format!(
                "COD and COC markers must resolve before {level_name} encode-compatible decode support can be classified"
            ),
        ));
    };
    if coding_style.entropy_coder != EntropyCoder::ClassicTier1 {
        return Some((
            UnsupportedConstruct::EntropyCoder,
            alloc::format!(
                "{level_name} encode-compatible decode accepts only classic tier-1 coding"
            ),
        ));
    }
    if coding_style.decomposition_levels != expected_decomposition_levels {
        return Some((
            UnsupportedConstruct::WaveletTransform,
            alloc::format!(
                "{level_name} encode-compatible decode accepts exactly {expected_decomposition_levels} decomposition level{}",
                if expected_decomposition_levels == 1 {
                    ""
                } else {
                    "s"
                }
            ),
        ));
    }
    if !default_precinct_progression_order_supported(coding_style.progression_order) {
        return Some((
            UnsupportedConstruct::ProgressionOrder,
            alloc::format!(
                "{level_name} encode-compatible decode accepts only LRCP/RLCP default-precinct progression"
            ),
        ));
    }
    if coding_style.transform != WaveletTransform::Reversible53 {
        return Some((
            UnsupportedConstruct::WaveletTransform,
            alloc::format!(
                "{level_name} encode-compatible decode accepts only reversible 5/3 lossless coding"
            ),
        ));
    }
    if !default_precinct_layer_count_supported(coding_style.layers) {
        return Some((
            UnsupportedConstruct::PacketDecode,
            alloc::format!(
                "{level_name} encode-compatible decode requires at least one quality layer"
            ),
        ));
    }
    if coding_style.sop_markers || coding_style.eph_markers || coding_style.precincts_declared {
        return Some((
            UnsupportedConstruct::MarkerSegment,
            alloc::format!(
                "SOP markers, EPH markers, and explicit precinct tables are outside the {level_name} encode-compatible profile"
            ),
        ));
    }
    if !classic_tier1_code_block_style_supported(coding_style.code_block_style) {
        return Some((
            UnsupportedConstruct::Tier1Decode,
            alloc::format!(
                "{level_name} encode-compatible decode accepts only combinations of BYPASS, RESET, TERMALL, VSC, PTERM, and SEGSYM code-block styles"
            ),
        ));
    }
    let requires_mct = expected_mct.unwrap_or(component_count == 3);
    if coding_style.multiple_component_transform != requires_mct {
        return Some((
            UnsupportedConstruct::Transform,
            alloc::format!(
                "{level_name} {profile_name} encode-compatible decode requires COD.mct={}",
                u8::from(requires_mct)
            ),
        ));
    }

    match codestream.tiles.as_slice() {
        [tile]
            if tile.tile_part_index == 0
                && !matches!(tile.tile_part_count, Some(count) if count != 1) => {}
        [] => {
            return Some((
                UnsupportedConstruct::MarkerSegment,
                alloc::format!(
                    "one tile-part payload is required before {level_name} encode-compatible decode can run"
                ),
            ));
        }
        [_] => {
            return Some((
                UnsupportedConstruct::MarkerSegment,
                alloc::format!(
                    "{level_name} encode-compatible decode requires the first tile-part payload only"
                ),
            ));
        }
        _ => {
            return Some((
                UnsupportedConstruct::MarkerSegment,
                alloc::format!(
                    "{level_name} encode-compatible decode requires exactly one tile-part"
                ),
            ));
        }
    }

    None
}

fn native_part1_profile_component_samples(codestream: &Codestream) -> Option<u64> {
    let width = u64::from(codestream.image_width());
    let height = u64::from(codestream.image_height());
    let components = u64::from(codestream.siz.component_count());
    width.checked_mul(height)?.checked_mul(components)
}

fn native_part1_component_grid_samples(codestream: &Codestream) -> Option<u64> {
    codestream
        .siz
        .components
        .iter()
        .try_fold(0_u64, |total, component| {
            let x0 = codestream
                .siz
                .image_origin_x
                .div_ceil(u32::from(component.horizontal_separation));
            let y0 = codestream
                .siz
                .image_origin_y
                .div_ceil(u32::from(component.vertical_separation));
            let x1 = codestream
                .siz
                .reference_grid_width
                .div_ceil(u32::from(component.horizontal_separation));
            let y1 = codestream
                .siz
                .reference_grid_height
                .div_ceil(u32::from(component.vertical_separation));
            let samples =
                u64::from(x1.checked_sub(x0)?).checked_mul(u64::from(y1.checked_sub(y0)?))?;
            total.checked_add(samples)
        })
}

fn validate_irreversible97_zero_origin_aligned_tile_grid(
    codestream: &Codestream,
    coding_style: CodingStyleMarker,
) -> Result<()> {
    if codestream.siz.image_origin_x != 0
        || codestream.siz.image_origin_y != 0
        || codestream.siz.tile_origin_x != 0
        || codestream.siz.tile_origin_y != 0
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::WaveletTransform,
            "irreversible 9/7 decode currently requires zero image and tile origins",
        ));
    }
    let alignment = 1_u32
        .checked_shl(u32::from(coding_style.decomposition_levels))
        .ok_or(CodestreamError::SizeOverflow)?;
    if tile_rects(codestream)?
        .iter()
        .any(|tile| tile.x % alignment != 0 || tile.y % alignment != 0)
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::WaveletTransform,
            "irreversible 9/7 tile origins must align to the full decomposition grid",
        ));
    }
    Ok(())
}

fn validate_supported_part1_reversible53_default_precinct(
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    let encode_compatible = is_supported_no_decomposition_encode_compatible_profile(codestream)
        || is_supported_one_decomposition_encode_compatible_profile(codestream)
        || is_supported_rgb_u8_one_decomposition_encode_compatible_profile(codestream)
        || is_supported_u8_two_decomposition_encode_compatible_profile(codestream)
        || is_supported_grayscale_u16_one_decomposition_encode_compatible_profile(codestream)
        || is_supported_rgb_u16_one_decomposition_encode_compatible_profile(codestream)
        || is_supported_grayscale_u16_two_decomposition_encode_compatible_profile(codestream)
        || is_supported_rgb_u16_two_decomposition_encode_compatible_profile(codestream);

    if !encode_compatible && let Some((construct, _message)) = unsupported_construct(codestream) {
        return Err(unsupported(
            None,
            None,
            construct,
            "codestream is outside the profile-scoped native Part 1 decode subset",
        ));
    }

    uniform_effective_coding_style(codestream)
}

fn validate_supported_part1_irreversible97_default_precinct(
    input: &[u8],
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    if codestream.kind != CodestreamKind::J2k {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::EntropyCoder,
            "irreversible decode is limited to JPEG 2000 Part 1 codestreams",
        ));
    }
    if !matches!(codestream.siz.component_count(), 1 | 3) {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentCount,
            "initial irreversible decode accepts grayscale or three-component MCT rows",
        ));
    }
    if codestream.siz.components.iter().any(|component| {
        component.signed
            || !(8..=16).contains(&component.bits_per_sample)
            || component.horizontal_separation != 1
            || component.vertical_separation != 1
    }) {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "initial irreversible decode requires matching unit-sampled unsigned 8-16 bit components",
        ));
    }
    let first_component = codestream
        .siz
        .components
        .first()
        .ok_or(CodestreamError::SizeOverflow)?;
    if codestream
        .siz
        .components
        .iter()
        .any(|component| component.bits_per_sample != first_component.bits_per_sample)
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::SamplePrecision,
            "initial irreversible decode requires matching component precision",
        ));
    }
    if codestream.siz.tile_count_x()? != 1 || codestream.siz.tile_count_y()? != 1 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::MultipleTiles,
            "initial irreversible full decode accepts one tile",
        ));
    }
    let samples =
        native_part1_profile_component_samples(codestream).ok_or(CodestreamError::SizeOverflow)?;
    if samples == 0 || samples > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "initial irreversible decode is guarded to at most 16 Mi component samples",
        ));
    }
    let coding_style = uniform_effective_coding_style(codestream)?;
    if coding_style.entropy_coder != EntropyCoder::ClassicTier1 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::EntropyCoder,
            "initial irreversible decode accepts classic Tier-1 coding",
        ));
    }
    if coding_style.transform != WaveletTransform::Irreversible97 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::WaveletTransform,
            "irreversible decode requires COD transform zero",
        ));
    }
    validate_irreversible97_zero_origin_aligned_tile_grid(codestream, coding_style)?;
    if !default_precinct_progression_order_supported(coding_style.progression_order) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::ProgressionOrder,
            "initial irreversible decode accepts LRCP/RLCP progression",
        ));
    }
    if !default_precinct_layer_count_supported(coding_style.layers)
        || coding_style.sop_markers
        || coding_style.eph_markers
        || coding_style.precincts_declared
        || !classic_tier1_code_block_style_supported(coding_style.code_block_style)
    {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::PacketDecode,
            "initial irreversible decode requires at least one layer, default precincts, admitted code-block style, and no SOP/EPH",
        ));
    }
    if coding_style.multiple_component_transform != (codestream.siz.component_count() == 3) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "irreversible grayscale requires COD.mct=0 and three-component decode requires COD.mct=1 ICT",
        ));
    }
    for segment in &codestream.markers {
        match segment.marker {
            Marker::Soc
            | Marker::Sot
            | Marker::Sod
            | Marker::Eoc
            | Marker::Siz
            | Marker::Cod
            | Marker::Qcd
            | Marker::Qcc
            | Marker::Tlm
            | Marker::Plm
            | Marker::Plt
            | Marker::Com => {}
            marker => {
                return Err(unsupported(
                    Some(segment.offset),
                    Some(marker),
                    UnsupportedConstruct::MarkerSegment,
                    "marker is outside the initial irreversible decode profile",
                ));
            }
        }
    }
    let first_tile_offset = codestream
        .markers
        .iter()
        .find(|segment| segment.marker == Marker::Sot)
        .map(|segment| segment.offset)
        .ok_or_else(|| {
            unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "irreversible decode requires a tile-part header",
            )
        })?;
    if let Some(segment) = codestream.markers.iter().find(|segment| {
        matches!(segment.marker, Marker::Qcd | Marker::Qcc) && segment.offset > first_tile_offset
    }) {
        return Err(unsupported(
            Some(segment.offset),
            Some(segment.marker),
            UnsupportedConstruct::MarkerSegment,
            "initial irreversible decode accepts QCD/QCC only in the main header",
        ));
    }
    match codestream.tiles.as_slice() {
        [tile]
            if tile.tile_part_index == 0
                && !matches!(tile.tile_part_count, Some(count) if count != 1) => {}
        _ => {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "initial irreversible full decode requires exactly one first tile part",
            ));
        }
    }
    let subband_count = 1usize
        .checked_add(
            usize::from(coding_style.decomposition_levels)
                .checked_mul(3)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .ok_or(CodestreamError::SizeOverflow)?;
    parse_component_quantization(input, codestream, subband_count)?;
    Ok(coding_style)
}

fn validate_supported_part1_high_bit_depth_component_profile(
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    if codestream.kind != CodestreamKind::J2k {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "high-bit-depth component decode is limited to raw J2K Part 1 codestreams",
        ));
    }
    if let Some((marker, _detail)) = unsupported_part1_profile_marker(codestream, false, false) {
        return Err(unsupported(
            None,
            Some(marker),
            UnsupportedConstruct::MarkerSegment,
            "marker segment is outside the admitted high-bit-depth component profile",
        ));
    }
    if codestream.siz.component_count() != 1 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentCount,
            "high-bit-depth component decode is limited to one grayscale component",
        ));
    }
    let component = codestream
        .siz
        .components
        .first()
        .ok_or(CodestreamError::SizeOverflow)?;
    if component.bits_per_sample <= 8 || component.bits_per_sample > 16 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::SamplePrecision,
            "high-bit-depth component decode accepts 9-16 bit samples only",
        ));
    }
    if component.horizontal_separation != 1 || component.vertical_separation != 1 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "high-bit-depth component decode requires unit component sampling",
        ));
    }
    if codestream.siz.tile_count_x()? != 1 || codestream.siz.tile_count_y()? != 1 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::MultipleTiles,
            "high-bit-depth component decode accepts one tile",
        ));
    }
    let component_samples =
        native_part1_profile_component_samples(codestream).ok_or(CodestreamError::SizeOverflow)?;
    if component_samples == 0 || component_samples > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "native Part 1 profile decode is guarded to at most 16 Mi component samples",
        ));
    }
    let coding_style = uniform_effective_coding_style(codestream)?;
    if coding_style.entropy_coder != EntropyCoder::ClassicTier1 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::EntropyCoder,
            "high-bit-depth component decode only accepts classic tier-1 coding",
        ));
    }
    if !default_precinct_progression_order_supported(coding_style.progression_order) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::ProgressionOrder,
            "high-bit-depth component decode only accepts LRCP/RLCP default-precinct progression",
        ));
    }
    if coding_style.transform != WaveletTransform::Reversible53 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::WaveletTransform,
            "high-bit-depth component decode only accepts reversible 5/3",
        ));
    }
    if !default_precinct_layer_count_supported(coding_style.layers) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::PacketDecode,
            "high-bit-depth component decode requires at least one quality layer",
        ));
    }
    if coding_style.sop_markers || coding_style.eph_markers || coding_style.precincts_declared {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::MarkerSegment,
            "SOP, EPH, and explicit precinct tables are outside high-bit-depth component decode",
        ));
    }
    if !classic_tier1_code_block_style_supported(coding_style.code_block_style) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Tier1Decode,
            "high-bit-depth component decode accepts only combinations of BYPASS, RESET, TERMALL, VSC, PTERM, and SEGSYM code-block styles",
        ));
    }
    if coding_style.multiple_component_transform {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "high-bit-depth grayscale component decode does not accept multiple component transform",
        ));
    }
    match codestream.tiles.as_slice() {
        [tile]
            if tile.tile_part_index == 0
                && !matches!(tile.tile_part_count, Some(count) if count != 1) => {}
        [] => {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "one tile-part payload is required before high-bit-depth component decode",
            ));
        }
        [_] => {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "high-bit-depth component decode requires the first tile-part payload",
            ));
        }
        _ => {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "high-bit-depth component decode requires exactly one tile-part",
            ));
        }
    }

    Ok(coding_style)
}

fn validate_supported_part1_multitile_grayscale_profile(
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    if codestream.kind != CodestreamKind::J2k {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "multi-tile grayscale decode is limited to raw J2K Part 1 codestreams",
        ));
    }
    if let Some((marker, _detail)) = unsupported_part1_profile_marker(codestream, false, false) {
        return Err(unsupported(
            None,
            Some(marker),
            UnsupportedConstruct::MarkerSegment,
            "marker segment is outside the admitted multi-tile grayscale profile",
        ));
    }
    if codestream.siz.component_count() != 1 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentCount,
            "multi-tile grayscale decode is limited to one component",
        ));
    }
    let component = codestream
        .siz
        .components
        .first()
        .ok_or(CodestreamError::SizeOverflow)?;
    if component.bits_per_sample != 8 || component.signed {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::SamplePrecision,
            "multi-tile grayscale decode accepts unsigned 8-bit samples only",
        ));
    }
    if component.horizontal_separation != 1 || component.vertical_separation != 1 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "multi-tile grayscale decode requires unit component sampling",
        ));
    }
    if codestream.siz.tile_count_x()? == 1 && codestream.siz.tile_count_y()? == 1 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::MultipleTiles,
            "multi-tile grayscale decode requires more than one tile",
        ));
    }
    let component_samples =
        native_part1_profile_component_samples(codestream).ok_or(CodestreamError::SizeOverflow)?;
    if component_samples == 0 || component_samples > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "native Part 1 profile decode is guarded to at most 16 Mi component samples",
        ));
    }
    let coding_style = uniform_effective_coding_style(codestream)?;
    if coding_style.entropy_coder != EntropyCoder::ClassicTier1 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::EntropyCoder,
            "multi-tile grayscale decode only accepts classic tier-1 coding",
        ));
    }
    if !default_precinct_progression_order_supported(coding_style.progression_order) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::ProgressionOrder,
            "multi-tile grayscale decode only accepts LRCP/RLCP default-precinct progression",
        ));
    }
    if coding_style.transform != WaveletTransform::Reversible53 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::WaveletTransform,
            "multi-tile grayscale decode only accepts reversible 5/3",
        ));
    }
    if !default_precinct_layer_count_supported(coding_style.layers) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::PacketDecode,
            "multi-tile grayscale decode requires at least one quality layer",
        ));
    }
    if coding_style.sop_markers || coding_style.eph_markers || coding_style.precincts_declared {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::MarkerSegment,
            "SOP, EPH, and explicit precinct tables are outside multi-tile grayscale decode",
        ));
    }
    if !classic_tier1_code_block_style_supported(coding_style.code_block_style) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Tier1Decode,
            "multi-tile grayscale decode accepts only combinations of BYPASS, RESET, TERMALL, VSC, PTERM, and SEGSYM code-block styles",
        ));
    }
    if coding_style.multiple_component_transform {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "multi-tile grayscale decode does not accept multiple component transform",
        ));
    }
    validate_one_tile_part_per_tile(codestream)?;

    Ok(coding_style)
}

fn validate_supported_native_grayscale_u16_two_decomp_multitile_profile(
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    validate_supported_native_two_decomp_multitile_profile(codestream, 16, 1, false, "grayscale")
}

fn validate_supported_native_rgb_u16_two_decomp_multitile_profile(
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    validate_supported_native_two_decomp_multitile_profile(codestream, 16, 3, true, "RGB")
}

fn validate_supported_native_grayscale_u8_two_decomp_multitile_profile(
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    validate_supported_native_two_decomp_multitile_profile(codestream, 8, 1, false, "grayscale")
}

fn validate_supported_part1_native_multitile_partial_profile(
    input: &[u8],
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    let coding_style = validate_supported_part1_native_multitile_partial_semantics(codestream)?;
    let tile_count = codestream
        .siz
        .tile_count_x()?
        .checked_mul(codestream.siz.tile_count_y()?)
        .and_then(|count| usize::try_from(count).ok())
        .ok_or(CodestreamError::SizeOverflow)?;
    let expected_markers = 3_usize
        .checked_add(
            tile_count
                .checked_mul(2)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .and_then(|count| count.checked_add(1))
        .ok_or(CodestreamError::SizeOverflow)?;
    if codestream.markers.len() != expected_markers
        || input.get(..2) != Some(&[0xff, 0x4f])
        || codestream
            .markers
            .first()
            .is_none_or(|segment| segment.marker != Marker::Siz)
        || codestream
            .markers
            .get(1)
            .is_none_or(|segment| segment.marker != Marker::Cod)
        || codestream
            .markers
            .get(2)
            .is_none_or(|segment| segment.marker != Marker::Qcd)
    {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "native multi-tile partial decode requires exactly one ordered main-header SOC, SIZ, COD and QCD sequence",
        ));
    }
    if codestream.tiles.len() != tile_count {
        return Err(unsupported(
            None,
            Some(Marker::Sot),
            UnsupportedConstruct::MarkerSegment,
            "native multi-tile partial decode requires one ordered SOT/SOD pair for every SIZ tile",
        ));
    }
    for (tile_position, tile) in codestream.tiles.iter().enumerate() {
        let marker_position = 3_usize
            .checked_add(
                tile_position
                    .checked_mul(2)
                    .ok_or(CodestreamError::SizeOverflow)?,
            )
            .ok_or(CodestreamError::SizeOverflow)?;
        let tile_index = u16::try_from(tile_position).map_err(|_| CodestreamError::SizeOverflow)?;
        if tile.tile_index != tile_index
            || tile.tile_part_index != 0
            || tile.tile_part_count != Some(1)
            || codestream
                .markers
                .get(marker_position)
                .is_none_or(|segment| segment.marker != Marker::Sot)
            || codestream
                .markers
                .get(marker_position + 1)
                .is_none_or(|segment| segment.marker != Marker::Sod)
        {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "native multi-tile partial decode requires ordered single-part SOT/SOD tile structures without tile-header overrides",
            ));
        }
    }
    let eoc = codestream
        .markers
        .last()
        .filter(|segment| segment.marker == Marker::Eoc)
        .ok_or_else(|| {
            unsupported(
                None,
                Some(Marker::Eoc),
                UnsupportedConstruct::MarkerSegment,
                "native multi-tile partial decode requires exactly one terminal EOC marker",
            )
        })?;
    if eoc.offset.checked_add(2) != Some(input.len()) {
        return Err(unsupported(
            Some(eoc.offset),
            Some(Marker::Eoc),
            UnsupportedConstruct::MarkerSegment,
            "native multi-tile partial decode requires EOC to terminate the raw codestream bytes",
        ));
    }
    Ok(coding_style)
}

fn validate_supported_part1_native_multitile_partial_semantics(
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    let coding_style =
        validate_supported_native_grayscale_u8_two_decomp_multitile_profile(codestream)?;
    let siz = &codestream.siz;
    let has_nonzero_origin = siz.image_origin_x != 0
        || siz.image_origin_y != 0
        || siz.tile_origin_x != 0
        || siz.tile_origin_y != 0;
    if has_nonzero_origin
        && (!siz.image_origin_x.is_multiple_of(4)
            || !siz.image_origin_y.is_multiple_of(4)
            || !siz.tile_origin_x.is_multiple_of(4)
            || !siz.tile_origin_y.is_multiple_of(4)
            || !siz.tile_width.is_multiple_of(4)
            || !siz.tile_height.is_multiple_of(4))
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::Transform,
            "non-zero-origin native multi-tile partial decode requires image origins, tile origins and nominal tile extents aligned to the two-level synthesis phase",
        ));
    }
    if has_nonzero_origin {
        for tile in tile_rects(codestream)? {
            let absolute_x = siz
                .image_origin_x
                .checked_add(tile.x)
                .ok_or(CodestreamError::SizeOverflow)?;
            let absolute_y = siz
                .image_origin_y
                .checked_add(tile.y)
                .ok_or(CodestreamError::SizeOverflow)?;
            if !absolute_x.is_multiple_of(4) || !absolute_y.is_multiple_of(4) {
                return Err(unsupported(
                    None,
                    Some(Marker::Siz),
                    UnsupportedConstruct::Transform,
                    "non-zero-origin native multi-tile partial decode requires every clipped tile-component start aligned to the two-level synthesis phase",
                ));
            }
        }
    }
    if coding_style.progression_order != ProgressionOrder::Lrcp
        || coding_style.layers != 1
        || coding_style.code_block_width_exponent != 6
        || coding_style.code_block_height_exponent != 6
        || coding_style.code_block_style != 0
    {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::PacketDecode,
            "native multi-tile partial decode requires one-layer LRCP coding with the encoder-compatible default code-block style",
        ));
    }
    if !codestream.component_coding_styles.is_empty() {
        return Err(unsupported(
            None,
            Some(Marker::Coc),
            UnsupportedConstruct::MarkerSegment,
            "native multi-tile partial decode rejects component coding-style overrides",
        ));
    }
    Ok(coding_style)
}

fn validate_supported_native_rgb_u8_two_decomp_multitile_profile(
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    validate_supported_native_two_decomp_multitile_profile(codestream, 8, 3, true, "RGB")
}

fn validate_supported_native_component_multitile_profile(
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    validate_supported_native_component_multitile_profile_with_sample_guard(codestream, true, false)
}

fn validate_supported_native_component_multitile_profile_with_sample_guard(
    codestream: &Codestream,
    enforce_total_sample_guard: bool,
    allow_bounded_tile_maxshift: bool,
) -> Result<CodingStyleMarker> {
    if codestream.kind != CodestreamKind::J2k {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "native component multi-tile decode is limited to raw J2K Part 1 codestreams",
        ));
    }
    if let Some((marker, _detail)) =
        unsupported_part1_profile_marker(codestream, true, allow_bounded_tile_maxshift)
    {
        return Err(unsupported(
            None,
            Some(marker),
            UnsupportedConstruct::MarkerSegment,
            "marker segment is outside native component multi-tile decode",
        ));
    }
    let component_count = codestream.siz.component_count();
    if component_count == 0 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentCount,
            "native component decode requires at least one component",
        ));
    }
    if codestream
        .siz
        .components
        .iter()
        .any(|component| component.bits_per_sample == 0 || component.bits_per_sample > 16)
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::SamplePrecision,
            "native component decode accepts signed or unsigned 1-16 bit samples",
        ));
    }
    if codestream
        .siz
        .components
        .iter()
        .any(|component| component.horizontal_separation != 1 || component.vertical_separation != 1)
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "native component multi-tile decode requires unit component sampling",
        ));
    }
    let component_samples =
        native_part1_profile_component_samples(codestream).ok_or(CodestreamError::SizeOverflow)?;
    if component_samples == 0
        || (enforce_total_sample_guard && component_samples > MAX_NATIVE_PART1_TOTAL_DECODE_SAMPLES)
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "native component decode is guarded to at most 256 Mi total component samples",
        ));
    }

    let coding_style = uniform_effective_coding_style(codestream)?;
    if coding_style.entropy_coder != EntropyCoder::ClassicTier1 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::EntropyCoder,
            "native component multi-tile decode only accepts classic tier-1 coding",
        ));
    }
    let explicit_precinct_progression = coding_style.precincts_declared
        && matches!(
            coding_style.progression_order,
            ProgressionOrder::Lrcp
                | ProgressionOrder::Rlcp
                | ProgressionOrder::Rpcl
                | ProgressionOrder::Pcrl
                | ProgressionOrder::Cprl
        );
    let first_tile_offset = codestream
        .markers
        .iter()
        .find(|segment| segment.marker == Marker::Sot)
        .map(|segment| segment.offset)
        .unwrap_or(usize::MAX);
    let has_main_header_poc = codestream
        .markers
        .iter()
        .any(|segment| segment.marker == Marker::Poc && segment.offset < first_tile_offset);
    if !default_precinct_progression_order_supported(coding_style.progression_order)
        && !explicit_precinct_progression
        && !has_main_header_poc
    {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::ProgressionOrder,
            "native component decode accepts LRCP/RLCP, an admitted explicit-precinct progression, or a bounded main-header POC override",
        ));
    }
    if coding_style.transform != WaveletTransform::Reversible53 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::WaveletTransform,
            "native component multi-tile decode only accepts reversible 5/3",
        ));
    }
    if !default_precinct_layer_count_supported(coding_style.layers) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::PacketDecode,
            "native component multi-tile decode requires at least one quality layer",
        ));
    }
    let inline_packet_markers = coding_style.sop_markers || coding_style.eph_markers;
    if coding_style.precincts_declared && coding_style.sop_markers {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::PacketDecode,
            "SOP with explicit precincts is outside the qualified native component profile",
        ));
    }
    if coding_style.precincts_declared {
        let tile_rects = tile_rects(codestream)?;
        let component_styles = alloc::vec![coding_style; usize::from(component_count)];
        if tile_rects.len() != 1
            || !coding_style_has_supported_precinct_grid(coding_style, tile_rects[0])
            || !topologies_have_supported_spatial_precinct_order(
                &codestream.siz,
                tile_rects[0],
                &component_styles,
                coding_style.progression_order,
            )?
        {
            return Err(unsupported(
                None,
                Some(Marker::Cod),
                UnsupportedConstruct::PacketDecode,
                "explicit precinct decode currently requires one tile with valid precinct/code-block geometry and absolute precinct positions aligned with the bounded spatial-order walker",
            ));
        }
    }
    if !classic_tier1_code_block_style_supported(coding_style.code_block_style) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Tier1Decode,
            "native component multi-tile decode accepts only combinations of BYPASS, RESET, TERMALL, VSC, PTERM, and SEGSYM code-block styles",
        ));
    }
    if component_count != 3 && coding_style.multiple_component_transform {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "native component decode accepts multiple component transform only for three-component rows",
        ));
    }
    if inline_packet_markers {
        validate_one_tile_part_per_tile(codestream)?;
    } else {
        validate_retained_tile_parts_per_tile(codestream)?;
    }

    Ok(coding_style)
}

fn validate_supported_native_subsampled_component_profile(
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    if codestream.kind != CodestreamKind::J2k {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "native subsampled component decode is limited to raw J2K Part 1 codestreams",
        ));
    }
    if let Some((marker, _detail)) =
        unsupported_part1_profile_marker_inner(codestream, false, false, true)
    {
        return Err(unsupported(
            None,
            Some(marker),
            UnsupportedConstruct::MarkerSegment,
            "marker segment is outside native subsampled component decode",
        ));
    }
    validate_native_informational_crg_structure(codestream)?;
    if codestream.siz.components.is_empty() {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentCount,
            "native subsampled component decode requires at least one component",
        ));
    }
    if codestream.siz.components.iter().any(|component| {
        component.bits_per_sample == 0
            || component.bits_per_sample > 16
            || component.horizontal_separation == 0
            || component.vertical_separation == 0
    }) {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::SamplePrecision,
            "native subsampled component decode accepts signed or unsigned 1-16 bit components with nonzero sampling factors",
        ));
    }
    if codestream
        .siz
        .components
        .iter()
        .all(|component| component.horizontal_separation == 1 && component.vertical_separation == 1)
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "native subsampled component decode requires at least one non-unit component grid",
        ));
    }
    if codestream.siz.image_origin_x != 0
        || codestream.siz.image_origin_y != 0
        || codestream.siz.tile_origin_x != 0
        || codestream.siz.tile_origin_y != 0
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "native subsampled component decode currently requires zero image and tile origins",
        ));
    }
    let tiles = tile_rects(codestream)?;
    if tiles.len() != 1 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::MultipleTiles,
            "native subsampled component decode currently requires exactly one tile",
        ));
    }
    let component_samples =
        native_part1_component_grid_samples(codestream).ok_or(CodestreamError::SizeOverflow)?;
    if component_samples == 0 || component_samples > MAX_NATIVE_PART1_TOTAL_DECODE_SAMPLES {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "native subsampled component decode is guarded to at most 256 Mi native-grid samples",
        ));
    }

    let coding_style = uniform_effective_coding_style(codestream)?;
    if coding_style.entropy_coder != EntropyCoder::ClassicTier1 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::EntropyCoder,
            "native subsampled component decode requires classic Tier-1 coding",
        ));
    }
    if coding_style.transform == WaveletTransform::Irreversible97 {
        validate_irreversible97_zero_origin_aligned_tile_grid(codestream, coding_style)?;
    }
    if !default_precinct_progression_order_supported(coding_style.progression_order) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::ProgressionOrder,
            "native subsampled component decode currently accepts LRCP or RLCP progression",
        ));
    }
    if !default_precinct_layer_count_supported(coding_style.layers) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::PacketDecode,
            "native subsampled component decode requires at least one quality layer",
        ));
    }
    if coding_style.precincts_declared {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::MarkerSegment,
            "explicit precincts are outside native subsampled component decode",
        ));
    }
    if !classic_tier1_code_block_style_supported(coding_style.code_block_style) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Tier1Decode,
            "native subsampled component decode requires an admitted code-block style",
        ));
    }
    if coding_style.multiple_component_transform {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "native subsampled component decode does not apply a multiple-component transform",
        ));
    }
    for component in &codestream.siz.components {
        let component_tile = component_tile_rect(codestream, tiles[0], component)?;
        if component_tile.width == 0
            || component_tile.height == 0
            || component_tile.width > (1 << 15)
            || component_tile.height > (1 << 15)
        {
            return Err(unsupported(
                None,
                Some(Marker::Siz),
                UnsupportedConstruct::PacketDecode,
                "native subsampled component decode requires one effective default precinct per native component grid",
            ));
        }
    }
    validate_one_tile_part_per_tile(codestream)?;
    Ok(coding_style)
}

fn validate_native_informational_crg_structure(codestream: &Codestream) -> Result<()> {
    let first_tile_offset = codestream
        .markers
        .iter()
        .find(|segment| segment.marker == Marker::Sot)
        .map(|segment| segment.offset)
        .unwrap_or(usize::MAX);
    let mut registration = codestream
        .markers
        .iter()
        .filter(|segment| segment.marker == Marker::Crg);
    let Some(segment) = registration.next() else {
        return Ok(());
    };
    if registration.next().is_some() {
        return Err(invalid(
            Some(segment.offset),
            Some(Marker::Crg),
            "main header contains more than one CRG marker segment",
        ));
    }
    if segment.offset >= first_tile_offset {
        return Err(unsupported(
            Some(segment.offset),
            Some(Marker::Crg),
            UnsupportedConstruct::MarkerSegment,
            "CRG is permitted only in the main header",
        ));
    }
    let expected = usize::from(codestream.siz.component_count())
        .checked_mul(4)
        .ok_or(CodestreamError::SizeOverflow)?;
    if segment.data_len != expected {
        return Err(invalid(
            Some(segment.offset),
            Some(Marker::Crg),
            "CRG must contain exactly one Xcrg/Ycrg pair per SIZ component",
        ));
    }
    Ok(())
}

fn validate_supported_native_irreversible_component_selective_profile(
    input: &[u8],
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    if codestream.kind != CodestreamKind::J2k {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "selective irreversible component decode is limited to raw Part 1 codestreams",
        ));
    }
    if codestream.siz.component_count() == 0 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentCount,
            "selective irreversible component decode requires at least one component",
        ));
    }
    if codestream.siz.components.iter().any(|component| {
        component.signed
            || !(8..=16).contains(&component.bits_per_sample)
            || component.horizontal_separation != 1
            || component.vertical_separation != 1
    }) {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "selective irreversible component decode requires unsigned 8-16 bit unit-sampled components",
        ));
    }
    if tile_rects(codestream)?.iter().any(|tile| {
        u64::from(tile.width).saturating_mul(u64::from(tile.height))
            > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES
    }) {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "selective irreversible decode is guarded to at most 16 Mi samples per tile component",
        ));
    }

    let coding_style = uniform_effective_coding_style(codestream)?;
    if coding_style.entropy_coder != EntropyCoder::ClassicTier1 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::EntropyCoder,
            "selective irreversible decode accepts classic Tier-1 coding",
        ));
    }
    if coding_style.transform != WaveletTransform::Irreversible97 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::WaveletTransform,
            "selective irreversible decode requires COD transform zero",
        ));
    }
    validate_irreversible97_zero_origin_aligned_tile_grid(codestream, coding_style)?;
    if !default_precinct_progression_order_supported(coding_style.progression_order) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::ProgressionOrder,
            "selective irreversible decode currently accepts LRCP or RLCP progression",
        ));
    }
    if !default_precinct_layer_count_supported(coding_style.layers)
        || coding_style.sop_markers
        || coding_style.eph_markers
        || coding_style.precincts_declared
        || !classic_tier1_code_block_style_supported(coding_style.code_block_style)
    {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::PacketDecode,
            "selective irreversible decode requires at least one layer, default precincts, admitted code-block style, and no SOP/EPH",
        ));
    }
    if coding_style.multiple_component_transform {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "selective irreversible component decode does not split multiple-component-transform inputs",
        ));
    }

    let first_tile_offset = codestream
        .markers
        .iter()
        .find(|segment| segment.marker == Marker::Sot)
        .map(|segment| segment.offset)
        .ok_or_else(|| {
            unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "selective irreversible decode requires tile-part headers",
            )
        })?;
    for segment in &codestream.markers {
        match segment.marker {
            Marker::Soc
            | Marker::Sot
            | Marker::Sod
            | Marker::Eoc
            | Marker::Siz
            | Marker::Cod
            | Marker::Qcd
            | Marker::Qcc
            | Marker::Tlm
            | Marker::Plm
            | Marker::Plt
            | Marker::Com => {}
            marker => {
                return Err(unsupported(
                    Some(segment.offset),
                    Some(marker),
                    UnsupportedConstruct::MarkerSegment,
                    "marker is outside selective irreversible component decode",
                ));
            }
        }
        if matches!(segment.marker, Marker::Qcd | Marker::Qcc) && segment.offset > first_tile_offset
        {
            return Err(unsupported(
                Some(segment.offset),
                Some(segment.marker),
                UnsupportedConstruct::MarkerSegment,
                "selective irreversible decode accepts QCD/QCC only in the main header",
            ));
        }
    }
    validate_retained_tile_parts_per_tile(codestream)?;
    let subband_count = 1usize
        .checked_add(
            usize::from(coding_style.decomposition_levels)
                .checked_mul(3)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .ok_or(CodestreamError::SizeOverflow)?;
    parse_component_quantization(input, codestream, subband_count)?;
    Ok(coding_style)
}

fn validate_supported_selective_native_component_profile(
    input: &[u8],
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    validate_supported_selective_native_component_profile_with_sample_guard(input, codestream, true)
}

fn validate_supported_selective_native_component_profile_with_sample_guard(
    input: &[u8],
    codestream: &Codestream,
    enforce_total_sample_guard: bool,
) -> Result<CodingStyleMarker> {
    let bounded_poc = parse_bounded_main_header_poc(input, codestream)?;
    let bounded_maxshift = parse_bounded_tile_maxshift(input, codestream)?;
    if bounded_maxshift.is_some() && bounded_poc.is_none() {
        return Err(unsupported(
            None,
            Some(Marker::Rgn),
            UnsupportedConstruct::MarkerSegment,
            "tile-header Maxshift is admitted only by the bounded P0.03 POC path",
        ));
    }
    let coding_style = uniform_effective_coding_style(codestream)?;
    if codestream.siz.image_origin_x != 0
        || codestream.siz.image_origin_y != 0
        || codestream.siz.tile_origin_x != 0
        || codestream.siz.tile_origin_y != 0
    {
        return if enforce_total_sample_guard {
            validate_supported_part1_native_multitile_partial_profile(input, codestream)
        } else {
            validate_supported_part1_native_multitile_partial_semantics(codestream)
        };
    }
    match coding_style.transform {
        WaveletTransform::Irreversible97 => {
            validate_supported_native_irreversible_component_selective_profile(input, codestream)
        }
        _ if codestream.siz.components.iter().any(|component| {
            component.horizontal_separation != 1 || component.vertical_separation != 1
        }) =>
        {
            validate_supported_native_subsampled_component_profile(codestream)
        }
        _ => {
            if let Some(maxshift) = bounded_maxshift {
                validate_bounded_informational_crg(input, codestream)?;
                validate_bounded_maxshift_plane_widths(input, codestream, coding_style, maxshift)?;
            }
            validate_supported_native_component_multitile_profile_with_sample_guard(
                codestream,
                enforce_total_sample_guard,
                bounded_poc.is_some() && bounded_maxshift.is_some(),
            )
        }
    }
}

fn validate_part1_reduced_reversible_mct_component_profile(
    input: &[u8],
    codestream: &Codestream,
    discard_levels: u8,
) -> Result<CodingStyleMarker> {
    if discard_levels != 2 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "the qualified Profile-0 reduced MCT path requires exactly two discarded resolution levels",
        ));
    }
    let coding_style = validate_supported_selective_native_component_profile(input, codestream)?;
    if codestream.siz.component_count() != 3
        || codestream.siz.components.iter().any(|component| {
            component.bits_per_sample != 8
                || component.signed
                || component.horizontal_separation != 1
                || component.vertical_separation != 1
        })
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "the qualified Profile-0 reduced MCT path requires three unsigned 8-bit unit-sampled components",
        ));
    }
    if codestream.siz.image_origin_x != 0
        || codestream.siz.image_origin_y != 0
        || codestream.siz.tile_origin_x != 0
        || codestream.siz.tile_origin_y != 0
        || tile_rects(codestream)?.len() != 1
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::MultipleTiles,
            "the qualified Profile-0 reduced MCT path requires one origin-aligned tile",
        ));
    }
    if coding_style.progression_order != ProgressionOrder::Lrcp
        || coding_style.layers != 1
        || !coding_style.multiple_component_transform
        || coding_style.decomposition_levels != 5
        || coding_style.transform != WaveletTransform::Reversible53
        || coding_style.precincts_declared
        || coding_style.sop_markers
        || coding_style.eph_markers
    {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "the qualified Profile-0 reduced MCT path requires one-layer LRCP, five-level reversible 5/3 coding with MCT and default precincts",
        ));
    }
    if !codestream.component_coding_styles.is_empty()
        || codestream.markers.iter().any(|segment| {
            matches!(
                segment.marker,
                Marker::Coc
                    | Marker::Rgn
                    | Marker::Qcc
                    | Marker::Poc
                    | Marker::Tlm
                    | Marker::Plm
                    | Marker::Plt
                    | Marker::Ppm
                    | Marker::Ppt
                    | Marker::Crg
                    | Marker::Sop
                    | Marker::Eph
                    | Marker::Cap
                    | Marker::Unknown(_)
            )
        })
    {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "component overrides, progression changes, packet relocation, ROI, registration, capability extensions, and inline packet markers are outside the qualified Profile-0 reduced MCT path",
        ));
    }
    Ok(coding_style)
}

fn validate_part1_reduced_irreversible_mct_component_profile(
    input: &[u8],
    codestream: &Codestream,
    discard_levels: u8,
) -> Result<CodingStyleMarker> {
    if discard_levels != 3 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "the qualified Profile-0 reduced irreversible MCT path requires exactly three discarded resolution levels",
        ));
    }
    if codestream.kind != CodestreamKind::J2k {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 reduced irreversible MCT path is limited to raw Part 1 codestreams",
        ));
    }
    if codestream.siz.component_count() != 3
        || codestream.siz.components.iter().any(|component| {
            component.bits_per_sample != 8
                || component.signed
                || component.horizontal_separation != 1
                || component.vertical_separation != 1
        })
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "the qualified Profile-0 reduced irreversible MCT path requires three unsigned 8-bit unit-sampled components",
        ));
    }
    if codestream.siz.image_origin_x != 0
        || codestream.siz.image_origin_y != 0
        || codestream.siz.tile_origin_x != 0
        || codestream.siz.tile_origin_y != 0
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::WaveletTransform,
            "the qualified Profile-0 reduced irreversible MCT path requires zero image and tile origins",
        ));
    }
    let tile_rects = tile_rects(codestream)?;
    if tile_rects.len() != 1
        || !matches!(
            codestream.tiles.as_slice(),
            [tile] if tile.tile_index == 0
                && tile.tile_part_index == 0
                && !matches!(tile.tile_part_count, Some(count) if count != 1)
        )
    {
        return Err(unsupported(
            None,
            Some(Marker::Sot),
            UnsupportedConstruct::MultipleTiles,
            "the qualified Profile-0 reduced irreversible MCT path requires one first tile part in one tile",
        ));
    }
    if !codestream.component_coding_styles.is_empty() {
        return Err(unsupported(
            None,
            Some(Marker::Coc),
            UnsupportedConstruct::MarkerSegment,
            "component coding-style overrides are outside the qualified Profile-0 reduced irreversible MCT path",
        ));
    }

    let coding_style = codestream.coding_style.ok_or_else(|| {
        invalid(
            None,
            Some(Marker::Cod),
            "the qualified Profile-0 reduced irreversible MCT path requires a main-header COD marker",
        )
    })?;
    let p0_04_precincts = coding_style.precincts_declared
        && coding_style.decomposition_levels == 6
        && coding_style.precinct_exponents[..=6]
            .iter()
            .all(|&packed| packed == 0x77);
    if coding_style.entropy_coder != EntropyCoder::ClassicTier1
        || coding_style.transform != WaveletTransform::Irreversible97
        || !coding_style.multiple_component_transform
        || coding_style.decomposition_levels != 6
        || coding_style.progression_order != ProgressionOrder::Rlcp
        || coding_style.layers != 20
        || !p0_04_precincts
        || coding_style.sop_markers
        || coding_style.eph_markers
        || coding_style.code_block_style != 4
    {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "the qualified Profile-0 reduced irreversible MCT path requires 20-layer RLCP irreversible 9/7 MCT with six decomposition levels, 128-by-128 precincts, termination on every classic Tier-1 coding pass, and no SOP/EPH",
        ));
    }
    validate_irreversible97_zero_origin_aligned_tile_grid(codestream, coding_style)?;

    let first_tile_offset = codestream
        .markers
        .iter()
        .find(|segment| segment.marker == Marker::Sot)
        .map(|segment| segment.offset)
        .ok_or_else(|| {
            unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "the qualified Profile-0 reduced irreversible MCT path requires a tile-part header",
            )
        })?;
    let mut main_cod_seen = false;
    for segment in &codestream.markers {
        match segment.marker {
            Marker::Soc
            | Marker::Sot
            | Marker::Sod
            | Marker::Eoc
            | Marker::Siz
            | Marker::Cod
            | Marker::Qcd
            | Marker::Qcc
            | Marker::Com => {}
            marker => {
                return Err(unsupported(
                    Some(segment.offset),
                    Some(marker),
                    UnsupportedConstruct::MarkerSegment,
                    "marker is outside the qualified Profile-0 reduced irreversible MCT path",
                ));
            }
        }
        if segment.marker == Marker::Cod
            && (segment.offset >= first_tile_offset || core::mem::replace(&mut main_cod_seen, true))
        {
            return Err(unsupported(
                Some(segment.offset),
                Some(Marker::Cod),
                UnsupportedConstruct::MarkerSegment,
                "the qualified Profile-0 reduced irreversible MCT path requires exactly one main-header COD and no tile-header COD overrides",
            ));
        }
        if matches!(segment.marker, Marker::Qcd | Marker::Qcc) && segment.offset > first_tile_offset
        {
            return Err(unsupported(
                Some(segment.offset),
                Some(segment.marker),
                UnsupportedConstruct::MarkerSegment,
                "the qualified Profile-0 reduced irreversible MCT path accepts QCD/QCC only in the main header",
            ));
        }
    }
    let subband_count = 1usize
        .checked_add(
            usize::from(coding_style.decomposition_levels)
                .checked_mul(3)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .ok_or(CodestreamError::SizeOverflow)?;
    parse_component_quantization(input, codestream, subband_count)?;
    Ok(coding_style)
}

fn p0_05_effective_style_matches(
    style: CodingStyleMarker,
    decomposition_levels: u8,
    transform: WaveletTransform,
) -> bool {
    style.entropy_coder == EntropyCoder::ClassicTier1
        && !style.sop_markers
        && !style.eph_markers
        && style.progression_order == ProgressionOrder::Pcrl
        && style.layers == 7
        && !style.multiple_component_transform
        && style.decomposition_levels == decomposition_levels
        && style.code_block_width_exponent == 5
        && style.code_block_height_exponent == 5
        && style.code_block_style == 0
        && style.transform == transform
        && !style.precincts_declared
}

fn validate_part1_reduced_heterogeneous_irreversible_component_profile(
    input: &[u8],
    codestream: &Codestream,
    discard_levels: u8,
) -> Result<CodingStyleMarker> {
    if discard_levels != 3 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "the qualified Profile-0 heterogeneous component path requires exactly three discarded resolution levels",
        ));
    }
    if codestream.kind != CodestreamKind::J2k {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 heterogeneous component path is limited to raw Part 1 codestreams",
        ));
    }
    let expected_sampling = [(1_u8, 1_u8), (1, 1), (2, 2), (2, 2)];
    if codestream.siz.components.len() != expected_sampling.len()
        || codestream.siz.reference_grid_width != 1024
        || codestream.siz.reference_grid_height != 1024
        || codestream.siz.tile_width != 1024
        || codestream.siz.tile_height != 1024
        || codestream
            .siz
            .components
            .iter()
            .zip(expected_sampling)
            .any(|(component, sampling)| {
                component.bits_per_sample != 8
                    || component.signed
                    || (
                        component.horizontal_separation,
                        component.vertical_separation,
                    ) != sampling
            })
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "the qualified Profile-0 heterogeneous component path requires one 1024x1024 tile and four unsigned 8-bit components with its bounded 1x1/1x1/2x2/2x2 sampling",
        ));
    }
    if codestream.siz.image_origin_x != 0
        || codestream.siz.image_origin_y != 0
        || codestream.siz.tile_origin_x != 0
        || codestream.siz.tile_origin_y != 0
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::WaveletTransform,
            "the qualified Profile-0 heterogeneous component path requires zero image and tile origins",
        ));
    }
    let tiles = tile_rects(codestream)?;
    if tiles.len() != 1
        || !matches!(
            codestream.tiles.as_slice(),
            [tile] if tile.tile_index == 0
                && tile.tile_part_index == 0
                && !matches!(tile.tile_part_count, Some(count) if count != 1)
        )
    {
        return Err(unsupported(
            None,
            Some(Marker::Sot),
            UnsupportedConstruct::MultipleTiles,
            "the qualified Profile-0 heterogeneous component path requires one first tile part in one tile",
        ));
    }

    let coding_style = codestream.coding_style.ok_or_else(|| {
        invalid(
            None,
            Some(Marker::Cod),
            "the qualified Profile-0 heterogeneous component path requires a main-header COD marker",
        )
    })?;
    let expected_styles = [
        (0_u16, 6_u8, WaveletTransform::Irreversible97),
        (1, 3, WaveletTransform::Irreversible97),
        (2, 6, WaveletTransform::Irreversible97),
        (3, 6, WaveletTransform::Reversible53),
    ];
    if codestream.component_coding_styles.len() != 2
        || !codestream
            .component_coding_styles
            .iter()
            .any(|style| style.component_index == 1)
        || !codestream
            .component_coding_styles
            .iter()
            .any(|style| style.component_index == 3)
        || expected_styles
            .iter()
            .any(|(component, levels, transform)| {
                codestream
                    .effective_coding_style(*component)
                    .is_none_or(|style| !p0_05_effective_style_matches(style, *levels, *transform))
            })
    {
        return Err(unsupported(
            None,
            Some(Marker::Coc),
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 heterogeneous component path requires the bounded component-1 and component-3 COC styles",
        ));
    }
    validate_irreversible97_zero_origin_aligned_tile_grid(codestream, coding_style)?;
    for (component_index, style) in (0..codestream.siz.component_count()).filter_map(|component| {
        codestream
            .effective_coding_style(component)
            .map(|style| (component, style))
    }) {
        let component = codestream
            .siz
            .components
            .get(usize::from(component_index))
            .ok_or(CodestreamError::SizeOverflow)?;
        let component_tile = component_tile_rect(codestream, tiles[0], component)?;
        if !coding_style_has_single_precinct(style, component_tile.width, component_tile.height) {
            return Err(unsupported(
                None,
                Some(Marker::Cod),
                UnsupportedConstruct::PacketDecode,
                "the qualified Profile-0 heterogeneous component path requires one effective precinct per component resolution",
            ));
        }
    }

    let first_tile_offset = codestream
        .markers
        .iter()
        .find(|segment| segment.marker == Marker::Sot)
        .map(|segment| segment.offset)
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut main_cod_seen = false;
    let mut main_siz_seen = false;
    let mut qcc_components = Vec::new();
    for segment in &codestream.markers {
        match segment.marker {
            Marker::Soc
            | Marker::Sot
            | Marker::Sod
            | Marker::Eoc
            | Marker::Siz
            | Marker::Cod
            | Marker::Coc
            | Marker::Qcd
            | Marker::Qcc
            | Marker::Tlm
            | Marker::Com => {}
            marker => {
                return Err(unsupported(
                    Some(segment.offset),
                    Some(marker),
                    UnsupportedConstruct::MarkerSegment,
                    "marker is outside the qualified Profile-0 heterogeneous component path",
                ));
            }
        }
        if segment.marker == Marker::Cod
            && (segment.offset >= first_tile_offset || core::mem::replace(&mut main_cod_seen, true))
        {
            return Err(unsupported(
                Some(segment.offset),
                Some(Marker::Cod),
                UnsupportedConstruct::MarkerSegment,
                "the qualified Profile-0 heterogeneous component path requires exactly one main-header COD",
            ));
        }
        if segment.marker == Marker::Siz
            && (segment.offset >= first_tile_offset || core::mem::replace(&mut main_siz_seen, true))
        {
            return Err(unsupported(
                Some(segment.offset),
                Some(Marker::Siz),
                UnsupportedConstruct::MarkerSegment,
                "the qualified Profile-0 heterogeneous component path requires exactly one main-header SIZ",
            ));
        }
        if matches!(
            segment.marker,
            Marker::Coc | Marker::Qcd | Marker::Qcc | Marker::Tlm
        ) && segment.offset >= first_tile_offset
        {
            return Err(unsupported(
                Some(segment.offset),
                Some(segment.marker),
                UnsupportedConstruct::MarkerSegment,
                "component, quantisation, and tile-length overrides are accepted only in the main header",
            ));
        }
        if segment.marker == Marker::Qcc {
            let data = checked_slice(input, segment.data_offset, segment.data_len)?;
            qcc_components.push(data.first().copied().map(u16::from).ok_or_else(|| {
                invalid(
                    Some(segment.offset),
                    Some(Marker::Qcc),
                    "QCC marker omits its component selector",
                )
            })?);
        }
    }
    qcc_components.sort_unstable();
    if qcc_components != [0, 3] {
        return Err(unsupported(
            None,
            Some(Marker::Qcc),
            UnsupportedConstruct::PacketDecode,
            "the qualified Profile-0 heterogeneous component path requires QCC overrides for components zero and three",
        ));
    }

    let component_styles = expected_styles
        .iter()
        .map(|(component, _, _)| {
            codestream
                .effective_coding_style(*component)
                .ok_or(CodestreamError::SizeOverflow)
        })
        .collect::<Result<Vec<_>>>()?;
    let subband_counts = component_styles
        .iter()
        .map(|style| 1usize + usize::from(style.decomposition_levels) * 3)
        .collect::<Vec<_>>();
    parse_component_quantization_for_styles(
        input,
        codestream,
        &component_styles,
        &subband_counts,
        19,
        None,
    )?;
    Ok(coding_style)
}

fn p0_06_effective_style_matches(style: CodingStyleMarker, transform: WaveletTransform) -> bool {
    style.entropy_coder == EntropyCoder::ClassicTier1
        && !style.sop_markers
        && !style.eph_markers
        && style.progression_order == ProgressionOrder::Rpcl
        && style.layers == 4
        && !style.multiple_component_transform
        && style.decomposition_levels == 6
        && style.code_block_width_exponent == 6
        && style.code_block_height_exponent == 6
        && style.code_block_style == 0
        && style.transform == transform
        && !style.precincts_declared
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ValidatedP006ComponentProfile {
    coding_style: CodingStyleMarker,
    effective_maxshift: BoundedTileMaxshift,
}

fn p0_07_main_cod_payload_matches(data: &[u8]) -> bool {
    data == [0x06, 0x01, 0x00, 0x08, 0x00, 0x03, 0x04, 0x04, 0x00, 0x01]
}

fn validate_part1_reduced_roi_irreversible_component_profile(
    input: &[u8],
    codestream: &Codestream,
    discard_levels: u8,
) -> Result<ValidatedP006ComponentProfile> {
    if discard_levels != 3 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "the qualified Profile-0 ROI component path requires exactly three discarded resolution levels",
        ));
    }
    if codestream.kind != CodestreamKind::J2k {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 ROI component path is limited to raw Part 1 codestreams",
        ));
    }
    let expected_sampling = [(1_u8, 1_u8), (2, 1), (1, 2), (2, 2)];
    if codestream.siz.capabilities != 2
        || codestream.siz.components.len() != expected_sampling.len()
        || codestream.siz.reference_grid_width != 513
        || codestream.siz.reference_grid_height != 129
        || codestream.siz.tile_width != 513
        || codestream.siz.tile_height != 129
        || codestream
            .siz
            .components
            .iter()
            .zip(expected_sampling)
            .any(|(component, sampling)| {
                component.bits_per_sample != 12
                    || component.signed
                    || (
                        component.horizontal_separation,
                        component.vertical_separation,
                    ) != sampling
            })
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "the qualified Profile-0 ROI path requires one 513x129 tile and four unsigned 12-bit components with its bounded 1x1/2x1/1x2/2x2 sampling",
        ));
    }
    if codestream.siz.image_origin_x != 0
        || codestream.siz.image_origin_y != 0
        || codestream.siz.tile_origin_x != 0
        || codestream.siz.tile_origin_y != 0
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::WaveletTransform,
            "the qualified Profile-0 ROI path requires zero image and tile origins",
        ));
    }
    let tiles = tile_rects(codestream)?;
    if tiles.len() != 1
        || !matches!(
            codestream.tiles.as_slice(),
            [tile] if tile.tile_index == 0
                && tile.tile_part_index == 0
                && tile.tile_part_count == Some(1)
        )
    {
        return Err(unsupported(
            None,
            Some(Marker::Sot),
            UnsupportedConstruct::MultipleTiles,
            "the qualified Profile-0 ROI path requires one declared first tile part in one tile",
        ));
    }

    let coding_style = codestream.coding_style.ok_or_else(|| {
        invalid(
            None,
            Some(Marker::Cod),
            "the qualified Profile-0 ROI path requires a main-header COD marker",
        )
    })?;
    let expected_styles = [
        (0_u16, WaveletTransform::Irreversible97),
        (1, WaveletTransform::Irreversible97),
        (2, WaveletTransform::Irreversible97),
        (3, WaveletTransform::Reversible53),
    ];
    if codestream.component_coding_styles.len() != 1
        || codestream.component_coding_styles[0].component_index != 3
        || expected_styles.iter().any(|(component, transform)| {
            codestream
                .effective_coding_style(*component)
                .is_none_or(|style| !p0_06_effective_style_matches(style, *transform))
        })
    {
        return Err(unsupported(
            None,
            Some(Marker::Coc),
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 ROI path requires one reversible component-three COC override over the bounded RPCL style",
        ));
    }
    validate_irreversible97_zero_origin_aligned_tile_grid(codestream, coding_style)?;
    for component_index in 0..codestream.siz.component_count() {
        let style = codestream
            .effective_coding_style(component_index)
            .ok_or(CodestreamError::SizeOverflow)?;
        let component = codestream
            .siz
            .components
            .get(usize::from(component_index))
            .ok_or(CodestreamError::SizeOverflow)?;
        let component_tile = component_tile_rect(codestream, tiles[0], component)?;
        if !coding_style_has_single_precinct(style, component_tile.width, component_tile.height) {
            return Err(unsupported(
                None,
                Some(Marker::Cod),
                UnsupportedConstruct::PacketDecode,
                "the qualified Profile-0 ROI path requires one effective precinct per component resolution",
            ));
        }
    }

    let first_tile_offset = codestream
        .markers
        .iter()
        .find(|segment| segment.marker == Marker::Sot)
        .map(|segment| segment.offset)
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut main_siz_seen = false;
    let mut main_cod_seen = false;
    let mut main_qcd_seen = false;
    let mut qcc_components = Vec::new();
    for segment in &codestream.markers {
        match segment.marker {
            Marker::Soc
            | Marker::Sot
            | Marker::Sod
            | Marker::Eoc
            | Marker::Siz
            | Marker::Cod
            | Marker::Coc
            | Marker::Qcd
            | Marker::Qcc
            | Marker::Rgn
            | Marker::Tlm
            | Marker::Com => {}
            marker => {
                return Err(unsupported(
                    Some(segment.offset),
                    Some(marker),
                    UnsupportedConstruct::MarkerSegment,
                    "marker is outside the qualified Profile-0 ROI component path",
                ));
            }
        }
        if segment.marker == Marker::Siz
            && (segment.offset >= first_tile_offset || core::mem::replace(&mut main_siz_seen, true))
        {
            return Err(unsupported(
                Some(segment.offset),
                Some(Marker::Siz),
                UnsupportedConstruct::MarkerSegment,
                "the qualified Profile-0 ROI path requires exactly one main-header SIZ",
            ));
        }
        if segment.marker == Marker::Cod
            && (segment.offset >= first_tile_offset || core::mem::replace(&mut main_cod_seen, true))
        {
            return Err(unsupported(
                Some(segment.offset),
                Some(Marker::Cod),
                UnsupportedConstruct::MarkerSegment,
                "the qualified Profile-0 ROI path requires exactly one main-header COD",
            ));
        }
        if segment.marker == Marker::Qcd
            && (segment.offset >= first_tile_offset || core::mem::replace(&mut main_qcd_seen, true))
        {
            return Err(unsupported(
                Some(segment.offset),
                Some(Marker::Qcd),
                UnsupportedConstruct::MarkerSegment,
                "the qualified Profile-0 ROI path requires exactly one main-header QCD",
            ));
        }
        if matches!(segment.marker, Marker::Coc | Marker::Qcc | Marker::Tlm)
            && segment.offset >= first_tile_offset
        {
            return Err(unsupported(
                Some(segment.offset),
                Some(segment.marker),
                UnsupportedConstruct::MarkerSegment,
                "component, quantisation, and tile-length overrides are accepted only in the main header",
            ));
        }
        if segment.marker == Marker::Qcc {
            let data = checked_slice(input, segment.data_offset, segment.data_len)?;
            qcc_components.push(data.first().copied().map(u16::from).ok_or_else(|| {
                invalid(
                    Some(segment.offset),
                    Some(Marker::Qcc),
                    "QCC marker omits its component selector",
                )
            })?);
        }
    }
    qcc_components.sort_unstable();
    if qcc_components != [1, 2, 3] {
        return Err(unsupported(
            None,
            Some(Marker::Qcc),
            UnsupportedConstruct::PacketDecode,
            "the qualified Profile-0 ROI path requires QCC overrides for components one, two and three",
        ));
    }
    let effective_maxshift = parse_p0_06_effective_maxshift(input, codestream)?;

    let component_styles = expected_styles
        .iter()
        .map(|(component, _)| {
            codestream
                .effective_coding_style(*component)
                .ok_or(CodestreamError::SizeOverflow)
        })
        .collect::<Result<Vec<_>>>()?;
    let subband_counts = component_styles
        .iter()
        .map(|style| 1usize + usize::from(style.decomposition_levels) * 3)
        .collect::<Vec<_>>();
    let quantization = parse_component_quantization_for_styles(
        input,
        codestream,
        &component_styles,
        &subband_counts,
        19,
        None,
    )?;
    let component_zero = quantization.first().ok_or(CodestreamError::SizeOverflow)?;
    for subband in 0..19 {
        bounded_maxshift_available_bitplanes(
            component_zero.available_bitplanes(subband, coding_style.entropy_coder)?,
            Some(effective_maxshift.shift),
        )?;
    }
    Ok(ValidatedP006ComponentProfile {
        coding_style,
        effective_maxshift,
    })
}

/// Validate the exact tile-header progression schedule qualified by
/// Profile-0 P0.07.
///
/// The schedule has one LRCP volume for resolutions zero through two in tile
/// zero's first tile part, followed by one LRCP volume for resolution three in
/// its second tile part. The other 255 tiles use the COD-declared RLCP order.
/// Keeping this admission separate from the general P0.03 main-header POC
/// parser prevents either bounded contract from silently widening the other.
fn validate_part1_p0_07_progression_change_component_profile(
    input: &[u8],
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    if codestream.kind != CodestreamKind::J2k {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 P0.07 path is limited to raw Part 1 codestreams",
        ));
    }
    if codestream.siz.capabilities != 1
        || codestream.siz.reference_grid_width != 2048
        || codestream.siz.reference_grid_height != 2048
        || codestream.siz.image_origin_x != 0
        || codestream.siz.image_origin_y != 0
        || codestream.siz.tile_width != 128
        || codestream.siz.tile_height != 128
        || codestream.siz.tile_origin_x != 0
        || codestream.siz.tile_origin_y != 0
        || codestream.siz.components.len() != 3
        || codestream.siz.components.iter().any(|component| {
            component.bits_per_sample != 12
                || !component.signed
                || component.horizontal_separation != 1
                || component.vertical_separation != 1
        })
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "the qualified Profile-0 P0.07 path requires a 2048-by-2048 signed 12-bit three-component image on a 128-by-128 origin-aligned tile grid",
        ));
    }

    let coding_style = codestream.coding_style.ok_or_else(|| {
        invalid(
            None,
            Some(Marker::Cod),
            "the qualified Profile-0 P0.07 path requires a main-header COD marker",
        )
    })?;
    if !coding_style.sop_markers
        || !coding_style.eph_markers
        || coding_style.progression_order != ProgressionOrder::Rlcp
        || coding_style.layers != 8
        || coding_style.multiple_component_transform
        || coding_style.decomposition_levels != 3
        || coding_style.code_block_width_exponent != 6
        || coding_style.code_block_height_exponent != 6
        || coding_style.code_block_style != 0
        || coding_style.transform != WaveletTransform::Reversible53
        || coding_style.entropy_coder != EntropyCoder::ClassicTier1
        || coding_style.precincts_declared
        || !codestream.component_coding_styles.is_empty()
    {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::ProgressionOrder,
            "the qualified Profile-0 P0.07 path requires eight-layer RLCP reversible coding with SOP, EPH, three decomposition levels, 64-by-64 code-blocks and default precincts",
        ));
    }

    let tile_rects = tile_rects(codestream)?;
    if tile_rects.len() != 256 || codestream.tiles.len() != 257 {
        return Err(unsupported(
            None,
            Some(Marker::Sot),
            UnsupportedConstruct::MultipleTiles,
            "the qualified Profile-0 P0.07 path requires 256 tiles and 257 retained tile parts",
        ));
    }
    for (position, tile_part) in codestream.tiles.iter().enumerate() {
        let expected = match position {
            0 => (0_u16, 0_u8, None),
            1..=255 => (
                u16::try_from(position).map_err(|_| CodestreamError::SizeOverflow)?,
                0,
                Some(1),
            ),
            256 => (0, 1, Some(2)),
            _ => return Err(CodestreamError::SizeOverflow),
        };
        if (
            tile_part.tile_index,
            tile_part.tile_part_index,
            tile_part.tile_part_count,
        ) != expected
        {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "the qualified Profile-0 P0.07 path requires tile zero part zero, tiles one through 255, then tile zero part one, with its exact declared part counts",
            ));
        }
    }
    for tile_index in 0..256_u16 {
        validate_retained_tile_parts_for_tile(codestream, tile_index)?;
    }

    let first_tile_offset = codestream
        .markers
        .iter()
        .find(|segment| segment.marker == Marker::Sot)
        .map(|segment| segment.offset)
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut main_siz = 0_u8;
    let mut main_cod = 0_u8;
    let mut main_qcd = 0_u8;
    for segment in codestream
        .markers
        .iter()
        .take_while(|segment| segment.offset < first_tile_offset)
    {
        match segment.marker {
            Marker::Soc | Marker::Com => {}
            Marker::Siz => main_siz = main_siz.saturating_add(1),
            Marker::Cod => main_cod = main_cod.saturating_add(1),
            Marker::Qcd => main_qcd = main_qcd.saturating_add(1),
            marker => {
                return Err(unsupported(
                    Some(segment.offset),
                    Some(marker),
                    UnsupportedConstruct::MarkerSegment,
                    "marker is outside the qualified Profile-0 P0.07 main header",
                ));
            }
        }
    }
    if (main_siz, main_cod, main_qcd) != (1, 1, 1) {
        return Err(unsupported(
            None,
            Some(Marker::Qcd),
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 P0.07 path requires exactly one main-header SIZ, COD and QCD",
        ));
    }
    let main_cod_segment = codestream
        .markers
        .iter()
        .find(|segment| segment.marker == Marker::Cod && segment.offset < first_tile_offset)
        .ok_or(CodestreamError::SizeOverflow)?;
    if !p0_07_main_cod_payload_matches(checked_slice(
        input,
        main_cod_segment.data_offset,
        main_cod_segment.data_len,
    )?) {
        return Err(unsupported(
            Some(main_cod_segment.offset),
            Some(Marker::Cod),
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 P0.07 path requires its exact ten-byte COD payload with no reserved Scod bits",
        ));
    }
    if codestream.markers.iter().any(|segment| {
        segment.offset >= first_tile_offset
            && !matches!(
                segment.marker,
                Marker::Sot | Marker::Poc | Marker::Plt | Marker::Sod | Marker::Eoc
            )
    }) {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "marker is outside the qualified Profile-0 P0.07 tile headers",
        ));
    }

    for tile_part in &codestream.tiles {
        let payload_offset = tile_part
            .payload_offset
            .ok_or(CodestreamError::SizeOverflow)?;
        let sod_index = codestream
            .markers
            .iter()
            .position(|segment| {
                segment.marker == Marker::Sod && segment.data_offset == payload_offset
            })
            .ok_or(CodestreamError::SizeOverflow)?;
        let sot_index = codestream.markers[..sod_index]
            .iter()
            .rposition(|segment| segment.marker == Marker::Sot)
            .ok_or(CodestreamError::SizeOverflow)?;
        let header = &codestream.markers[sot_index..=sod_index];
        let expected_poc = match (tile_part.tile_index, tile_part.tile_part_index) {
            (0, 0) => Some([0_u8, 0, 0, 9, 3, 3, 0]),
            (0, 1) => Some([0_u8, 0, 0, 9, 8, 3, 0]),
            _ => None,
        };
        let expected_markers: &[Marker] = if expected_poc.is_some() {
            &[Marker::Sot, Marker::Poc, Marker::Plt, Marker::Sod]
        } else {
            &[Marker::Sot, Marker::Plt, Marker::Sod]
        };
        if header
            .iter()
            .map(|segment| segment.marker)
            .ne(expected_markers.iter().copied())
        {
            return Err(unsupported(
                header.first().map(|segment| segment.offset),
                Some(Marker::Poc),
                UnsupportedConstruct::MarkerSegment,
                "the qualified Profile-0 P0.07 path requires one PLT per tile part and POC only in tile zero's two parts",
            ));
        }
        if let Some(expected_poc) = expected_poc {
            let poc = header
                .iter()
                .find(|segment| segment.marker == Marker::Poc)
                .ok_or(CodestreamError::SizeOverflow)?;
            if checked_slice(input, poc.data_offset, poc.data_len)? != expected_poc {
                return Err(unsupported(
                    Some(poc.offset),
                    Some(Marker::Poc),
                    UnsupportedConstruct::ProgressionOrder,
                    "the qualified Profile-0 P0.07 path requires its exact two LRCP progression volumes",
                ));
            }
        }
        let (packet_lengths, _) = tile_part_packet_lengths_from_plt(input, codestream, tile_part)?
            .ok_or_else(|| {
                invalid(
                    Some(payload_offset),
                    Some(Marker::Plt),
                    "the qualified Profile-0 P0.07 path requires PLT packet lengths",
                )
            })?;
        let expected_packets = if tile_part.tile_index == 0 && tile_part.tile_part_index == 0 {
            72
        } else if tile_part.tile_index == 0 && tile_part.tile_part_index == 1 {
            24
        } else {
            96
        };
        if packet_lengths.len() != expected_packets {
            return Err(unsupported(
                Some(payload_offset),
                Some(Marker::Plt),
                UnsupportedConstruct::PacketDecode,
                "the qualified Profile-0 P0.07 path requires a 72+24 tile-zero packet split and 96 packets in every other tile",
            ));
        }
    }

    let quantization = parse_component_quantization(input, codestream, 10)?;
    let expected_exponents = [14_u8, 15, 15, 16, 15, 15, 16, 15, 15, 16];
    if quantization.len() != 3
        || quantization.iter().any(|component| {
            component.style != transform::QuantizationStyle::NoQuantization
                || component.guard_bits != 1
                || component.steps.len() != expected_exponents.len()
                || component
                    .steps
                    .iter()
                    .zip(expected_exponents)
                    .any(|(step, exponent)| step.exponent != exponent || step.mantissa != 0)
        })
    {
        return Err(unsupported(
            None,
            Some(Marker::Qcd),
            UnsupportedConstruct::PacketDecode,
            "the qualified Profile-0 P0.07 path requires its exact reversible QCD exponents",
        ));
    }
    Ok(coding_style)
}

/// True when the codestream matches the exact tile-header POC profile
/// qualified by Profile-0 P0.07.
pub fn is_supported_part1_p0_07_progression_change_component_profile(
    input: &[u8],
    codestream: &Codestream,
) -> bool {
    validate_part1_p0_07_progression_change_component_profile(input, codestream).is_ok()
}

fn p0_08_exponent(subband: usize) -> u8 {
    if subband == 0 {
        11
    } else if subband.is_multiple_of(3) {
        13
    } else {
        12
    }
}

fn p0_08_quantization_payload_matches(
    data: &[u8],
    component: Option<u8>,
    subband_count: usize,
) -> bool {
    let selector_len = usize::from(component.is_some());
    if data.len() != selector_len + 1 + subband_count {
        return false;
    }
    if let Some(component) = component
        && data[0] != component
    {
        return false;
    }
    data[selector_len] == 0x80
        && data[selector_len + 1..]
            .iter()
            .enumerate()
            .all(|(subband, value)| *value == p0_08_exponent(subband) << 3)
}

fn p0_08_cod_payload_matches(data: &[u8]) -> bool {
    data == [0x06, 0x04, 0x00, 0x1e, 0x00, 0x07, 0x04, 0x04, 0x00, 0x01]
}

fn p0_08_coc_payload_matches(data: &[u8], component: u8) -> bool {
    let expected = match component {
        0 => [0, 0, 6, 4, 4, 0, 1],
        1 => [1, 0, 7, 3, 3, 0, 1],
        2 => [2, 0, 8, 4, 4, 0, 1],
        _ => return false,
    };
    data == expected
}

fn p0_08_effective_style_matches(
    style: CodingStyleMarker,
    decomposition_levels: u8,
    code_block_exponent: u8,
) -> bool {
    style.sop_markers
        && style.eph_markers
        && style.progression_order == ProgressionOrder::Cprl
        && style.layers == 30
        && !style.multiple_component_transform
        && style.decomposition_levels == decomposition_levels
        && style.code_block_width_exponent == code_block_exponent
        && style.code_block_height_exponent == code_block_exponent
        && style.code_block_style == 0
        && style.transform == WaveletTransform::Reversible53
        && style.entropy_coder == EntropyCoder::ClassicTier1
        && !style.precincts_declared
}

fn validate_part1_p0_08_heterogeneous_reversible_component_profile(
    input: &[u8],
    codestream: &Codestream,
    discard_levels: u8,
) -> Result<CodingStyleMarker> {
    if discard_levels != 5 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "the qualified Profile-0 P0.08 path requires exactly five discarded resolution levels",
        ));
    }
    if codestream.kind != CodestreamKind::J2k
        || codestream.siz.capabilities != 1
        || codestream.siz.reference_grid_width != 513
        || codestream.siz.reference_grid_height != 3072
        || codestream.siz.image_origin_x != 0
        || codestream.siz.image_origin_y != 0
        || codestream.siz.tile_width != 513
        || codestream.siz.tile_height != 3072
        || codestream.siz.tile_origin_x != 0
        || codestream.siz.tile_origin_y != 0
        || codestream.siz.components.len() != 3
        || codestream.siz.components.iter().any(|component| {
            component.bits_per_sample != 12
                || !component.signed
                || component.horizontal_separation != 1
                || component.vertical_separation != 1
        })
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "the qualified Profile-0 P0.08 path requires one 513-by-3072 tile with three signed 12-bit unit-sampled components",
        ));
    }
    if !matches!(
        codestream.tiles.as_slice(),
        [tile] if tile.tile_index == 0
            && tile.tile_part_index == 0
            && tile.tile_part_count == Some(1)
    ) || tile_rects(codestream)?.len() != 1
    {
        return Err(unsupported(
            None,
            Some(Marker::Sot),
            UnsupportedConstruct::MultipleTiles,
            "the qualified Profile-0 P0.08 path requires one declared tile part in one tile",
        ));
    }
    validate_retained_tile_parts_for_tile(codestream, 0)?;

    let expected_markers = [
        Marker::Siz,
        Marker::Cod,
        Marker::Coc,
        Marker::Coc,
        Marker::Coc,
        Marker::Qcd,
        Marker::Qcc,
        Marker::Qcc,
        Marker::Com,
        Marker::Sot,
        Marker::Sod,
        Marker::Eoc,
    ];
    if codestream
        .markers
        .iter()
        .map(|segment| segment.marker)
        .ne(expected_markers)
    {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 P0.08 path requires its exact main-header marker order and an empty tile-part header",
        ));
    }

    let cod = &codestream.markers[1];
    if !p0_08_cod_payload_matches(checked_slice(input, cod.data_offset, cod.data_len)?) {
        return Err(unsupported(
            Some(cod.offset),
            Some(Marker::Cod),
            UnsupportedConstruct::ProgressionOrder,
            "the qualified Profile-0 P0.08 path requires its exact thirty-layer CPRL COD payload",
        ));
    }
    for (component, segment) in codestream.markers[2..5].iter().enumerate() {
        if !p0_08_coc_payload_matches(
            checked_slice(input, segment.data_offset, segment.data_len)?,
            u8::try_from(component).map_err(|_| CodestreamError::SizeOverflow)?,
        ) {
            return Err(unsupported(
                Some(segment.offset),
                Some(Marker::Coc),
                UnsupportedConstruct::MarkerSegment,
                "the qualified Profile-0 P0.08 path requires its exact three COC payloads",
            ));
        }
    }
    let qcd = &codestream.markers[5];
    let qcc_zero = &codestream.markers[6];
    let qcc_two = &codestream.markers[7];
    if !p0_08_quantization_payload_matches(
        checked_slice(input, qcd.data_offset, qcd.data_len)?,
        None,
        22,
    ) || !p0_08_quantization_payload_matches(
        checked_slice(input, qcc_zero.data_offset, qcc_zero.data_len)?,
        Some(0),
        19,
    ) || !p0_08_quantization_payload_matches(
        checked_slice(input, qcc_two.data_offset, qcc_two.data_len)?,
        Some(2),
        25,
    ) {
        return Err(unsupported(
            None,
            Some(Marker::Qcc),
            UnsupportedConstruct::PacketDecode,
            "the qualified Profile-0 P0.08 path requires its exact QCD and component-zero/component-two QCC payloads",
        ));
    }

    let expected_styles = [(6_u8, 6_u8), (7, 5), (8, 6)];
    let component_styles = expected_styles
        .iter()
        .enumerate()
        .map(|(component, (decomposition_levels, code_block_exponent))| {
            let style = codestream
                .effective_coding_style(
                    u16::try_from(component).map_err(|_| CodestreamError::SizeOverflow)?,
                )
                .ok_or(CodestreamError::SizeOverflow)?;
            if !p0_08_effective_style_matches(
                style,
                *decomposition_levels,
                *code_block_exponent,
            ) {
                return Err(unsupported(
                    None,
                    Some(Marker::Coc),
                    UnsupportedConstruct::MarkerSegment,
                    "the qualified Profile-0 P0.08 path requires its exact effective component styles",
                ));
            }
            Ok(style)
        })
        .collect::<Result<Vec<_>>>()?;
    let tile_rect = tile_rects(codestream)?[0];
    for (component_index, style) in component_styles.iter().enumerate() {
        let component = &codestream.siz.components[component_index];
        let component_tile = component_tile_rect(codestream, tile_rect, component)?;
        if !coding_style_has_single_precinct(*style, component_tile.width, component_tile.height) {
            return Err(unsupported(
                None,
                Some(Marker::Coc),
                UnsupportedConstruct::PacketDecode,
                "the qualified Profile-0 P0.08 path requires one precinct per effective component resolution",
            ));
        }
    }
    let subband_counts = [19_usize, 22, 25];
    let quantization = parse_component_quantization_for_styles(
        input,
        codestream,
        &component_styles,
        &subband_counts,
        22,
        None,
    )?;
    if quantization
        .iter()
        .zip(subband_counts)
        .any(|(component, subband_count)| {
            component.style != transform::QuantizationStyle::NoQuantization
                || component.guard_bits != 4
                || component.steps.len() != subband_count
                || component.steps.iter().enumerate().any(|(subband, step)| {
                    step.exponent != p0_08_exponent(subband) || step.mantissa != 0
                })
        })
    {
        return Err(unsupported(
            None,
            Some(Marker::Qcc),
            UnsupportedConstruct::PacketDecode,
            "the qualified Profile-0 P0.08 path requires its exact effective reversible quantisation",
        ));
    }
    component_styles
        .first()
        .copied()
        .ok_or(CodestreamError::SizeOverflow)
}

/// True when the codestream matches the exact heterogeneous reversible
/// component profile qualified by Profile-0 P0.08.
pub fn is_supported_part1_p0_08_heterogeneous_reversible_component_profile(
    input: &[u8],
    codestream: &Codestream,
    discard_levels: u8,
) -> bool {
    validate_part1_p0_08_heterogeneous_reversible_component_profile(
        input,
        codestream,
        discard_levels,
    )
    .is_ok()
}

fn p0_10_exponent(subband: usize) -> u8 {
    if subband == 0 {
        11
    } else if subband.is_multiple_of(3) {
        13
    } else {
        12
    }
}

fn p0_10_cod_payload_matches(data: &[u8]) -> bool {
    data == [0x00, 0x00, 0x00, 0x02, 0x01, 0x03, 0x04, 0x04, 0x00, 0x01]
}

fn p0_10_qcd_payload_matches(data: &[u8]) -> bool {
    data.len() == 11
        && data[0] == 0
        && data[1..]
            .iter()
            .enumerate()
            .all(|(subband, value)| *value == p0_10_exponent(subband) << 3)
}

fn validate_part1_p0_10_subsampled_reversible_mct_component_profile(
    input: &[u8],
    codestream: &Codestream,
) -> Result<CodingStyleMarker> {
    if codestream.kind != CodestreamKind::J2k
        || codestream.siz.capabilities != 1
        || codestream.siz.reference_grid_width != 256
        || codestream.siz.reference_grid_height != 256
        || codestream.siz.image_origin_x != 0
        || codestream.siz.image_origin_y != 0
        || codestream.siz.tile_width != 128
        || codestream.siz.tile_height != 128
        || codestream.siz.tile_origin_x != 0
        || codestream.siz.tile_origin_y != 0
        || codestream.siz.components.len() != 3
        || codestream.siz.components.iter().any(|component| {
            component.bits_per_sample != 8
                || component.signed
                || component.horizontal_separation != 4
                || component.vertical_separation != 4
        })
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "the qualified Profile-0 P0.10 path requires a 256-by-256 origin-aligned four-tile grid with three unsigned 8-bit 4-by-4 sampled components",
        ));
    }

    let tiles = tile_rects(codestream)?;
    let expected_tiles = [
        (0_u16, 0_u32, 0_u32, 0_u32, 0_u32),
        (1, 1, 0, 128, 0),
        (2, 0, 1, 0, 128),
        (3, 1, 1, 128, 128),
    ];
    if tiles.len() != expected_tiles.len()
        || tiles
            .iter()
            .zip(expected_tiles)
            .any(|(tile, (tile_index, tile_x, tile_y, x, y))| {
                tile.tile_index != tile_index
                    || tile.tile_x != tile_x
                    || tile.tile_y != tile_y
                    || tile.x != x
                    || tile.y != y
                    || tile.width != 128
                    || tile.height != 128
            })
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::MultipleTiles,
            "the qualified Profile-0 P0.10 path requires its exact two-by-two tile grid",
        ));
    }

    let expected_parts = [
        (0_u16, 0_u8, None),
        (1, 0, None),
        (2, 0, None),
        (3, 0, None),
        (0, 1, Some(2)),
        (1, 1, Some(2)),
        (3, 1, Some(2)),
        (2, 1, None),
        (2, 2, None),
    ];
    if codestream.tiles.len() != expected_parts.len()
        || codestream.tiles.iter().zip(expected_parts).any(
            |(tile, (tile_index, tile_part_index, tile_part_count))| {
                tile.tile_index != tile_index
                    || tile.tile_part_index != tile_part_index
                    || tile.tile_part_count != tile_part_count
                    || tile.payload_offset.is_none()
                    || tile.payload_len.is_none()
            },
        )
    {
        return Err(unsupported(
            None,
            Some(Marker::Sot),
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 P0.10 path requires its exact nine-part Profile-0 tile sequence and declared counts",
        ));
    }
    for tile_index in 0..4 {
        validate_retained_tile_parts_for_tile(codestream, tile_index)?;
    }

    let mut expected_markers = alloc::vec![Marker::Siz, Marker::Cod, Marker::Qcd];
    for _ in 0..expected_parts.len() {
        expected_markers.extend([Marker::Sot, Marker::Sod]);
    }
    expected_markers.push(Marker::Eoc);
    if codestream
        .markers
        .iter()
        .map(|segment| segment.marker)
        .ne(expected_markers)
    {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 P0.10 path requires only SIZ, COD and QCD in the main header and empty tile-part headers",
        ));
    }

    let cod = &codestream.markers[1];
    let qcd = &codestream.markers[2];
    if !p0_10_cod_payload_matches(checked_slice(input, cod.data_offset, cod.data_len)?)
        || !p0_10_qcd_payload_matches(checked_slice(input, qcd.data_offset, qcd.data_len)?)
    {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 P0.10 path requires its exact COD and QCD payloads",
        ));
    }

    let coding_style = uniform_effective_coding_style(codestream)?;
    if coding_style.sop_markers
        || coding_style.eph_markers
        || coding_style.progression_order != ProgressionOrder::Lrcp
        || coding_style.layers != 2
        || !coding_style.multiple_component_transform
        || coding_style.decomposition_levels != 3
        || coding_style.code_block_width_exponent != 6
        || coding_style.code_block_height_exponent != 6
        || coding_style.code_block_style != 0
        || coding_style.transform != WaveletTransform::Reversible53
        || coding_style.entropy_coder != EntropyCoder::ClassicTier1
        || coding_style.precincts_declared
    {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "the qualified Profile-0 P0.10 path requires two-layer LRCP reversible-MCT coding with three decompositions and default precincts",
        ));
    }
    for tile in &tiles {
        for component in &codestream.siz.components {
            let component_tile = component_tile_rect(codestream, *tile, component)?;
            if component_tile.width != 32
                || component_tile.height != 32
                || !coding_style_has_single_precinct(
                    coding_style,
                    component_tile.width,
                    component_tile.height,
                )
            {
                return Err(unsupported(
                    None,
                    Some(Marker::Siz),
                    UnsupportedConstruct::PacketDecode,
                    "the qualified Profile-0 P0.10 path requires one 32-by-32 precinct per component-tile resolution",
                ));
            }
        }
    }

    let quantization = parse_component_quantization(input, codestream, 10)?;
    if quantization.iter().any(|component| {
        component.style != transform::QuantizationStyle::NoQuantization
            || component.guard_bits != 0
            || component.steps.len() != 10
            || component.steps.iter().enumerate().any(|(subband, step)| {
                step.exponent != p0_10_exponent(subband) || step.mantissa != 0
            })
    }) {
        return Err(unsupported(
            None,
            Some(Marker::Qcd),
            UnsupportedConstruct::PacketDecode,
            "the qualified Profile-0 P0.10 path requires its exact effective reversible quantisation",
        ));
    }
    Ok(coding_style)
}

/// True when the codestream matches the exact multi-tile subsampled
/// reversible-MCT profile qualified by Profile-0 P0.10.
pub fn is_supported_part1_p0_10_subsampled_reversible_mct_component_profile(
    input: &[u8],
    codestream: &Codestream,
) -> bool {
    validate_part1_p0_10_subsampled_reversible_mct_component_profile(input, codestream).is_ok()
}

fn p0_13_cod_payload_matches(data: &[u8]) -> bool {
    data == [0x00, 0x01, 0x00, 0x01, 0x01, 0x01, 0x03, 0x03, 0x10, 0x01]
}

fn p0_13_coc_payload_matches(data: &[u8]) -> bool {
    data == [0x00, 0x02, 0x00, 0x01, 0x04, 0x04, 0x00, 0x01]
}

fn p0_13_qcd_payload_matches(data: &[u8]) -> bool {
    data == [0x40, 0x40, 0x48, 0x48, 0x50]
}

fn p0_13_qcc_payload_matches(data: &[u8], component_index: u16) -> bool {
    let guard = match component_index {
        1 => 0x60,
        2 => 0x40,
        _ => return false,
    };
    data == [
        (component_index >> 8) as u8,
        component_index as u8,
        guard,
        0x48,
        0x50,
        0x50,
        0x58,
    ]
}

fn p0_13_poc_payload_matches(data: &[u8]) -> bool {
    data == [
        0x00, 0x00, 0x00, 0x00, 0x01, 0x21, 0x00, 0x80, 0x01, 0x00, 0x00, 0x80, 0x00, 0x01, 0x21,
        0x01, 0x01, 0x04,
    ]
}

fn parse_p0_13_main_maxshift(input: &[u8], codestream: &Codestream) -> Result<BoundedTileMaxshift> {
    let first_tile_offset = codestream
        .markers
        .iter()
        .find(|segment| segment.marker == Marker::Sot)
        .map(|segment| segment.offset)
        .ok_or(CodestreamError::SizeOverflow)?;
    let segments = codestream
        .markers
        .iter()
        .filter(|segment| segment.marker == Marker::Rgn)
        .collect::<Vec<_>>();
    let [segment] = segments.as_slice() else {
        return Err(unsupported(
            segments.get(1).map(|segment| segment.offset),
            Some(Marker::Rgn),
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 P0.13 path requires exactly one main-header RGN assignment",
        ));
    };
    if segment.offset >= first_tile_offset
        || checked_slice(input, segment.data_offset, segment.data_len)? != [0x00, 0x03, 0x00, 0x0b]
    {
        return Err(unsupported(
            Some(segment.offset),
            Some(Marker::Rgn),
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 P0.13 path requires the two-byte component-three Maxshift-eleven assignment in the main header",
        ));
    }
    Ok(BoundedTileMaxshift {
        tile_index: 0,
        component_index: 3,
        shift: 11,
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ValidatedP013MainMaxshift(BoundedTileMaxshift);

fn recheck_validator_granted_p0_13_main_maxshift(
    input: &[u8],
    codestream: &Codestream,
    tile_index: u16,
    granted: Option<ValidatedP013MainMaxshift>,
) -> Result<Option<BoundedTileMaxshift>> {
    let Some(ValidatedP013MainMaxshift(granted)) = granted else {
        return Ok(None);
    };
    let exact = BoundedTileMaxshift {
        tile_index: 0,
        component_index: 3,
        shift: 11,
    };
    if granted != exact || parse_p0_13_main_maxshift(input, codestream)? != granted {
        return Err(unsupported(
            None,
            Some(Marker::Rgn),
            UnsupportedConstruct::PacketDecode,
            "the validator-granted main-header Maxshift must match the exact P0.13 tile-zero/component-three shift-eleven assignment",
        ));
    }
    Ok((granted.tile_index == tile_index).then_some(granted))
}

fn p0_13_effective_style_matches(style: CodingStyleMarker, component_index: u16) -> bool {
    style.entropy_coder == EntropyCoder::ClassicTier1
        && !style.sop_markers
        && !style.eph_markers
        && style.progression_order == ProgressionOrder::Rlcp
        && style.layers == 1
        && style.multiple_component_transform
        && style.decomposition_levels == 1
        && style.code_block_width_exponent == if component_index == 2 { 6 } else { 5 }
        && style.code_block_height_exponent == if component_index == 2 { 6 } else { 5 }
        && style.code_block_style == if component_index == 2 { 0 } else { 16 }
        && style.transform == WaveletTransform::Reversible53
        && !style.precincts_declared
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ValidatedP013PacketRoute {
    coding_style: CodingStyleMarker,
    main_maxshift: ValidatedP013MainMaxshift,
}

fn validate_part1_p0_13_high_component_progression_profile(
    input: &[u8],
    codestream: &Codestream,
) -> Result<ValidatedP013PacketRoute> {
    if codestream.kind != CodestreamKind::J2k
        || codestream.siz.capabilities != 1
        || codestream.siz.reference_grid_width != 1
        || codestream.siz.reference_grid_height != 1
        || codestream.siz.image_origin_x != 0
        || codestream.siz.image_origin_y != 0
        || codestream.siz.tile_width != 1
        || codestream.siz.tile_height != 1
        || codestream.siz.tile_origin_x != 0
        || codestream.siz.tile_origin_y != 0
        || codestream.siz.components.len() != 257
        || codestream.siz.components.iter().any(|component| {
            component.bits_per_sample != 8
                || component.signed
                || component.horizontal_separation != 1
                || component.vertical_separation != 1
        })
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentCount,
            "the qualified Profile-0 P0.13 path requires one unsigned 8-bit sample in each of exactly 257 unit-sampled components",
        ));
    }
    let tiles = tile_rects(codestream)?;
    if tiles.len() != 1
        || tiles[0].tile_index != 0
        || tiles[0].width != 1
        || tiles[0].height != 1
        || !matches!(
            codestream.tiles.as_slice(),
            [tile] if tile.tile_index == 0
                && tile.tile_part_index == 0
                && tile.tile_part_count == Some(1)
                && tile.payload_offset.is_some()
                && tile.payload_len.is_some()
        )
    {
        return Err(unsupported(
            None,
            Some(Marker::Sot),
            UnsupportedConstruct::MultipleTiles,
            "the qualified Profile-0 P0.13 path requires one declared tile part in one 1-by-1 tile",
        ));
    }

    let expected_markers = [
        Marker::Siz,
        Marker::Cod,
        Marker::Coc,
        Marker::Qcd,
        Marker::Qcc,
        Marker::Qcc,
        Marker::Rgn,
        Marker::Poc,
        Marker::Com,
        Marker::Sot,
        Marker::Sod,
        Marker::Eoc,
    ];
    if codestream
        .markers
        .iter()
        .map(|segment| segment.marker)
        .ne(expected_markers)
    {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 P0.13 path requires its exact main-header marker order and an empty tile-part header",
        ));
    }
    let markers = &codestream.markers;
    if !p0_13_cod_payload_matches(checked_slice(
        input,
        markers[1].data_offset,
        markers[1].data_len,
    )?) || !p0_13_coc_payload_matches(checked_slice(
        input,
        markers[2].data_offset,
        markers[2].data_len,
    )?) || !p0_13_qcd_payload_matches(checked_slice(
        input,
        markers[3].data_offset,
        markers[3].data_len,
    )?) || !p0_13_qcc_payload_matches(
        checked_slice(input, markers[4].data_offset, markers[4].data_len)?,
        1,
    ) || !p0_13_qcc_payload_matches(
        checked_slice(input, markers[5].data_offset, markers[5].data_len)?,
        2,
    ) || !p0_13_poc_payload_matches(checked_slice(
        input,
        markers[7].data_offset,
        markers[7].data_len,
    )?) || markers[8].data_len != 43
    {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 P0.13 path requires its exact COD, COC, QCD, QCC, POC and COM field lengths",
        ));
    }
    let main_maxshift = ValidatedP013MainMaxshift(parse_p0_13_main_maxshift(input, codestream)?);

    let coding_style = codestream.coding_style.ok_or_else(|| {
        invalid(
            None,
            Some(Marker::Cod),
            "the qualified Profile-0 P0.13 path requires a main-header COD marker",
        )
    })?;
    if codestream.component_coding_styles.len() != 1
        || codestream.component_coding_styles[0].component_index != 2
        || (0..codestream.siz.component_count()).any(|component_index| {
            codestream
                .effective_coding_style(component_index)
                .is_none_or(|style| !p0_13_effective_style_matches(style, component_index))
        })
    {
        return Err(unsupported(
            None,
            Some(Marker::Coc),
            UnsupportedConstruct::MarkerSegment,
            "the qualified Profile-0 P0.13 path requires only the exact component-two COC override",
        ));
    }
    for component_index in 0..codestream.siz.component_count() {
        let component = codestream
            .siz
            .components
            .get(usize::from(component_index))
            .ok_or(CodestreamError::SizeOverflow)?;
        let component_tile = component_tile_rect(codestream, tiles[0], component)?;
        let style = codestream
            .effective_coding_style(component_index)
            .ok_or(CodestreamError::SizeOverflow)?;
        if !coding_style_has_single_precinct(style, component_tile.width, component_tile.height) {
            return Err(unsupported(
                None,
                Some(Marker::Cod),
                UnsupportedConstruct::PacketDecode,
                "the qualified Profile-0 P0.13 path requires one precinct in each effective component resolution",
            ));
        }
    }

    let component_styles = (0..codestream.siz.component_count())
        .map(|component_index| {
            codestream
                .effective_coding_style(component_index)
                .ok_or(CodestreamError::SizeOverflow)
        })
        .collect::<Result<Vec<_>>>()?;
    let subband_counts = alloc::vec![4_usize; component_styles.len()];
    let quantization = parse_component_quantization_for_styles(
        input,
        codestream,
        &component_styles,
        &subband_counts,
        4,
        None,
    )?;
    for (component_index, component) in quantization.iter().enumerate() {
        let (guard_bits, exponents) = match component_index {
            1 => (3, [9, 10, 10, 11]),
            2 => (2, [9, 10, 10, 11]),
            _ => (2, [8, 9, 9, 10]),
        };
        if component.style != transform::QuantizationStyle::NoQuantization
            || component.guard_bits != guard_bits
            || component.steps.len() != 4
            || component
                .steps
                .iter()
                .zip(exponents)
                .any(|(step, exponent)| step.exponent != exponent || step.mantissa != 0)
        {
            return Err(unsupported(
                None,
                Some(Marker::Qcc),
                UnsupportedConstruct::PacketDecode,
                "the qualified Profile-0 P0.13 path requires its exact default and component-one/component-two reversible quantisation",
            ));
        }
    }
    Ok(ValidatedP013PacketRoute {
        coding_style,
        main_maxshift,
    })
}

/// True when the codestream matches the exact 257-component progression and
/// ROI profile qualified by Profile-0 P0.13.
pub fn is_supported_part1_p0_13_high_component_progression_profile(
    input: &[u8],
    codestream: &Codestream,
) -> bool {
    validate_part1_p0_13_high_component_progression_profile(input, codestream).is_ok()
}

fn validate_bounded_maxshift_plane_widths(
    input: &[u8],
    codestream: &Codestream,
    coding_style: CodingStyleMarker,
    maxshift: BoundedTileMaxshift,
) -> Result<()> {
    let subband_count = 1usize
        .checked_add(
            usize::from(coding_style.decomposition_levels)
                .checked_mul(3)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .ok_or(CodestreamError::SizeOverflow)?;
    let selected = [maxshift.component_index];
    let quantization = parse_component_quantization_for_selection(
        input,
        codestream,
        subband_count,
        Some(&selected),
    )?;
    let component = quantization
        .get(usize::from(maxshift.component_index))
        .ok_or(CodestreamError::SizeOverflow)?;
    for subband in 0..subband_count {
        bounded_maxshift_available_bitplanes(
            component.available_bitplanes(subband, coding_style.entropy_coder)?,
            Some(maxshift.shift),
        )?;
    }
    Ok(())
}

/// True when a raw Part 1 row is admitted by the bounded non-MCT selective
/// irreversible component decoder. This predicate does not imply that a full
/// image allocation is practical; callers should submit a region or discard
/// request for large NITF-derived rows.
pub fn is_supported_part1_selective_irreversible97_component_profile(
    input: &[u8],
    codestream: &Codestream,
) -> bool {
    validate_supported_native_irreversible_component_selective_profile(input, codestream).is_ok()
}

fn validate_supported_native_two_decomp_multitile_profile(
    codestream: &Codestream,
    expected_bits_per_sample: u8,
    expected_components: u16,
    expected_mct: bool,
    profile_name: &'static str,
) -> Result<CodingStyleMarker> {
    if codestream.kind != CodestreamKind::J2k {
        return Err(unsupported(
            None,
            None,
            UnsupportedConstruct::MarkerSegment,
            "native multi-tile DWT2 decode is limited to raw J2K Part 1 codestreams",
        ));
    }
    if let Some((marker, _detail)) = unsupported_part1_profile_marker(codestream, false, false) {
        return Err(unsupported(
            None,
            Some(marker),
            UnsupportedConstruct::MarkerSegment,
            "marker segment is outside native multi-tile DWT2 decode",
        ));
    }
    if codestream.siz.component_count() != expected_components {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentCount,
            if expected_components == 1 {
                "native grayscale multi-tile DWT2 decode accepts one component"
            } else {
                "native RGB multi-tile DWT2 decode accepts three components"
            },
        ));
    }
    if codestream
        .siz
        .components
        .iter()
        .any(|component| component.bits_per_sample != expected_bits_per_sample || component.signed)
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::SamplePrecision,
            if expected_bits_per_sample == 8 {
                "native u8 multi-tile DWT2 decode accepts unsigned 8-bit samples only"
            } else {
                "native u16 multi-tile DWT2 decode accepts unsigned 16-bit samples only"
            },
        ));
    }
    if codestream
        .siz
        .components
        .iter()
        .any(|component| component.horizontal_separation != 1 || component.vertical_separation != 1)
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentSampling,
            "native multi-tile DWT2 decode requires unit component sampling",
        ));
    }
    if codestream.siz.tile_count_x()? == 1 && codestream.siz.tile_count_y()? == 1 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::MultipleTiles,
            "native multi-tile DWT2 decode requires more than one tile",
        ));
    }
    let component_samples =
        native_part1_profile_component_samples(codestream).ok_or(CodestreamError::SizeOverflow)?;
    if component_samples == 0 || component_samples > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "native Part 1 profile decode is guarded to at most 16 Mi component samples",
        ));
    }

    let coding_style = uniform_effective_coding_style(codestream)?;
    if coding_style.entropy_coder != EntropyCoder::ClassicTier1 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::EntropyCoder,
            "native multi-tile DWT2 decode only accepts classic tier-1 coding",
        ));
    }
    if !default_precinct_progression_order_supported(coding_style.progression_order) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::ProgressionOrder,
            "native multi-tile DWT2 decode only accepts LRCP/RLCP default-precinct progression",
        ));
    }
    if coding_style.transform != WaveletTransform::Reversible53 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::WaveletTransform,
            "native multi-tile DWT2 decode only accepts reversible 5/3",
        ));
    }
    if coding_style.decomposition_levels != 2 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::WaveletTransform,
            "native multi-tile DWT2 decode accepts exactly two decomposition levels",
        ));
    }
    if !default_precinct_layer_count_supported(coding_style.layers) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::PacketDecode,
            "native multi-tile DWT2 decode requires at least one quality layer",
        ));
    }
    if coding_style.sop_markers || coding_style.eph_markers || coding_style.precincts_declared {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::MarkerSegment,
            "SOP, EPH, and explicit precinct tables are outside native multi-tile DWT2 decode",
        ));
    }
    if !classic_tier1_code_block_style_supported(coding_style.code_block_style) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Tier1Decode,
            "native multi-tile DWT2 decode accepts only combinations of BYPASS, RESET, TERMALL, VSC, PTERM, and SEGSYM code-block styles",
        ));
    }
    if coding_style.multiple_component_transform != expected_mct {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            if expected_mct {
                "native RGB multi-tile DWT2 decode requires multiple component transform"
            } else {
                "native grayscale multi-tile DWT2 decode does not accept multiple component transform"
            },
        ));
    }
    validate_one_tile_part_per_tile(codestream)?;

    let _ = profile_name;
    Ok(coding_style)
}

fn validate_one_tile_part_per_tile(codestream: &Codestream) -> Result<()> {
    let tile_rects = tile_rects(codestream)?;
    if codestream.tiles.len() != tile_rects.len() {
        return Err(unsupported(
            None,
            Some(Marker::Sot),
            UnsupportedConstruct::MarkerSegment,
            "multi-tile decode requires exactly one tile-part payload per tile",
        ));
    }

    for tile in &codestream.tiles {
        if tile.tile_part_index != 0 {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "multi-tile decode rejects tile-part continuations",
            ));
        }
        if tile.tile_part_count != Some(1) {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "multi-tile decode requires each tile to declare exactly one tile-part",
            ));
        }
        let matching_rects = tile_rects
            .iter()
            .filter(|rect| rect.tile_index == tile.tile_index)
            .count();
        if matching_rects != 1 {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "multi-tile decode found a tile-part outside the expected tile grid",
            ));
        }
        tile.payload_offset.ok_or_else(|| {
            unsupported(
                None,
                Some(Marker::Sod),
                UnsupportedConstruct::MarkerSegment,
                "tile-part payload offset was not retained",
            )
        })?;
        tile.payload_len.ok_or_else(|| {
            unsupported(
                None,
                Some(Marker::Sod),
                UnsupportedConstruct::MarkerSegment,
                "tile-part payload length was not retained",
            )
        })?;
    }

    for rect in tile_rects {
        let matching_parts = codestream
            .tiles
            .iter()
            .filter(|tile| tile.tile_index == rect.tile_index)
            .count();
        if matching_parts != 1 {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "multi-tile grayscale decode rejects missing or duplicate tile-part payloads",
            ));
        }
    }

    Ok(())
}

fn validate_retained_tile_parts_per_tile(codestream: &Codestream) -> Result<()> {
    let tile_rects = tile_rects(codestream)?;
    for tile in &codestream.tiles {
        let matching_rects = tile_rects
            .iter()
            .filter(|rect| rect.tile_index == tile.tile_index)
            .count();
        if matching_rects != 1 {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "multi-tile component decode found a tile-part outside the expected tile grid",
            ));
        }
        tile.payload_offset.ok_or_else(|| {
            unsupported(
                None,
                Some(Marker::Sod),
                UnsupportedConstruct::MarkerSegment,
                "tile-part payload offset was not retained",
            )
        })?;
        tile.payload_len.ok_or_else(|| {
            unsupported(
                None,
                Some(Marker::Sod),
                UnsupportedConstruct::MarkerSegment,
                "tile-part payload length was not retained",
            )
        })?;
    }

    if codestream.tile_part_lengths.as_ref().is_some_and(|table| {
        table.fully_covers_codestream && table.entries.len() > codestream.tiles.len()
    }) {
        // A request-aware TLM parse retains payload metadata only for selected
        // tiles. The complete table and fixed SOT fields were reconciled for
        // every tile part before optional headers were skipped.
        return Ok(());
    }

    for rect in tile_rects {
        validate_retained_tile_parts_for_tile(codestream, rect.tile_index)?;
    }

    Ok(())
}

fn validate_retained_tile_parts_for_tile(codestream: &Codestream, tile_index: u16) -> Result<()> {
    let mut tile_parts = codestream
        .tiles
        .iter()
        .filter(|tile| tile.tile_index == tile_index)
        .collect::<Vec<_>>();
    if tile_parts.is_empty() {
        return Err(unsupported(
            None,
            Some(Marker::Sot),
            UnsupportedConstruct::MarkerSegment,
            "multi-tile component decode requires retained tile-part payloads for every tile",
        ));
    }
    tile_parts.sort_by_key(|tile| tile.tile_part_index);

    for (expected_index, tile_part) in tile_parts.iter().enumerate() {
        if usize::from(tile_part.tile_part_index) != expected_index {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "multi-tile component decode requires dense tile-part indexes per tile",
            ));
        }
        if let Some(declared_count) = tile_part.tile_part_count
            && usize::from(declared_count) != tile_parts.len()
        {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "multi-tile component decode requires declared tile-part counts to match retained payloads",
            ));
        }
    }

    Ok(())
}

fn single_part1_profile_tile<'a>(
    input: &'a [u8],
    codestream: &Codestream,
) -> Result<(TileRect, &'a [u8])> {
    let tile_rect = match tile_rects(codestream)?.as_slice() {
        [tile] => *tile,
        _ => {
            return Err(unsupported(
                None,
                Some(Marker::Siz),
                UnsupportedConstruct::MultipleTiles,
                "profile-scoped native Part 1 decode accepts one tile",
            ));
        }
    };
    let tile = match codestream.tiles.as_slice() {
        [tile] => tile,
        _ => {
            return Err(unsupported(
                None,
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "profile-scoped native Part 1 decode requires one tile-part payload",
            ));
        }
    };
    if tile.tile_index != tile_rect.tile_index {
        return Err(unsupported(
            None,
            Some(Marker::Sot),
            UnsupportedConstruct::MarkerSegment,
            "profile-scoped native Part 1 decode expected the retained tile-part to match the single tile",
        ));
    }
    Ok((tile_rect, tile_payload(input, tile)?))
}

/// Extract borrowed classic tier-1 code-block segments for benchmark-only
/// profiling of the current supported Part 1 profile.
#[doc(hidden)]
pub fn profile_code_block_segments_for_bench(
    input: &[u8],
) -> Result<Vec<ProfileCodeBlockSegment<'_>>> {
    let codestream = parse(input)?;
    if is_supported_part1_multitile_grayscale_profile(&codestream) {
        let coding_style = validate_supported_part1_multitile_grayscale_profile(&codestream)?;
        let mut segments = Vec::new();
        for tile_rect in tile_rects(&codestream)? {
            let tile = codestream
                .tiles
                .iter()
                .find(|tile| tile.tile_index == tile_rect.tile_index)
                .ok_or_else(|| {
                    unsupported(
                        None,
                        Some(Marker::Sot),
                        UnsupportedConstruct::MarkerSegment,
                        "multi-tile code-block extraction requires a retained tile-part for every tile",
                    )
                })?;
            let payload = tile_payload(input, tile)?;
            let contributions =
                parse_default_precinct_lrcp_packets(input, &codestream, tile_rect, payload)?;
            append_profile_code_block_segments(
                &mut segments,
                payload,
                coding_style,
                &contributions,
            )?;
        }
        return Ok(segments);
    }

    let coding_style = validate_supported_part1_reversible53_default_precinct(&codestream)?;
    let (tile_rect, payload) = single_part1_profile_tile(input, &codestream)?;
    let component_count = codestream.siz.component_count();

    if coding_style.decomposition_levels == 0 && component_count == 1 {
        let quantization = parse_component_quantization(input, &codestream, 1)?;
        let available_bitplanes = quantization
            .first()
            .ok_or(CodestreamError::SizeOverflow)?
            .available_bitplanes(0, coding_style.entropy_coder)?;
        let packet = parse_no_decomp_lrcp_packet(payload)?;
        let segment = checked_slice(payload, packet.payload_offset, packet.codeword_len)?;
        let width = u16::try_from(tile_rect.width).map_err(|_| CodestreamError::SizeOverflow)?;
        let height = u16::try_from(tile_rect.height).map_err(|_| CodestreamError::SizeOverflow)?;
        let dimensions = tier1::CodeBlockDimensions::new(width, height).map_err(map_tier1_error)?;
        return Ok(alloc::vec![ProfileCodeBlockSegment {
            segment: Cow::Borrowed(segment),
            coding_segments: alloc::vec![tier1::CodeBlockSegment {
                byte_len: segment.len(),
                coding_passes: packet.coding_passes,
            }],
            spec: tier1::CodeBlockDecodeSpec {
                dimensions,
                available_bitplanes,
                missing_most_significant_bitplanes: packet.missing_most_significant_bitplanes,
                coding_passes: packet.coding_passes,
                style: tier1::CodeBlockStyle::from_bits(coding_style.code_block_style),
                subband: tier1::Subband::LowLow,
            },
            component_index: 0,
            resolution: 0,
            subband: PacketSubbandKind::LowLow,
            code_block_x: 0,
            code_block_y: 0,
            width,
            height,
        }]);
    }

    let contributions =
        parse_default_precinct_lrcp_packets(input, &codestream, tile_rect, payload)?;
    let mut segments = Vec::new();
    append_profile_code_block_segments(&mut segments, payload, coding_style, &contributions)?;
    Ok(segments)
}

/// Extract the exact code-block population retained by a selective Part 1
/// request. This benchmark-only surface keeps segment bytes borrowed from the
/// caller's slice and rejects non-contiguous contributions.
#[doc(hidden)]
pub fn profile_selected_code_block_segments_for_bench<'a>(
    input: &'a [u8],
    request: Part1ComponentDecodeRequest<'_>,
) -> Result<Vec<ProfileCodeBlockSegment<'a>>> {
    let prepared = prepare_part1_component_decode(input, request)?;
    let mut segments = Vec::new();
    for tile in &prepared.tiles {
        for &index in &tile.selected_contribution_indices {
            let contribution = tile
                .contributions
                .get(index)
                .ok_or(CodestreamError::SizeOverflow)?;
            let segment = if contribution.segment_ranges.len() > 1 {
                let mut owned = Vec::with_capacity(contribution.codeword_len);
                for range in &contribution.segment_ranges {
                    let bytes = borrowed_profile_segment(
                        &tile.payload,
                        range.payload_offset,
                        range.codeword_len,
                    )
                    .ok_or_else(|| {
                        unsupported(
                            None,
                            Some(Marker::Sod),
                            UnsupportedConstruct::PacketDecode,
                            "selective tier-1 benchmark range crosses a tile-part span",
                        )
                    })?;
                    owned.extend_from_slice(bytes);
                }
                Cow::Owned(owned)
            } else {
                Cow::Borrowed(
                    borrowed_profile_segment(
                        &tile.payload,
                        contribution.payload_offset,
                        contribution.codeword_len,
                    )
                    .ok_or_else(|| {
                        unsupported(
                            None,
                            Some(Marker::Sod),
                            UnsupportedConstruct::PacketDecode,
                            "selective tier-1 benchmark contribution crosses a tile-part span",
                        )
                    })?,
                )
            };
            let dimensions =
                tier1::CodeBlockDimensions::new(contribution.width, contribution.height)
                    .map_err(map_tier1_error)?;
            segments.push(ProfileCodeBlockSegment {
                segment,
                coding_segments: if contribution.coding_segments.is_empty() {
                    alloc::vec![tier1::CodeBlockSegment {
                        byte_len: contribution.codeword_len,
                        coding_passes: contribution.coding_passes,
                    }]
                } else {
                    contribution.coding_segments.clone()
                },
                spec: tier1::CodeBlockDecodeSpec {
                    dimensions,
                    available_bitplanes: contribution.available_bitplanes,
                    missing_most_significant_bitplanes: contribution
                        .missing_most_significant_bitplanes,
                    coding_passes: contribution.coding_passes,
                    style: tier1::CodeBlockStyle::from_bits(prepared.coding_style.code_block_style),
                    subband: contribution.subband.tier1_subband(),
                },
                component_index: contribution.component_index,
                resolution: contribution.resolution,
                subband: contribution.subband,
                code_block_x: contribution.code_block_x,
                code_block_y: contribution.code_block_y,
                width: contribution.width,
                height: contribution.height,
            });
        }
    }
    Ok(segments)
}

/// Extract an owned selective code-block population from a positioned source.
///
/// This benchmark-only path allocates no output plane and retains only the
/// packet metadata and compressed bytes selected by `request`. Production
/// source-backed preparation uses a requested-output sample guard; this
/// extractor bypasses even that output guard because it never reconstructs
/// samples. All marker, coding-style, component, region, packet, and code-block
/// validation remains identical to production selective preparation.
#[cfg(feature = "std")]
#[doc(hidden)]
pub fn profile_selected_code_block_segments_from_source_for_bench(
    source: &dyn source::CodestreamSource,
    request: Part1ComponentDecodeRequest<'_>,
) -> Result<Vec<ProfileCodeBlockSegment<'static>>> {
    let mut scan = scan_part1_source_headers(source, request.region)?;
    let prepared = prepare_part1_component_decode_from_parsed(
        &scan.marker_bytes,
        scan.codestream,
        scan.work,
        request,
        false,
        |_codestream, tile| {
            let mut spans = scan.payload_spans.remove(&tile.tile_index).ok_or_else(|| {
                unsupported(
                    None,
                    Some(Marker::Sot),
                    UnsupportedConstruct::MarkerSegment,
                    "selected benchmark source tile has no retained payload spans",
                )
            })?;
            let mut logical_offset = 0_usize;
            for span in &mut spans {
                span.logical_offset = logical_offset;
                logical_offset = logical_offset
                    .checked_add(span.len)
                    .ok_or(CodestreamError::SizeOverflow)?;
            }
            Ok(PreparedTilePayload::Source(SourceTilePartPayload {
                source,
                spans,
                len: logical_offset,
            }))
        },
    )?;

    let mut segments = Vec::new();
    let mut segment_scratch = Vec::new();
    for tile in &prepared.tiles {
        for &index in &tile.selected_contribution_indices {
            let contribution = tile
                .contributions
                .get(index)
                .ok_or(CodestreamError::SizeOverflow)?;
            let segment =
                code_block_segment_from_source(&tile.payload, contribution, &mut segment_scratch)?
                    .to_vec();
            let dimensions =
                tier1::CodeBlockDimensions::new(contribution.width, contribution.height)
                    .map_err(map_tier1_error)?;
            segments.push(ProfileCodeBlockSegment {
                segment: Cow::Owned(segment),
                coding_segments: if contribution.coding_segments.is_empty() {
                    alloc::vec![tier1::CodeBlockSegment {
                        byte_len: contribution.codeword_len,
                        coding_passes: contribution.coding_passes,
                    }]
                } else {
                    contribution.coding_segments.clone()
                },
                spec: tier1::CodeBlockDecodeSpec {
                    dimensions,
                    available_bitplanes: contribution.available_bitplanes,
                    missing_most_significant_bitplanes: contribution
                        .missing_most_significant_bitplanes,
                    coding_passes: contribution.coding_passes,
                    style: tier1::CodeBlockStyle::from_bits(prepared.coding_style.code_block_style),
                    subband: contribution.subband.tier1_subband(),
                },
                component_index: contribution.component_index,
                resolution: contribution.resolution,
                subband: contribution.subband,
                code_block_x: contribution.code_block_x,
                code_block_y: contribution.code_block_y,
                width: contribution.width,
                height: contribution.height,
            });
        }
    }
    Ok(segments)
}

fn borrowed_profile_segment<'a>(
    payload: &PreparedTilePayload<'a>,
    offset: usize,
    len: usize,
) -> Option<&'a [u8]> {
    let PreparedTilePayload::Slice(payload) = payload else {
        return None;
    };
    let span = *payload.spans.get(payload.span_index_at(offset)?)?;
    let local_offset = offset.checked_sub(span.logical_offset)?;
    checked_slice(span.bytes, local_offset, len).ok()
}

/// Report whether feature-gated parallel decode paths are eligible for the
/// current raw Part 1 codestream benchmark row.
#[doc(hidden)]
pub fn decode_parallel_plan_for_bench(input: &[u8]) -> Result<Option<DecodeParallelPlan>> {
    let codestream = parse(input)?;
    if codestream.kind != CodestreamKind::J2k {
        return Ok(None);
    }
    let Ok(coding_style) = uniform_effective_coding_style(&codestream) else {
        return Ok(None);
    };
    if coding_style.entropy_coder != EntropyCoder::ClassicTier1
        || coding_style.transform != WaveletTransform::Reversible53
        || !default_precinct_progression_order_supported(coding_style.progression_order)
        || !default_precinct_layer_count_supported(coding_style.layers)
        || !classic_tier1_code_block_style_supported(coding_style.code_block_style)
    {
        return Ok(None);
    }

    let tile_rects = tile_rects(&codestream)?;
    let component_count = usize::from(codestream.siz.component_count());
    let component_count_u64 =
        u64::try_from(component_count).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_component_samples = tile_rects.iter().fold(0_u64, |total, tile_rect| {
        total.saturating_add(
            u64::from(tile_rect.width)
                .saturating_mul(u64::from(tile_rect.height))
                .saturating_mul(component_count_u64),
        )
    });

    let mut code_block_count = 0_usize;
    let mut code_block_coefficients = 0_u64;
    let mut code_block_coded_bytes = 0_u64;
    let mut code_block_coding_passes = 0_u64;
    let mut omitted_code_block_count = 0_usize;
    let mut estimated_tier1_work = 0_u64;
    let mut inverse_reversible_component_eligible_tile_count = 0_usize;
    for tile_rect in &tile_rects {
        if should_parallel_inverse_reversible_components(
            component_count,
            tile_rect.width,
            tile_rect.height,
            coding_style.decomposition_levels,
        ) {
            inverse_reversible_component_eligible_tile_count += 1;
        }

        let payload = tile_payload_for_rect(input, &codestream, *tile_rect)?;
        let contributions =
            parse_default_precinct_lrcp_packets(input, &codestream, *tile_rect, &payload)?;
        code_block_count = code_block_count
            .checked_add(contributions.len())
            .ok_or(CodestreamError::SizeOverflow)?;
        code_block_coefficients =
            code_block_coefficients.saturating_add(code_block_coefficient_count(&contributions));
        code_block_coded_bytes = code_block_coded_bytes.saturating_add(
            contributions
                .iter()
                .map(|contribution| contribution.codeword_len as u64)
                .sum::<u64>(),
        );
        code_block_coding_passes = code_block_coding_passes.saturating_add(
            contributions
                .iter()
                .map(|contribution| u64::from(contribution.coding_passes))
                .sum::<u64>(),
        );
        omitted_code_block_count = omitted_code_block_count.saturating_add(
            contributions
                .iter()
                .filter(|contribution| contribution.coding_passes == 0)
                .count(),
        );
        estimated_tier1_work =
            estimated_tier1_work.saturating_add(code_block_estimated_work(&contributions));
    }

    let tile_decode_eligible = should_parallel_decode_tiles(&tile_rects, component_count);
    let code_block_decode_eligible =
        should_parallel_decode_code_block_work(code_block_count, estimated_tier1_work);
    let selected_entropy_axis =
        select_decode_parallel_axis(tile_decode_eligible, code_block_decode_eligible);

    Ok(Some(DecodeParallelPlan {
        parallel_feature_enabled: cfg!(feature = "parallel"),
        worker_count: parallel_worker_count(),
        tile_count: tile_rects.len(),
        component_count,
        tile_component_samples,
        tile_decode_eligible,
        code_block_count,
        code_block_coefficients,
        code_block_coded_bytes,
        code_block_coding_passes,
        omitted_code_block_count,
        estimated_tier1_work,
        code_block_decode_eligible,
        selected_entropy_axis,
        inverse_reversible_component_tile_count: tile_rects.len(),
        inverse_reversible_component_eligible_tile_count,
    }))
}

fn code_block_coefficient_count(contributions: &[PacketCodeBlockContribution]) -> u64 {
    contributions.iter().fold(0_u64, |total, contribution| {
        total.saturating_add(u64::from(contribution.width) * u64::from(contribution.height))
    })
}

fn select_decode_parallel_axis(
    tile_decode_eligible: bool,
    code_block_decode_eligible: bool,
) -> DecodeParallelAxis {
    if !parallel_decode_dispatch_available() {
        DecodeParallelAxis::Scalar
    } else if tile_decode_eligible {
        DecodeParallelAxis::Tiles
    } else if code_block_decode_eligible {
        DecodeParallelAxis::CodeBlocks
    } else {
        DecodeParallelAxis::Scalar
    }
}

fn append_profile_code_block_segments<'a>(
    segments: &mut Vec<ProfileCodeBlockSegment<'a>>,
    payload: &'a [u8],
    coding_style: CodingStyleMarker,
    contributions: &[PacketCodeBlockContribution],
) -> Result<()> {
    for contribution in contributions {
        if contribution.segment_ranges.len() > 1 {
            return Err(unsupported(
                None,
                Some(Marker::Sod),
                UnsupportedConstruct::PacketDecode,
                "tier-1 borrowed segment benchmarks require one contiguous code-block contribution",
            ));
        }
        let segment = checked_slice(
            payload,
            contribution.payload_offset,
            contribution.codeword_len,
        )?;
        let dimensions = tier1::CodeBlockDimensions::new(contribution.width, contribution.height)
            .map_err(map_tier1_error)?;
        segments.push(ProfileCodeBlockSegment {
            segment: Cow::Borrowed(segment),
            coding_segments: if contribution.coding_segments.is_empty() {
                alloc::vec![tier1::CodeBlockSegment {
                    byte_len: segment.len(),
                    coding_passes: contribution.coding_passes,
                }]
            } else {
                contribution.coding_segments.clone()
            },
            spec: tier1::CodeBlockDecodeSpec {
                dimensions,
                available_bitplanes: contribution.available_bitplanes,
                missing_most_significant_bitplanes: contribution.missing_most_significant_bitplanes,
                coding_passes: contribution.coding_passes,
                style: tier1::CodeBlockStyle::from_bits(coding_style.code_block_style),
                subband: contribution.subband.tier1_subband(),
            },
            component_index: contribution.component_index,
            resolution: contribution.resolution,
            subband: contribution.subband,
            code_block_x: contribution.code_block_x,
            code_block_y: contribution.code_block_y,
            width: contribution.width,
            height: contribution.height,
        });
    }
    Ok(())
}

fn decode_supported_part1_reversible53_default_precinct(
    input: &[u8],
    codestream: &Codestream,
) -> Result<DecodedImage> {
    let coding_style = validate_supported_part1_reversible53_default_precinct(codestream)?;
    decode_supported_part1_reversible53_default_precinct_validated(
        input,
        codestream,
        coding_style,
        None,
    )
}

#[cfg_attr(not(feature = "std"), allow(unused_mut, unused_variables))]
fn decode_supported_part1_reversible53_default_precinct_validated(
    input: &[u8],
    codestream: &Codestream,
    coding_style: CodingStyleMarker,
    mut timings: Option<&mut DecodeStageTimings>,
) -> Result<DecodedImage> {
    let component_count = usize::from(codestream.siz.component_count());

    #[cfg(feature = "std")]
    let stage_started = std::time::Instant::now();
    let (tile_rect, payload) = single_part1_profile_tile(input, codestream)?;
    #[cfg(feature = "std")]
    record_stage(
        &mut timings,
        DecodeStage::TilePayload,
        stage_started.elapsed(),
    );
    let mut planes = decode_default_precinct_tile_component_planes(
        input,
        codestream,
        coding_style,
        tile_rect,
        payload,
        component_count,
        &mut timings,
    )?;

    let rgb_u8_components =
        component_count == 3 && codestream_components_are_unsigned_u8(codestream, 3);
    if rgb_u8_components && timings.is_none() {
        let first_component = codestream
            .siz
            .components
            .first()
            .ok_or(CodestreamError::SizeOverflow)?;
        return Ok(DecodedImage {
            width: tile_rect.width,
            height: tile_rect.height,
            bits_per_sample: first_component.bits_per_sample,
            signed: first_component.signed,
            components: rgb_u8_inverse_rct_planes_to_components(planes)?,
        });
    }

    if component_count == 3 {
        #[cfg(feature = "std")]
        let stage_started = std::time::Instant::now();
        let (y_plane, rest) = planes.split_at_mut(1);
        let (db_plane, dr_plane) = rest.split_at_mut(1);
        transform::inverse_reversible_color_transform_bounded(
            &mut y_plane[0],
            &mut db_plane[0],
            &mut dr_plane[0],
        )
        .map_err(|_| {
            unsupported(
                None,
                None,
                UnsupportedConstruct::Transform,
                "inverse reversible color transform failed for profile-scoped native Part 1 decode",
            )
        })?;
        #[cfg(feature = "std")]
        record_stage(
            &mut timings,
            DecodeStage::InverseRct,
            stage_started.elapsed(),
        );
    }

    #[cfg(feature = "std")]
    let stage_started = std::time::Instant::now();
    let components = if rgb_u8_components {
        rgb_u8_component_planes_to_components(planes)?
    } else {
        planes
            .into_iter()
            .enumerate()
            .map(|(component_index, plane)| {
                let component = codestream
                    .siz
                    .components
                    .get(component_index)
                    .ok_or(CodestreamError::SizeOverflow)?;
                component_samples_to_bytes(component.bits_per_sample, component.signed, plane)
                    .map(|samples| DecodedComponent { samples })
            })
            .collect::<Result<Vec<_>>>()?
    };
    #[cfg(feature = "std")]
    record_stage(
        &mut timings,
        DecodeStage::SampleConversion,
        stage_started.elapsed(),
    );

    let first_component = codestream
        .siz
        .components
        .first()
        .ok_or(CodestreamError::SizeOverflow)?;
    Ok(DecodedImage {
        width: tile_rect.width,
        height: tile_rect.height,
        bits_per_sample: first_component.bits_per_sample,
        signed: first_component.signed,
        components,
    })
}

fn decode_supported_part1_irreversible97_default_precinct(
    input: &[u8],
    codestream: &Codestream,
) -> Result<DecodedImage> {
    let coding_style = validate_supported_part1_irreversible97_default_precinct(input, codestream)?;
    let (tile_rect, payload) = single_part1_profile_tile(input, codestream)?;
    let contributions = parse_default_precinct_lrcp_packets(input, codestream, tile_rect, payload)?;
    let mut planes = reconstruct_irreversible_component_planes(
        payload,
        codestream,
        coding_style,
        tile_rect,
        &contributions,
    )?;

    if coding_style.multiple_component_transform {
        if planes.len() != 3 {
            return Err(CodestreamError::SizeOverflow);
        }
        let (y, rest) = planes.split_at_mut(1);
        let (cb, cr) = rest.split_at_mut(1);
        transform::inverse_irreversible_color_transform(&mut y[0], &mut cb[0], &mut cr[0])
            .map_err(|_| {
                unsupported(
                    None,
                    None,
                    UnsupportedConstruct::Transform,
                    "inverse irreversible component transform failed",
                )
            })?;
    }

    let components = planes
        .into_iter()
        .zip(&codestream.siz.components)
        .map(|(plane, component)| {
            irreversible_component_samples_to_bytes(component, &plane)
                .map(|samples| DecodedComponent { samples })
        })
        .collect::<Result<Vec<_>>>()?;
    let first = codestream
        .siz
        .components
        .first()
        .ok_or(CodestreamError::SizeOverflow)?;
    Ok(DecodedImage {
        width: tile_rect.width,
        height: tile_rect.height,
        bits_per_sample: first.bits_per_sample,
        signed: first.signed,
        components,
    })
}

/// Decode the repo-owned profile-scoped native Part 1 baseline subset.
pub fn decode_baseline_owned(input: &[u8]) -> Result<DecodedImage> {
    decode_baseline_owned_components(input)
}

/// Decode the repo-owned profile-scoped native Part 1 subset as
/// rendered/display components.
pub fn decode_baseline_owned_rendered(input: &[u8]) -> Result<DecodedImage> {
    let codestream = parse(input)?;
    decode_supported_part1_reversible53_default_precinct(input, &codestream).or_else(|error| {
        if uniform_effective_coding_style(&codestream)
            .is_ok_and(|coding_style| coding_style.transform == WaveletTransform::Irreversible97)
        {
            decode_supported_part1_irreversible97_default_precinct(input, &codestream)
        } else if is_supported_grayscale_u8_two_decomposition_multitile_encode_compatible_profile(
            &codestream,
        ) {
            decode_native_grayscale_u8_two_decomp_multitile(input, &codestream)
        } else if is_supported_rgb_u8_two_decomposition_multitile_encode_compatible_profile(
            &codestream,
        ) {
            decode_native_rgb_u8_two_decomp_multitile(input, &codestream)
        } else if uniform_effective_coding_style(&codestream)
            .is_ok_and(|coding_style| coding_style.precincts_declared)
            && matches!(codestream.siz.component_count(), 1 | 3)
            && codestream
                .siz
                .components
                .iter()
                .all(|component| component.bits_per_sample == 8 && !component.signed)
            && is_supported_native_component_multitile_profile(&codestream)
        {
            decode_native_component_multitile(input, &codestream)
        } else if is_supported_part1_multitile_grayscale_profile(&codestream) {
            decode_profiled_multitile_grayscale(input, &codestream)
        } else if is_supported_part1_high_bit_depth_component_profile(&codestream) {
            decode_profiled_high_bit_depth_component(input, &codestream)
        } else {
            Err(error)
        }
    })
}

/// Decode the repo-owned profile-scoped native Part 1 subset as component
/// planes. Three-component profile rows apply inverse RCT and return RGB
/// component planes because that is the currently supported rendered profile.
pub fn decode_baseline_owned_components(input: &[u8]) -> Result<DecodedImage> {
    let codestream = parse(input)?;
    if is_supported_part1_native_subsampled_component_profile(&codestream) {
        return decode_native_subsampled_components(input, &codestream);
    }
    decode_supported_part1_reversible53_default_precinct(input, &codestream).or_else(|error| {
        if uniform_effective_coding_style(&codestream)
            .is_ok_and(|coding_style| coding_style.transform == WaveletTransform::Irreversible97)
        {
            decode_supported_part1_irreversible97_default_precinct(input, &codestream)
        } else if is_supported_part1_multitile_grayscale_profile(&codestream) {
            decode_profiled_multitile_grayscale(input, &codestream)
        } else if is_supported_grayscale_u8_two_decomposition_multitile_encode_compatible_profile(
            &codestream,
        ) {
            decode_native_grayscale_u8_two_decomp_multitile(input, &codestream)
        } else if is_supported_rgb_u8_two_decomposition_multitile_encode_compatible_profile(
            &codestream,
        ) {
            decode_native_rgb_u8_two_decomp_multitile(input, &codestream)
        } else if is_supported_grayscale_u16_two_decomposition_multitile_encode_compatible_profile(
            &codestream,
        ) {
            decode_native_grayscale_u16_two_decomp_multitile(input, &codestream)
        } else if is_supported_rgb_u16_two_decomposition_multitile_encode_compatible_profile(
            &codestream,
        ) {
            decode_native_rgb_u16_two_decomp_multitile(input, &codestream)
        } else if is_supported_native_component_multitile_profile(&codestream) {
            decode_native_component_multitile(input, &codestream)
        } else if is_supported_part1_high_bit_depth_component_profile(&codestream) {
            decode_profiled_high_bit_depth_component(input, &codestream)
        } else {
            Err(error)
        }
    })
}

/// Decode only the requested source component planes from the repo-owned
/// profile-scoped native Part 1 subset.
///
/// Component indices must be unique, in range, and are returned in caller
/// order. Packet headers for non-selected components are still parsed so the
/// packet-body offsets remain standards-correct, but their code-block bodies
/// are not entropy-decoded and no coefficient or output plane is allocated for
/// them. A codestream using the multiple-component transform currently
/// requires the identity selection because its transformed inputs are coupled.
pub fn decode_baseline_owned_components_selected(
    input: &[u8],
    component_indices: &[u16],
) -> Result<DecodedImage> {
    decode_baseline_owned_components_selected_with_max_layers(input, component_indices, None)
}

/// Owned selective component decode with an optional inclusive count of
/// leading quality layers to reconstruct.
pub fn decode_baseline_owned_components_selected_with_max_layers(
    input: &[u8],
    component_indices: &[u16],
    max_layers: Option<u16>,
) -> Result<DecodedImage> {
    let codestream = parse(input)?;
    validate_component_selection(&codestream, component_indices)?;
    let component_count = usize::from(codestream.siz.component_count());
    let identity = component_indices.len() == component_count
        && component_indices
            .iter()
            .enumerate()
            .all(|(position, component)| usize::from(*component) == position);
    if identity
        && max_layers.is_none()
        && !is_supported_part1_native_subsampled_component_profile(&codestream)
    {
        return decode_baseline_owned_components(input);
    }

    let coding_style = validate_supported_selective_native_component_profile(input, &codestream)?;
    if coding_style.multiple_component_transform {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "selective component decode requires an identity component selection when multiple component transform is enabled",
        ));
    }
    let mut workspace = Part1ComponentDecodeWorkspace::new();
    decode_multitile_components_selected_validated(
        input,
        &codestream,
        coding_style,
        component_indices,
        None,
        &mut workspace,
        max_layers,
    )
}

/// Decode selected transformed component planes from the bounded
/// reduced-resolution reversible-MCT profile qualified by Profile-0 P0.14.
///
/// Component-mode output remains before inverse RCT, matching the Part 4
/// component oracle; rendered reduced-MCT output remains a separate feature.
pub fn decode_part1_reduced_reversible_mct_components_selected(
    input: &[u8],
    component_indices: &[u16],
    discard_levels: u8,
) -> Result<DecodedImage> {
    let codestream = parse(input)?;
    validate_component_selection(&codestream, component_indices)?;
    if component_indices != [0] {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentCount,
            "the qualified reduced reversible-MCT component path selects component zero only",
        ));
    }
    let coding_style = validate_part1_reduced_reversible_mct_component_profile(
        input,
        &codestream,
        discard_levels,
    )?;
    let tile_rect = *tile_rects(&codestream)?
        .first()
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut workspace = Part1ComponentDecodeWorkspace::new();
    let mut timings = None;
    let components = decode_multitile_tile_component_samples_selected(
        input,
        &codestream,
        coding_style,
        tile_rect,
        component_indices,
        &mut timings,
        &mut workspace,
        None,
        discard_levels,
        PacketOrganisationConfig::DEFAULT,
    )?
    .into_iter()
    .map(|samples| DecodedComponent { samples })
    .collect::<Vec<_>>();
    let retained_resolution = coding_style
        .decomposition_levels
        .checked_sub(discard_levels)
        .ok_or(CodestreamError::SizeOverflow)?;
    let (width, height) = resolution_dimensions(
        tile_rect.width,
        tile_rect.height,
        coding_style.decomposition_levels,
        retained_resolution,
    )?;
    Ok(DecodedImage {
        width,
        height,
        bits_per_sample: 8,
        signed: false,
        components,
    })
}

