fn reduced_part1_region(
    siz: &SizMarker,
    region: TileRegionRequest,
    discard_levels: u8,
) -> Result<TileRegionRequest> {
    let reduced = siz
        .absolute_reference_region(region)?
        .to_component_grid(1, 1)?
        .reduce(discard_levels)?;
    Ok(TileRegionRequest {
        x: reduced.x0(),
        y: reduced.y0(),
        width: reduced.width(),
        height: reduced.height(),
    })
}

#[cfg(feature = "std")]
/// Decode selected component planes and collect stage timings plus selective
/// work-avoidance counters.
pub fn decode_baseline_owned_components_selected_profiled_with_work_counters(
    input: &[u8],
    component_indices: &[u16],
    collect_tier1_work_counters: bool,
) -> Result<(DecodedImage, DecodeStageTimings)> {
    let total_started = std::time::Instant::now();
    let stage_started = std::time::Instant::now();
    let codestream = parse(input)?;
    let mut timings = DecodeStageTimings {
        collect_tier1_work_counters,
        marker_parse_ns: stage_started.elapsed().as_nanos(),
        ..DecodeStageTimings::default()
    };
    validate_component_selection(&codestream, component_indices)?;
    let stage_started = std::time::Instant::now();
    let coding_style = validate_supported_selective_native_component_profile(input, &codestream)?;
    if coding_style.multiple_component_transform {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "profiled selective component decode does not split multiple-component-transform inputs",
        ));
    }
    timings.support_classification_ns = stage_started.elapsed().as_nanos();
    let mut workspace = Part1ComponentDecodeWorkspace::new();
    let image = decode_multitile_components_selected_validated(
        input,
        &codestream,
        coding_style,
        component_indices,
        Some(&mut timings),
        &mut workspace,
        None,
    )?;
    timings.total_ns = total_started.elapsed().as_nanos();
    Ok((image, timings))
}

fn validate_component_selection(codestream: &Codestream, component_indices: &[u16]) -> Result<()> {
    if component_indices.is_empty() {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "component selection must not be empty",
        ));
    }
    let component_count = codestream.siz.component_count();
    let mut seen = alloc::vec![false; usize::from(component_count)];
    for &component_index in component_indices {
        if component_index >= component_count {
            return Err(invalid(
                None,
                Some(Marker::Siz),
                "component selection index is outside the codestream component range",
            ));
        }
        let seen = seen
            .get_mut(usize::from(component_index))
            .ok_or(CodestreamError::SizeOverflow)?;
        if *seen {
            return Err(invalid(
                None,
                Some(Marker::Siz),
                "component selection must not contain duplicate indices",
            ));
        }
        *seen = true;
    }
    Ok(())
}

