#[derive(Debug, Clone, PartialEq, Eq)]
struct PendingPacketContribution {
    component_index: u16,
    subband_index: u8,
    subband: PacketSubbandKind,
    resolution: u8,
    code_block_x: u16,
    code_block_y: u16,
    x: u32,
    y: u32,
    width: u16,
    height: u16,
    available_bitplanes: u8,
    irreversible_quantization_step: Option<transform::IrreversibleQuantizationStep>,
    missing_most_significant_bitplanes: u8,
    coding_passes: u16,
    codeword_len: usize,
    coding_segments: Vec<tier1::CodeBlockSegment>,
    ht_coding_set: Option<HtCodeBlockCodingSet>,
    ht_coded: bool,
    first_segment_continues: bool,
}

fn read_classic_codeword_lengths(
    reader: &mut PacketBitReader<'_>,
    l_block: u8,
    first_coding_pass: u16,
    coding_passes: u16,
    code_block_style: u8,
) -> Result<(usize, Vec<tier1::CodeBlockSegment>, bool)> {
    let terminates_each_pass = code_block_style & tier1::CodeBlockStyle::TERMINATE_EACH_PASS != 0;
    let selective_bypass =
        code_block_style & tier1::CodeBlockStyle::SELECTIVE_ARITHMETIC_BYPASS != 0;
    if !terminates_each_pass && !selective_bypass {
        let length_bits = l_block
            .checked_add(
                u8::try_from(u32::from(coding_passes).ilog2())
                    .map_err(|_| CodestreamError::SizeOverflow)?,
            )
            .ok_or(CodestreamError::SizeOverflow)?;
        let codeword_len = usize::try_from(reader.read_bits_with_stuffing(length_bits)?)
            .map_err(|_| CodestreamError::SizeOverflow)?;
        return Ok((codeword_len, Vec::new(), false));
    }

    let mut lengths = Vec::new();
    let mut codeword_len = 0usize;
    let mut pass = first_coding_pass;
    let pass_end = first_coding_pass
        .checked_add(coding_passes)
        .ok_or(CodestreamError::SizeOverflow)?;
    while pass < pass_end {
        let passes_in_length = if terminates_each_pass {
            1
        } else {
            bypass_segment_pass_capacity(pass).min(pass_end - pass)
        };
        let length_bits = l_block
            .checked_add(
                u8::try_from(u32::from(passes_in_length).ilog2())
                    .map_err(|_| CodestreamError::SizeOverflow)?,
            )
            .ok_or(CodestreamError::SizeOverflow)?;
        let length = usize::try_from(reader.read_bits_with_stuffing(length_bits)?)
            .map_err(|_| CodestreamError::SizeOverflow)?;
        codeword_len = codeword_len
            .checked_add(length)
            .ok_or(CodestreamError::SizeOverflow)?;
        lengths.push(tier1::CodeBlockSegment {
            byte_len: length,
            coding_passes: passes_in_length,
        });
        pass = pass
            .checked_add(passes_in_length)
            .ok_or(CodestreamError::SizeOverflow)?;
    }
    let first_segment_continues = !terminates_each_pass
        && selective_bypass
        && bypass_pass_continues_segment(first_coding_pass);
    Ok((codeword_len, lengths, first_segment_continues))
}

fn read_ht_codeword_lengths(
    reader: &mut PacketBitReader<'_>,
    l_block: u8,
    announced_coding_passes: u16,
) -> Result<(usize, Vec<tier1::CodeBlockSegment>, u16, u8)> {
    let placeholder_sets = u8::try_from((announced_coding_passes - 1) / 3)
        .map_err(|_| CodestreamError::SizeOverflow)?;
    let placeholder_passes = u16::from(placeholder_sets) * 3;
    let coding_passes = announced_coding_passes - placeholder_passes;
    debug_assert!((1..=3).contains(&coding_passes));

    let cleanup_length_bits = l_block
        .checked_add(
            u8::try_from((u32::from(placeholder_passes) + 1).ilog2())
                .map_err(|_| CodestreamError::SizeOverflow)?,
        )
        .ok_or(CodestreamError::SizeOverflow)?;
    let cleanup_len = usize::try_from(reader.read_bits_with_stuffing(cleanup_length_bits)?)
        .map_err(|_| CodestreamError::SizeOverflow)?;
    if !(2..65_535).contains(&cleanup_len) {
        return Err(invalid(
            None,
            Some(Marker::Sod),
            "HT cleanup pass segment length must be between 2 and 65534 bytes",
        ));
    }

    let mut segments = alloc::vec![tier1::CodeBlockSegment {
        byte_len: cleanup_len,
        coding_passes: 1,
    }];
    let mut codeword_len = cleanup_len;
    if coding_passes > 1 {
        let refinement_length_bits = l_block
            .checked_add(u8::from(coding_passes > 2))
            .ok_or(CodestreamError::SizeOverflow)?;
        let refinement_len =
            usize::try_from(reader.read_bits_with_stuffing(refinement_length_bits)?)
                .map_err(|_| CodestreamError::SizeOverflow)?;
        if refinement_len == 0 || refinement_len >= 2047 {
            return Err(invalid(
                None,
                Some(Marker::Sod),
                "HT refinement pass segment length must be between 1 and 2046 bytes",
            ));
        }
        codeword_len = codeword_len
            .checked_add(refinement_len)
            .ok_or(CodestreamError::SizeOverflow)?;
        segments.push(tier1::CodeBlockSegment {
            byte_len: refinement_len,
            coding_passes: coding_passes - 1,
        });
    }

    Ok((codeword_len, segments, coding_passes, placeholder_sets))
}

fn read_layered_ht_codeword_lengths(
    reader: &mut PacketBitReader<'_>,
    l_block: u8,
    first_coding_pass: u16,
    announced_coding_passes: u16,
) -> Result<(
    usize,
    Vec<tier1::CodeBlockSegment>,
    u16,
    Option<(u8, usize)>,
)> {
    let pass_end = first_coding_pass
        .checked_add(announced_coding_passes)
        .ok_or(CodestreamError::SizeOverflow)?;
    let final_set_start = (pass_end - 1) / 3 * 3;
    let actual_start = first_coding_pass.max(final_set_start);
    let placeholder_passes = actual_start - first_coding_pass;
    let coding_passes = pass_end - actual_start;
    if actual_start % 3 != 0 {
        let set_end = (first_coding_pass / 3 + 1) * 3;
        if pass_end > set_end {
            return Err(CodestreamError::SizeOverflow);
        }
        let refinement_length_bits = l_block
            .checked_add(u8::from(announced_coding_passes > 1))
            .ok_or(CodestreamError::SizeOverflow)?;
        let refinement_len =
            usize::try_from(reader.read_bits_with_stuffing(refinement_length_bits)?)
                .map_err(|_| CodestreamError::SizeOverflow)?;
        if refinement_len == 0 {
            return Ok((0, Vec::new(), 0, None));
        }
        return Ok((
            refinement_len,
            alloc::vec![tier1::CodeBlockSegment {
                byte_len: refinement_len,
                coding_passes: announced_coding_passes,
            }],
            announced_coding_passes,
            Some((
                u8::try_from(first_coding_pass / 3).map_err(|_| CodestreamError::SizeOverflow)?,
                0,
            )),
        ));
    }

    let cleanup_length_bits = l_block
        .checked_add(
            u8::try_from((u32::from(placeholder_passes) + 1).ilog2())
                .map_err(|_| CodestreamError::SizeOverflow)?,
        )
        .ok_or(CodestreamError::SizeOverflow)?;
    let cleanup_len = usize::try_from(reader.read_bits_with_stuffing(cleanup_length_bits)?)
        .map_err(|_| CodestreamError::SizeOverflow)?;
    if cleanup_len == 0 {
        return Ok((0, Vec::new(), 0, None));
    }
    if !(2..65_535).contains(&cleanup_len) {
        return Err(invalid(
            None,
            Some(Marker::Sod),
            "HT cleanup pass segment length must be between 2 and 65534 bytes",
        ));
    }
    let refinement_len = if coding_passes > 1 {
        let refinement_length_bits = l_block
            .checked_add(u8::from(coding_passes > 2))
            .ok_or(CodestreamError::SizeOverflow)?;
        let refinement_len =
            usize::try_from(reader.read_bits_with_stuffing(refinement_length_bits)?)
                .map_err(|_| CodestreamError::SizeOverflow)?;
        if refinement_len >= 2047 {
            return Err(invalid(
                None,
                Some(Marker::Sod),
                "HT refinement pass segment length must be less than 2047 bytes",
            ));
        }
        refinement_len
    } else {
        0
    };

    let mut segments = alloc::vec![tier1::CodeBlockSegment {
        byte_len: cleanup_len,
        coding_passes: 1,
    }];
    let mut codeword_len = cleanup_len;
    let coding_passes = if refinement_len == 0 {
        1
    } else {
        codeword_len = codeword_len
            .checked_add(refinement_len)
            .ok_or(CodestreamError::SizeOverflow)?;
        segments.push(tier1::CodeBlockSegment {
            byte_len: refinement_len,
            coding_passes: coding_passes - 1,
        });
        coding_passes
    };

    Ok((
        codeword_len,
        segments,
        coding_passes,
        Some((
            u8::try_from(actual_start / 3).map_err(|_| CodestreamError::SizeOverflow)?,
            cleanup_len,
        )),
    ))
}

fn bypass_segment_pass_capacity(coding_pass: u16) -> u16 {
    if coding_pass < 10 {
        return 10 - coding_pass;
    }
    match (coding_pass - 10) % 3 {
        0 => 2,
        1 | 2 => 1,
        _ => unreachable!(),
    }
}

fn bypass_pass_continues_segment(coding_pass: u16) -> bool {
    (1..10).contains(&coding_pass) || (coding_pass >= 10 && (coding_pass - 10) % 3 == 1)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct PacketCodeBlockKey {
    component_index: u16,
    subband_index: u8,
    code_block_x: u16,
    code_block_y: u16,
}

fn append_default_precinct_contribution(
    contributions: &mut Vec<PacketCodeBlockContribution>,
    contribution_indices: &mut BTreeMap<PacketCodeBlockKey, usize>,
    mut pending: PendingPacketContribution,
    segment_offset: usize,
) -> Result<()> {
    let key = PacketCodeBlockKey {
        component_index: pending.component_index,
        subband_index: pending.subband_index,
        code_block_x: pending.code_block_x,
        code_block_y: pending.code_block_y,
    };
    let segment_range = PacketCodeBlockSegmentRange {
        payload_offset: segment_offset,
        codeword_len: pending.codeword_len,
    };

    if let Some(&index) = contribution_indices.get(&key) {
        let contribution = contributions
            .get_mut(index)
            .ok_or(CodestreamError::SizeOverflow)?;
        if contribution.segment_ranges.is_empty() {
            contribution
                .segment_ranges
                .push(PacketCodeBlockSegmentRange {
                    payload_offset: contribution.payload_offset,
                    codeword_len: contribution.codeword_len,
                });
        }
        if let Some(mut coding_set) = pending.ht_coding_set.take() {
            if coding_set.cleanup_byte_len == 0 {
                if contribution.expanded_ht_coding_sets.is_none() {
                    if !contribution.ht_coded
                        || contribution.missing_most_significant_bitplanes
                            != coding_set.missing_most_significant_bitplanes
                        || contribution
                            .coding_passes
                            .checked_add(coding_set.coding_passes)
                            .ok_or(CodestreamError::SizeOverflow)?
                            > 3
                    {
                        return Err(invalid(
                            None,
                            Some(Marker::Sod),
                            "HT refinement continuation does not match the preceding cleanup set",
                        ));
                    }
                } else {
                    let previous = contribution
                        .expanded_ht_coding_sets
                        .as_deref_mut()
                        .and_then(<[HtCodeBlockCodingSet]>::last_mut)
                        .ok_or(CodestreamError::SizeOverflow)?;
                    if previous.missing_most_significant_bitplanes
                        != coding_set.missing_most_significant_bitplanes
                        || previous
                            .byte_offset
                            .checked_add(previous.byte_len)
                            .ok_or(CodestreamError::SizeOverflow)?
                            != contribution.codeword_len
                    {
                        return Err(invalid(
                            None,
                            Some(Marker::Sod),
                            "HT refinement continuation does not match the preceding cleanup set",
                        ));
                    }
                    previous.byte_len = previous
                        .byte_len
                        .checked_add(coding_set.byte_len)
                        .ok_or(CodestreamError::SizeOverflow)?;
                    previous.coding_passes = previous
                        .coding_passes
                        .checked_add(coding_set.coding_passes)
                        .ok_or(CodestreamError::SizeOverflow)?;
                    if previous.coding_passes > 3 {
                        return Err(invalid(
                            None,
                            Some(Marker::Sod),
                            "HT coding set contains more than three coding passes",
                        ));
                    }
                }
            } else {
                if !contribution.ht_coded {
                    return Err(invalid(
                        None,
                        Some(Marker::Sod),
                        "HT coding set cannot extend a classic Tier-1 contribution",
                    ));
                }
                coding_set.byte_offset = contribution.codeword_len;
                if contribution.expanded_ht_coding_sets.is_none() {
                    let first = contribution
                        .inline_ht_coding_set()
                        .ok_or(CodestreamError::SizeOverflow)?;
                    contribution.expanded_ht_coding_sets =
                        Some(alloc::vec![first, coding_set].into_boxed_slice());
                } else {
                    let mut coding_sets = Vec::from(
                        contribution
                            .expanded_ht_coding_sets
                            .take()
                            .ok_or(CodestreamError::SizeOverflow)?,
                    );
                    coding_sets.push(coding_set);
                    contribution.expanded_ht_coding_sets = Some(coding_sets.into_boxed_slice());
                }
            }
        }
        contribution.coding_passes = contribution
            .coding_passes
            .checked_add(pending.coding_passes)
            .ok_or(CodestreamError::SizeOverflow)?;
        contribution.codeword_len = contribution
            .codeword_len
            .checked_add(pending.codeword_len)
            .ok_or(CodestreamError::SizeOverflow)?;
        contribution.segment_ranges.push(segment_range);
        if pending.first_segment_continues {
            if pending.coding_segments.is_empty() {
                return Err(invalid(
                    None,
                    Some(Marker::Sod),
                    "continued BYPASS contribution has no coding segment",
                ));
            }
            let continued = pending.coding_segments.remove(0);
            let previous = contribution.coding_segments.last_mut().ok_or_else(|| {
                invalid(
                    None,
                    Some(Marker::Sod),
                    "continued BYPASS contribution has no preceding coding segment",
                )
            })?;
            previous.byte_len = previous
                .byte_len
                .checked_add(continued.byte_len)
                .ok_or(CodestreamError::SizeOverflow)?;
            previous.coding_passes = previous
                .coding_passes
                .checked_add(continued.coding_passes)
                .ok_or(CodestreamError::SizeOverflow)?;
        }
        contribution.coding_segments.extend(pending.coding_segments);
        return Ok(());
    }

    let contribution_index = contributions.len();
    push_default_precinct_contribution(contributions, pending, segment_offset)?;
    contribution_indices.insert(key, contribution_index);
    Ok(())
}

fn push_default_precinct_contribution(
    contributions: &mut Vec<PacketCodeBlockContribution>,
    pending: PendingPacketContribution,
    segment_offset: usize,
) -> Result<()> {
    if pending.first_segment_continues {
        return Err(invalid(
            None,
            Some(Marker::Sod),
            "first BYPASS contribution cannot continue a coding segment",
        ));
    }
    if pending
        .ht_coding_set
        .is_some_and(|coding_set| coding_set.cleanup_byte_len == 0)
    {
        return Err(invalid(
            None,
            Some(Marker::Sod),
            "first HT contribution cannot continue a refinement segment",
        ));
    }

    let ht_coded = pending.ht_coded;
    contributions.push(PacketCodeBlockContribution {
        component_index: pending.component_index,
        resolution: pending.resolution,
        subband: pending.subband,
        subband_index: pending.subband_index,
        code_block_x: pending.code_block_x,
        code_block_y: pending.code_block_y,
        x: pending.x,
        y: pending.y,
        width: pending.width,
        height: pending.height,
        available_bitplanes: pending.available_bitplanes,
        irreversible_quantization_step: pending.irreversible_quantization_step,
        missing_most_significant_bitplanes: pending.missing_most_significant_bitplanes,
        coding_passes: pending.coding_passes,
        codeword_len: pending.codeword_len,
        payload_offset: segment_offset,
        segment_ranges: Vec::new(),
        coding_segments: pending.coding_segments,
        ht_coded,
        expanded_ht_coding_sets: None,
    });
    Ok(())
}

#[derive(Debug)]
struct PacketIdentityLedger {
    layers: u16,
    resolution_offsets: Vec<Vec<usize>>,
    precinct_counts: Vec<Vec<u32>>,
    seen: Vec<bool>,
    seen_count: usize,
}

impl PacketIdentityLedger {
    fn new(layers: u16, topologies: &[Part1PrecinctTopology]) -> Result<Self> {
        if layers == 0 || topologies.is_empty() {
            return Err(CodestreamError::SizeOverflow);
        }
        let mut resolution_offsets = Vec::new();
        resolution_offsets
            .try_reserve_exact(topologies.len())
            .map_err(|_| CodestreamError::SizeOverflow)?;
        let mut precinct_counts = Vec::new();
        precinct_counts
            .try_reserve_exact(topologies.len())
            .map_err(|_| CodestreamError::SizeOverflow)?;
        let mut packet_count = 0_usize;
        for topology in topologies {
            let mut offsets = Vec::new();
            let mut counts = Vec::new();
            offsets
                .try_reserve_exact(topology.resolutions.len())
                .map_err(|_| CodestreamError::SizeOverflow)?;
            counts
                .try_reserve_exact(topology.resolutions.len())
                .map_err(|_| CodestreamError::SizeOverflow)?;
            for resolution in &topology.resolutions {
                offsets.push(packet_count);
                counts.push(resolution.precinct_count);
                packet_count = packet_count
                    .checked_add(
                        usize::try_from(resolution.precinct_count)
                            .map_err(|_| CodestreamError::SizeOverflow)?
                            .checked_mul(usize::from(layers))
                            .ok_or(CodestreamError::SizeOverflow)?,
                    )
                    .ok_or(CodestreamError::SizeOverflow)?;
                if packet_count > MAX_PACKETS_PER_TILE {
                    return Err(unsupported(
                        None,
                        Some(Marker::Cod),
                        UnsupportedConstruct::PacketDecode,
                        "packet identity ledger exceeds the bounded tile packet count",
                    ));
                }
            }
            resolution_offsets.push(offsets);
            precinct_counts.push(counts);
        }
        let mut seen = Vec::new();
        seen.try_reserve_exact(packet_count)
            .map_err(|_| CodestreamError::SizeOverflow)?;
        seen.resize(packet_count, false);
        Ok(Self {
            layers,
            resolution_offsets,
            precinct_counts,
            seen,
            seen_count: 0,
        })
    }

    fn packet_index(&self, packet: PacketKey) -> Result<usize> {
        if packet.layer >= self.layers {
            return Err(CodestreamError::SizeOverflow);
        }
        let precinct_count = *self
            .precinct_counts
            .get(usize::from(packet.component))
            .and_then(|counts| counts.get(usize::from(packet.resolution)))
            .ok_or(CodestreamError::SizeOverflow)?;
        if packet.precinct >= precinct_count {
            return Err(CodestreamError::SizeOverflow);
        }
        let base = *self
            .resolution_offsets
            .get(usize::from(packet.component))
            .and_then(|offsets| offsets.get(usize::from(packet.resolution)))
            .ok_or(CodestreamError::SizeOverflow)?;
        base.checked_add(
            usize::try_from(packet.precinct)
                .map_err(|_| CodestreamError::SizeOverflow)?
                .checked_mul(usize::from(self.layers))
                .and_then(|offset| offset.checked_add(usize::from(packet.layer)))
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .filter(|index| *index < self.seen.len())
        .ok_or(CodestreamError::SizeOverflow)
    }

    fn mark_if_new(&mut self, packet: PacketKey) -> Result<bool> {
        let index = self.packet_index(packet)?;
        let visited = self
            .seen
            .get_mut(index)
            .ok_or(CodestreamError::SizeOverflow)?;
        if *visited {
            return Ok(false);
        }
        *visited = true;
        self.seen_count = self
            .seen_count
            .checked_add(1)
            .ok_or(CodestreamError::SizeOverflow)?;
        Ok(true)
    }

    fn is_complete(&self) -> bool {
        self.seen_count == self.seen.len()
    }

    fn expected_packet_count(&self) -> usize {
        self.seen.len()
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SpatialPrecinct {
    x: u64,
    y: u64,
    component: u16,
    resolution: u8,
    precinct: u32,
}

fn effective_progression_volumes(
    input: &[u8],
    codestream: &Codestream,
    tile: u16,
    layers: u16,
    max_resolution_end: u8,
) -> Result<Vec<ProgressionVolume>> {
    let state = resolve_effective_header_state(
        input,
        &codestream.siz,
        codestream.kind,
        &codestream.markers,
    )?;
    let mut tile_parts = state
        .tile_parts
        .iter()
        .copied()
        .filter(|part| part.tile_index == tile)
        .collect::<Vec<_>>();
    tile_parts.sort_by_key(|part| part.tile_part_index);
    let last_part = tile_parts.last().copied().ok_or_else(|| {
        invalid(
            None,
            Some(Marker::Sot),
            "packet scheduling requires at least one effective tile part",
        )
    })?;
    let component_end = codestream.siz.component_count();
    let mut volumes = Vec::new();
    let mut push_record =
        |record: ProgressionChangeRecord, marker_offset: usize, declared_tile_part: usize| {
            volumes.push(ProgressionVolume {
                resolution_start: record.resolution_start,
                component_start: record.component_start,
                layer_end: record.layer_end,
                resolution_end: record.resolution_end,
                component_end: record.component_end,
                progression_order: record.progression_order,
                declared_tile_part,
                marker_offset: Some(marker_offset),
            });
        };
    match state.progression_changes(last_part) {
        EffectiveProgressionChanges::Cod => volumes.push(ProgressionVolume {
            resolution_start: 0,
            component_start: 0,
            layer_end: layers,
            resolution_end: max_resolution_end,
            component_end,
            progression_order: state.coding_style(tile, 0).progression_order,
            declared_tile_part: 0,
            marker_offset: None,
        }),
        EffectiveProgressionChanges::Main(segment) => {
            for record in &segment.records {
                push_record(*record, segment.marker_offset, 0);
            }
        }
        EffectiveProgressionChanges::Tile(segments) => {
            for (segment_index, segment) in segments.iter().enumerate() {
                let declared_tile_part = tile_parts
                    .iter()
                    .position(|part| part.available_tile_poc_segments > segment_index)
                    .ok_or_else(|| {
                        invalid(
                            Some(segment.marker_offset),
                            Some(Marker::Poc),
                            "tile POC volume is not available from any retained tile part",
                        )
                    })?;
                for record in &segment.records {
                    push_record(*record, segment.marker_offset, declared_tile_part);
                }
            }
        }
    }
    if volumes.is_empty() {
        return Err(invalid(
            None,
            Some(Marker::Poc),
            "packet progression contains no effective volumes",
        ));
    }
    Ok(volumes)
}

fn progression_spatial_precincts(
    siz: &SizMarker,
    tile_reference_origin: (u64, u64),
    component_styles: &[CodingStyleMarker],
    topologies: &[Part1PrecinctTopology],
    component_start: u16,
    component_end: u16,
    resolution_start: u8,
    resolution_end: u8,
) -> Result<Vec<SpatialPrecinct>> {
    let mut positions = Vec::new();
    for component in component_start..component_end {
        let topology = topologies
            .get(usize::from(component))
            .ok_or(CodestreamError::SizeOverflow)?;
        let style = *component_styles
            .get(usize::from(component))
            .ok_or(CodestreamError::SizeOverflow)?;
        let actual_resolution_end = resolution_end.min(
            style
                .decomposition_levels
                .checked_add(1)
                .ok_or(CodestreamError::SizeOverflow)?,
        );
        for resolution in resolution_start..actual_resolution_end {
            let lattice = topology.reference_precinct_lattice(siz, style, resolution)?;
            positions
                .try_reserve(
                    usize::try_from(lattice.count).map_err(|_| CodestreamError::SizeOverflow)?,
                )
                .map_err(|_| CodestreamError::SizeOverflow)?;
            for row in 0..lattice.rows {
                for col in 0..lattice.cols {
                    positions.push(SpatialPrecinct {
                        x: lattice
                            .first_x
                            .checked_add(
                                u64::from(col)
                                    .checked_mul(lattice.step_x)
                                    .ok_or(CodestreamError::SizeOverflow)?,
                            )
                            .ok_or(CodestreamError::SizeOverflow)?
                            .max(tile_reference_origin.0),
                        y: lattice
                            .first_y
                            .checked_add(
                                u64::from(row)
                                    .checked_mul(lattice.step_y)
                                    .ok_or(CodestreamError::SizeOverflow)?,
                            )
                            .ok_or(CodestreamError::SizeOverflow)?
                            .max(tile_reference_origin.1),
                        component,
                        resolution,
                        precinct: row
                            .checked_mul(lattice.cols)
                            .and_then(|value| value.checked_add(col))
                            .ok_or(CodestreamError::SizeOverflow)?,
                    });
                }
            }
        }
    }
    Ok(positions)
}

fn visit_progression_volumes(
    siz: &SizMarker,
    tile: u16,
    tile_reference_origin: (u64, u64),
    layers: u16,
    component_styles: &[CodingStyleMarker],
    topologies: &[Part1PrecinctTopology],
    volumes: &[ProgressionVolume],
    mut visitor: impl FnMut(ScheduledPacket) -> Result<()>,
) -> Result<usize> {
    if component_styles.len() != topologies.len()
        || component_styles.len() != usize::from(siz.component_count())
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let mut ledger = PacketIdentityLedger::new(layers, topologies)?;
    for volume in volumes {
        let component_start = volume.component_start.min(siz.component_count());
        let component_end = volume.component_end.min(siz.component_count());
        let layer_end = volume.layer_end.min(layers);
        if component_start >= component_end
            || volume.resolution_start >= volume.resolution_end
            || layer_end == 0
        {
            return Err(invalid(
                volume.marker_offset,
                Some(Marker::Poc),
                "progression volume has no packets after intersecting the tile domains",
            ));
        }
        let mut emitted = 0_usize;
        let mut emit = |layer: u16, resolution: u8, component: u16, precinct: u32| {
            let packet = PacketKey {
                tile,
                layer,
                resolution,
                component,
                precinct,
            };
            if ledger.mark_if_new(packet)? {
                emitted = emitted
                    .checked_add(1)
                    .ok_or(CodestreamError::SizeOverflow)?;
                visitor(ScheduledPacket {
                    key: packet,
                    declared_tile_part: volume.declared_tile_part,
                    marker_offset: volume.marker_offset,
                })?;
            }
            Ok::<(), CodestreamError>(())
        };
        match volume.progression_order {
            ProgressionOrder::Lrcp => {
                for layer in 0..layer_end {
                    for resolution in volume.resolution_start..volume.resolution_end {
                        for component in component_start..component_end {
                            let Some(topology) = topologies.get(usize::from(component)) else {
                                return Err(CodestreamError::SizeOverflow);
                            };
                            let Some(resolution_topology) =
                                topology.resolutions.get(usize::from(resolution))
                            else {
                                continue;
                            };
                            for precinct in 0..resolution_topology.precinct_count {
                                emit(layer, resolution, component, precinct)?;
                            }
                        }
                    }
                }
            }
            ProgressionOrder::Rlcp => {
                for resolution in volume.resolution_start..volume.resolution_end {
                    for layer in 0..layer_end {
                        for component in component_start..component_end {
                            let Some(topology) = topologies.get(usize::from(component)) else {
                                return Err(CodestreamError::SizeOverflow);
                            };
                            let Some(resolution_topology) =
                                topology.resolutions.get(usize::from(resolution))
                            else {
                                continue;
                            };
                            for precinct in 0..resolution_topology.precinct_count {
                                emit(layer, resolution, component, precinct)?;
                            }
                        }
                    }
                }
            }
            ProgressionOrder::Rpcl | ProgressionOrder::Pcrl | ProgressionOrder::Cprl => {
                if matches!(
                    volume.progression_order,
                    ProgressionOrder::Rpcl | ProgressionOrder::Pcrl
                ) && siz.components[usize::from(component_start)..usize::from(component_end)]
                    .iter()
                    .any(|component| {
                        !component.horizontal_separation.is_power_of_two()
                            || !component.vertical_separation.is_power_of_two()
                    })
                {
                    return Err(invalid(
                        volume.marker_offset,
                        Some(Marker::Poc),
                        "spatial progression requires power-of-two component separations",
                    ));
                }
                let mut positions = progression_spatial_precincts(
                    siz,
                    tile_reference_origin,
                    component_styles,
                    topologies,
                    component_start,
                    component_end,
                    volume.resolution_start,
                    volume.resolution_end,
                )?;
                match volume.progression_order {
                    ProgressionOrder::Rpcl => positions.sort_by_key(|position| {
                        (
                            position.resolution,
                            position.y,
                            position.x,
                            position.component,
                        )
                    }),
                    ProgressionOrder::Pcrl => positions.sort_by_key(|position| {
                        (
                            position.y,
                            position.x,
                            position.component,
                            position.resolution,
                        )
                    }),
                    ProgressionOrder::Cprl => positions.sort_by_key(|position| {
                        (
                            position.component,
                            position.y,
                            position.x,
                            position.resolution,
                        )
                    }),
                    ProgressionOrder::Lrcp | ProgressionOrder::Rlcp => unreachable!(),
                }
                for position in positions {
                    for layer in 0..layer_end {
                        emit(
                            layer,
                            position.resolution,
                            position.component,
                            position.precinct,
                        )?;
                    }
                }
            }
        }
        if emitted == 0 {
            return Err(invalid(
                volume.marker_offset,
                Some(Marker::Poc),
                "progression volume duplicates packets already scheduled or has an empty actual domain",
            ));
        }
    }
    if !ledger.is_complete() {
        return Err(invalid(
            volumes.last().and_then(|volume| volume.marker_offset),
            Some(Marker::Poc),
            "progression volumes do not cover every packet in the coded tile exactly once",
        ));
    }
    Ok(ledger.expected_packet_count())
}

#[cfg(test)]
fn visit_default_precinct_packet_keys(
    tile: u16,
    progression_order: ProgressionOrder,
    layers: u16,
    decomposition_levels: u8,
    component_count: u16,
    precinct_counts: &[u32],
    visitor: impl FnMut(PacketKey) -> Result<()>,
) -> Result<()> {
    if precinct_counts.len() != usize::from(decomposition_levels) + 1
        || precinct_counts.contains(&0)
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let precinct_counts_by_component =
        alloc::vec![precinct_counts.to_vec(); usize::from(component_count)];
    visit_component_precinct_packet_keys(
        tile,
        progression_order,
        layers,
        &precinct_counts_by_component,
        visitor,
    )
}

#[cfg(test)]
fn visit_component_precinct_packet_keys(
    tile: u16,
    progression_order: ProgressionOrder,
    layers: u16,
    precinct_counts_by_component: &[Vec<u32>],
    mut visitor: impl FnMut(PacketKey) -> Result<()>,
) -> Result<()> {
    if precinct_counts_by_component.is_empty()
        || precinct_counts_by_component
            .iter()
            .any(|counts| counts.is_empty() || counts.contains(&0))
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let max_resolution = precinct_counts_by_component
        .iter()
        .map(|counts| counts.len() - 1)
        .max()
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut visit = |layer, resolution: usize, component: usize, precinct| {
        visitor(PacketKey {
            tile,
            layer,
            resolution: u8::try_from(resolution).map_err(|_| CodestreamError::SizeOverflow)?,
            component: u16::try_from(component).map_err(|_| CodestreamError::SizeOverflow)?,
            precinct,
        })
    };
    match progression_order {
        ProgressionOrder::Lrcp => {
            for layer in 0..layers {
                for resolution in 0..=max_resolution {
                    for (component, precinct_counts) in
                        precinct_counts_by_component.iter().enumerate()
                    {
                        let Some(&precinct_count) = precinct_counts.get(resolution) else {
                            continue;
                        };
                        for precinct in 0..precinct_count {
                            visit(layer, resolution, component, precinct)?;
                        }
                    }
                }
            }
        }
        ProgressionOrder::Rlcp => {
            for resolution in 0..=max_resolution {
                for layer in 0..layers {
                    for (component, precinct_counts) in
                        precinct_counts_by_component.iter().enumerate()
                    {
                        let Some(&precinct_count) = precinct_counts.get(resolution) else {
                            continue;
                        };
                        for precinct in 0..precinct_count {
                            visit(layer, resolution, component, precinct)?;
                        }
                    }
                }
            }
        }
        ProgressionOrder::Rpcl => {
            for resolution in 0..=max_resolution {
                let max_precincts = precinct_counts_by_component
                    .iter()
                    .filter_map(|counts| counts.get(resolution))
                    .copied()
                    .max()
                    .unwrap_or(0);
                for precinct in 0..max_precincts {
                    for (component, precinct_counts) in
                        precinct_counts_by_component.iter().enumerate()
                    {
                        if precinct_counts
                            .get(resolution)
                            .is_none_or(|count| precinct >= *count)
                        {
                            continue;
                        }
                        for layer in 0..layers {
                            visit(layer, resolution, component, precinct)?;
                        }
                    }
                }
            }
        }
        ProgressionOrder::Pcrl => {
            let max_precincts = precinct_counts_by_component
                .iter()
                .flatten()
                .copied()
                .max()
                .unwrap_or(0);
            for precinct in 0..max_precincts {
                for (component, precinct_counts) in precinct_counts_by_component.iter().enumerate()
                {
                    for (resolution, precinct_count) in precinct_counts.iter().enumerate() {
                        if precinct >= *precinct_count {
                            continue;
                        }
                        for layer in 0..layers {
                            visit(layer, resolution, component, precinct)?;
                        }
                    }
                }
            }
        }
        ProgressionOrder::Cprl => {
            for (component, precinct_counts) in precinct_counts_by_component.iter().enumerate() {
                let max_precincts = precinct_counts.iter().copied().max().unwrap_or(0);
                for precinct in 0..max_precincts {
                    for (resolution, precinct_count) in precinct_counts.iter().enumerate() {
                        if precinct >= *precinct_count {
                            continue;
                        }
                        for layer in 0..layers {
                            visit(layer, resolution, component, precinct)?;
                        }
                    }
                }
            }
        }
    }
    Ok(())
}

#[cfg(test)]
fn default_precinct_packet_order(
    tile: u16,
    progression_order: ProgressionOrder,
    layers: u16,
    decomposition_levels: u8,
    component_count: u16,
    precinct_counts: &[u32],
) -> Result<Vec<PacketKey>> {
    let mut packets = Vec::new();
    visit_default_precinct_packet_keys(
        tile,
        progression_order,
        layers,
        decomposition_levels,
        component_count,
        precinct_counts,
        |key| {
            packets.push(key);
            Ok(())
        },
    )?;
    Ok(packets)
}

