    #[test]
    fn parallel_ht_workspace_reuses_decoded_block_storage() {
        let width = 512_u32;
        let height = 512_u32;
        let samples = (0..width * height)
            .map(|index| ((index * 29 + index / width * 17 + 1) & 0xff) as u8)
            .collect::<Vec<_>>();
        let encoded = encode_htj2k_grayscale_u8_no_decomp(GrayscaleU8Encode {
            width,
            height,
            samples: &samples,
            stride_bytes: width as usize,
        })
        .unwrap();
        let profile = htj2k_lossless_no_decomp_workload_profile(&encoded)
            .unwrap()
            .unwrap();
        assert!(profile.included_code_block_count >= 3 * MIN_PARALLEL_CODE_BLOCKS);

        let mut workspace = HtCodestreamDecodeWorkspace::new();
        let first = decode_htj2k_lossless_owned_with_workspace(&encoded, &mut workspace)
            .unwrap()
            .unwrap();
        assert_eq!(first.components[0].samples, samples);

        let retained_capacities = if rayon::current_num_threads() > 1 {
            assert_eq!(
                workspace.parallel_decoded_blocks.len(),
                profile.included_code_block_count
            );
            assert_eq!(
                workspace.parallel_workers.len(),
                rayon::current_num_threads().min(profile.included_code_block_count)
            );
            Some(
                workspace
                    .parallel_decoded_blocks
                    .iter()
                    .map(|block| block.coefficients.capacity())
                    .collect::<Vec<_>>(),
            )
        } else {
            None
        };

        let second = decode_htj2k_lossless_owned_with_workspace(&encoded, &mut workspace)
            .unwrap()
            .unwrap();
        assert_eq!(second.components[0].samples, samples);
        if let Some(capacities) = retained_capacities {
            assert_eq!(
                workspace
                    .parallel_decoded_blocks
                    .iter()
                    .map(|block| block.coefficients.capacity())
                    .collect::<Vec<_>>(),
                capacities
            );
        }
    }

