#[cfg(feature = "parallel")]
struct DecodedCodeBlockContribution {
    contribution_index: usize,
    coefficients: Vec<i32>,
}

#[cfg(feature = "parallel")]
struct ParallelCodeBlockDecodeScratch {
    tier1: tier1::CodeBlockDecodeScratch,
    segment: Vec<u8>,
    coefficients: Vec<i32>,
}

#[cfg(feature = "parallel")]
impl ParallelCodeBlockDecodeScratch {
    fn new() -> Self {
        Self {
            tier1: tier1::CodeBlockDecodeScratch::new(),
            segment: Vec::new(),
            coefficients: Vec::new(),
        }
    }
}

#[cfg(feature = "parallel")]
fn reconstruct_default_precinct_component_planes_parallel(
    payload: &[u8],
    coding_style: CodingStyleMarker,
    tile_rect: TileRect,
    contributions: &[PacketCodeBlockContribution],
    component_count: usize,
) -> Result<Vec<Vec<i32>>> {
    if component_count == 1 {
        return reconstruct_single_component_planes_parallel(
            payload,
            coding_style,
            tile_rect,
            contributions,
        );
    }

    use rayon::prelude::*;
    use std::sync::Mutex;

    let stride = usize::try_from(tile_rect.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(tile_rect.height).map_err(|_| CodestreamError::SizeOverflow)?;
    let plane_len = stride
        .checked_mul(height)
        .ok_or(CodestreamError::SizeOverflow)?;
    let planes = (0..component_count)
        .map(|_| Mutex::new(alloc::vec![0_i32; plane_len]))
        .collect::<Vec<_>>();

    contributions.par_iter().try_for_each_init(
        ParallelCodeBlockDecodeScratch::new,
        |scratch, contribution| {
            decode_and_place_code_block_contribution(
                payload,
                coding_style,
                contribution,
                &planes,
                stride,
                &mut scratch.tier1,
                &mut scratch.segment,
                &mut scratch.coefficients,
            )
        },
    )?;

    let mut planes = planes
        .into_iter()
        .map(|plane| {
            plane
                .into_inner()
                .map_err(|_| CodestreamError::SizeOverflow)
        })
        .collect::<Result<Vec<_>>>()?;

    inverse_reversible_5_3_component_planes(&mut planes, stride, tile_rect, coding_style, None)?;

    Ok(planes)
}

#[cfg(feature = "parallel")]
fn reconstruct_single_component_planes_parallel(
    payload: &[u8],
    coding_style: CodingStyleMarker,
    tile_rect: TileRect,
    contributions: &[PacketCodeBlockContribution],
) -> Result<Vec<Vec<i32>>> {
    use rayon::prelude::*;

    let decoded_blocks = contributions
        .par_iter()
        .enumerate()
        .map_init(
            ParallelCodeBlockDecodeScratch::new,
            |scratch, (contribution_index, contribution)| {
                decode_code_block_contribution(
                    payload,
                    coding_style,
                    contribution_index,
                    contribution,
                    &mut scratch.tier1,
                    &mut scratch.segment,
                )
            },
        )
        .collect::<Result<Vec<_>>>()?;

    let stride = usize::try_from(tile_rect.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(tile_rect.height).map_err(|_| CodestreamError::SizeOverflow)?;
    let plane_len = stride
        .checked_mul(height)
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut plane = alloc::vec![0_i32; plane_len];

    for decoded in decoded_blocks {
        let contribution = contributions
            .get(decoded.contribution_index)
            .ok_or(CodestreamError::SizeOverflow)?;
        place_code_block_coefficients(&mut plane, stride, contribution, &decoded.coefficients)?;
    }

    let mut planes = alloc::vec![plane];
    inverse_reversible_5_3_component_planes(&mut planes, stride, tile_rect, coding_style, None)?;

    Ok(planes)
}

#[cfg(feature = "parallel")]
fn decode_code_block_contribution(
    payload: &[u8],
    coding_style: CodingStyleMarker,
    contribution_index: usize,
    contribution: &PacketCodeBlockContribution,
    scratch: &mut tier1::CodeBlockDecodeScratch,
    segment_scratch: &mut Vec<u8>,
) -> Result<DecodedCodeBlockContribution> {
    let segment = code_block_segment_for_decode(payload, contribution, segment_scratch)?;
    let decode_spec = code_block_decode_spec(coding_style, contribution)?;
    let implicit_coding_segment = [tier1::CodeBlockSegment {
        byte_len: segment.len(),
        coding_passes: contribution.coding_passes,
    }];
    let coding_segments = if contribution.coding_segments.is_empty() {
        &implicit_coding_segment
    } else {
        contribution.coding_segments.as_slice()
    };
    let coefficient_count = decode_spec.dimensions.coefficient_count();
    let mut coefficients = alloc::vec![0_i32; coefficient_count];
    if contribution.coding_segments.is_empty() {
        tier1::decode_baseline_code_block_with_adaptive_scratch(
            segment,
            decode_spec,
            &mut coefficients,
            scratch,
        )
    } else {
        tier1::decode_baseline_code_block_segments_with_adaptive_scratch(
            segment,
            coding_segments,
            decode_spec,
            &mut coefficients,
            scratch,
        )
    }
    .map_err(map_tier1_error)?;

    Ok(DecodedCodeBlockContribution {
        contribution_index,
        coefficients,
    })
}

#[cfg(feature = "parallel")]
fn decode_and_place_code_block_contribution(
    payload: &[u8],
    coding_style: CodingStyleMarker,
    contribution: &PacketCodeBlockContribution,
    planes: &[std::sync::Mutex<Vec<i32>>],
    stride: usize,
    scratch: &mut tier1::CodeBlockDecodeScratch,
    segment_scratch: &mut Vec<u8>,
    coefficient_scratch: &mut Vec<i32>,
) -> Result<()> {
    let segment = code_block_segment_for_decode(payload, contribution, segment_scratch)?;
    let decode_spec = code_block_decode_spec(coding_style, contribution)?;
    let implicit_coding_segment = [tier1::CodeBlockSegment {
        byte_len: segment.len(),
        coding_passes: contribution.coding_passes,
    }];
    let coding_segments = if contribution.coding_segments.is_empty() {
        &implicit_coding_segment
    } else {
        contribution.coding_segments.as_slice()
    };
    coefficient_scratch.resize(decode_spec.dimensions.coefficient_count(), 0);
    if contribution.coding_segments.is_empty() {
        tier1::decode_baseline_code_block_with_adaptive_scratch(
            segment,
            decode_spec,
            coefficient_scratch,
            scratch,
        )
    } else {
        tier1::decode_baseline_code_block_segments_with_adaptive_scratch(
            segment,
            coding_segments,
            decode_spec,
            coefficient_scratch,
            scratch,
        )
    }
    .map_err(map_tier1_error)?;

    let component_index = usize::from(contribution.component_index);
    let mut plane = planes
        .get(component_index)
        .ok_or(CodestreamError::SizeOverflow)?
        .lock()
        .map_err(|_| CodestreamError::SizeOverflow)?;
    place_code_block_coefficients(&mut plane, stride, contribution, coefficient_scratch)
}

#[cfg_attr(not(feature = "std"), allow(unused_mut, unused_variables))]
fn inverse_reversible_5_3_component_planes(
    planes: &mut [Vec<i32>],
    stride: usize,
    tile_rect: TileRect,
    coding_style: CodingStyleMarker,
    mut timings: Option<&mut DecodeStageTimings>,
) -> Result<()> {
    #[cfg(feature = "parallel")]
    if timings.is_none()
        && parallel_decode_dispatch_available()
        && should_parallel_inverse_reversible_components(
            planes.len(),
            tile_rect.width,
            tile_rect.height,
            coding_style.decomposition_levels,
        )
    {
        return inverse_reversible_5_3_component_planes_parallel(
            planes,
            stride,
            tile_rect,
            coding_style.decomposition_levels,
        );
    }

    let max_axis = usize::try_from(tile_rect.width.max(tile_rect.height))
        .map_err(|_| CodestreamError::SizeOverflow)?;
    let mut transform_scratch = alloc::vec![
        0_i32;
        max_axis
            .checked_mul(3)
            .ok_or(CodestreamError::SizeOverflow)?
    ];
    for plane in planes {
        #[cfg(feature = "std")]
        let stage_started = std::time::Instant::now();
        inverse_reversible_5_3_levels_with_scratch(
            plane,
            stride,
            tile_rect.width,
            tile_rect.height,
            coding_style.decomposition_levels,
            &mut transform_scratch,
        )?;
        #[cfg(feature = "std")]
        record_stage(
            &mut timings,
            DecodeStage::InverseReversible53,
            stage_started.elapsed(),
        );
    }
    Ok(())
}

fn should_parallel_inverse_reversible_components(
    component_count: usize,
    width: u32,
    height: u32,
    decomposition_levels: u8,
) -> bool {
    if component_count < 3 || decomposition_levels == 0 {
        return false;
    }

    let component_count = match u64::try_from(component_count) {
        Ok(component_count) => component_count,
        Err(_) => return false,
    };
    u64::from(width)
        .saturating_mul(u64::from(height))
        .saturating_mul(component_count)
        >= MIN_PARALLEL_CODE_BLOCK_COEFFICIENTS
}

#[cfg(feature = "parallel")]
fn inverse_reversible_5_3_component_planes_parallel(
    planes: &mut [Vec<i32>],
    stride: usize,
    tile_rect: TileRect,
    decomposition_levels: u8,
) -> Result<()> {
    use rayon::prelude::*;

    let max_axis = usize::try_from(tile_rect.width.max(tile_rect.height))
        .map_err(|_| CodestreamError::SizeOverflow)?;
    let scratch_len = max_axis
        .checked_mul(3)
        .ok_or(CodestreamError::SizeOverflow)?;

    planes.par_iter_mut().try_for_each(|plane| {
        let mut transform_scratch = alloc::vec![0_i32; scratch_len];
        inverse_reversible_5_3_levels_with_scratch(
            plane,
            stride,
            tile_rect.width,
            tile_rect.height,
            decomposition_levels,
            &mut transform_scratch,
        )
    })
}

#[cfg(feature = "parallel")]
fn clear_full_plane_parallel<T: Copy + Send + Sync>(
    plane: &mut [T],
    value: T,
    worker_count: usize,
) {
    use rayon::prelude::*;

    if worker_count <= 1 || plane.is_empty() {
        plane.fill(value);
        return;
    }
    let chunk_samples = plane.len().div_ceil(worker_count.min(plane.len()));
    plane
        .par_chunks_mut(chunk_samples)
        .for_each(|chunk| chunk.fill(value));
}

#[cfg(feature = "parallel")]
fn place_reversible_code_blocks_parallel(
    plane: &mut [i32],
    stride: usize,
    height: usize,
    tile: &PreparedPart1TileDecode<'_>,
    decoded_blocks: &[Part1ParallelDecodedCodeBlock],
    worker_count: usize,
    clear_before_placement: bool,
) -> Result<()> {
    use rayon::prelude::*;

    for decoded in decoded_blocks {
        let contribution = tile
            .contributions
            .get(decoded.contribution_index)
            .ok_or(CodestreamError::SizeOverflow)?;
        let width = usize::from(contribution.width);
        let block_height = usize::from(contribution.height);
        let start_x = usize::try_from(contribution.x).map_err(|_| CodestreamError::SizeOverflow)?;
        let start_y = usize::try_from(contribution.y).map_err(|_| CodestreamError::SizeOverflow)?;
        if decoded.coefficients.len()
            < width
                .checked_mul(block_height)
                .ok_or(CodestreamError::SizeOverflow)?
            || start_x
                .checked_add(width)
                .ok_or(CodestreamError::SizeOverflow)?
                > stride
            || start_y
                .checked_add(block_height)
                .ok_or(CodestreamError::SizeOverflow)?
                > height
        {
            return Err(CodestreamError::SizeOverflow);
        }
    }
    if height == 0 {
        return Ok(());
    }
    let active_workers = worker_count.max(1).min(height);
    let chunk_rows = height.div_ceil(active_workers);
    plane
        .par_chunks_mut(chunk_rows * stride)
        .enumerate()
        .try_for_each(|(chunk_index, rows)| {
            if clear_before_placement {
                rows.fill(0);
            }
            let chunk_y = chunk_index * chunk_rows;
            let rows_in_chunk = rows.len() / stride;
            let chunk_y_end = chunk_y + rows_in_chunk;
            for decoded in decoded_blocks {
                let contribution = &tile.contributions[decoded.contribution_index];
                let width = usize::from(contribution.width);
                let block_height = usize::from(contribution.height);
                let start_x = contribution.x as usize;
                let start_y = contribution.y as usize;
                let first_y = start_y.max(chunk_y);
                let end_y = start_y.saturating_add(block_height).min(chunk_y_end);
                for y in first_y..end_y {
                    let source_row = y - start_y;
                    let destination_row = y - chunk_y;
                    let source_start = source_row * width;
                    let destination_start = destination_row * stride + start_x;
                    rows[destination_start..destination_start + width]
                        .copy_from_slice(&decoded.coefficients[source_start..source_start + width]);
                }
            }
            Ok(())
        })
}

fn place_code_block_coefficients(
    plane: &mut [i32],
    stride: usize,
    contribution: &PacketCodeBlockContribution,
    coefficients: &[i32],
) -> Result<()> {
    let width = usize::from(contribution.width);
    let height = usize::from(contribution.height);
    let start_x = usize::try_from(contribution.x).map_err(|_| CodestreamError::SizeOverflow)?;
    let start_y = usize::try_from(contribution.y).map_err(|_| CodestreamError::SizeOverflow)?;
    let coefficient_count = width
        .checked_mul(height)
        .ok_or(CodestreamError::SizeOverflow)?;
    if coefficients.len() < coefficient_count {
        return Err(CodestreamError::SizeOverflow);
    }
    if height == 0 {
        return Ok(());
    }

    let dst_start = start_y
        .checked_mul(stride)
        .and_then(|offset| offset.checked_add(start_x))
        .ok_or(CodestreamError::SizeOverflow)?;
    let last_row = height - 1;
    let dst_last_end = dst_start
        .checked_add(
            last_row
                .checked_mul(stride)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .and_then(|offset| offset.checked_add(width))
        .ok_or(CodestreamError::SizeOverflow)?;
    if dst_last_end > plane.len() {
        return Err(CodestreamError::SizeOverflow);
    }

    let mut src = 0_usize;
    let mut dst = dst_start;
    for _ in 0..height {
        plane[dst..dst + width].copy_from_slice(&coefficients[src..src + width]);
        src += width;
        dst += stride;
    }
    Ok(())
}

#[cfg(feature = "std")]
fn place_ht_code_block_coefficients(
    plane: &mut [i32],
    stride: usize,
    contribution: &PacketCodeBlockContribution,
    coefficients: &[i32],
    transfer: Option<HtReversibleCodeBlockTransfer>,
) -> Result<()> {
    let width = usize::from(contribution.width);
    let height = usize::from(contribution.height);
    let start_x = usize::try_from(contribution.x).map_err(|_| CodestreamError::SizeOverflow)?;
    let start_y = usize::try_from(contribution.y).map_err(|_| CodestreamError::SizeOverflow)?;
    let coefficient_count = width
        .checked_mul(height)
        .ok_or(CodestreamError::SizeOverflow)?;
    if coefficients.len() < coefficient_count {
        return Err(CodestreamError::SizeOverflow);
    }
    if height == 0 {
        return Ok(());
    }

    let dst_start = start_y
        .checked_mul(stride)
        .and_then(|offset| offset.checked_add(start_x))
        .ok_or(CodestreamError::SizeOverflow)?;
    let dst_last_end = dst_start
        .checked_add(
            (height - 1)
                .checked_mul(stride)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .and_then(|offset| offset.checked_add(width))
        .ok_or(CodestreamError::SizeOverflow)?;
    if dst_last_end > plane.len() {
        return Err(CodestreamError::SizeOverflow);
    }

    match transfer {
        Some(transfer) => {
            for (source, destination) in coefficients[..coefficient_count]
                .chunks_exact(width)
                .zip(plane[dst_start..].chunks_mut(stride))
                .take(height)
            {
                for (destination, coefficient) in
                    destination[..width].iter_mut().zip(source.iter().copied())
                {
                    *destination =
                        openjph_reversible_transfer_decoded_coefficient(coefficient, transfer);
                }
            }
        }
        None => {
            for (source, destination) in coefficients[..coefficient_count]
                .chunks_exact(width)
                .zip(plane[dst_start..].chunks_mut(stride))
                .take(height)
            {
                destination[..width].copy_from_slice(source);
            }
        }
    }
    Ok(())
}

#[cfg(feature = "std")]
fn place_ht_code_block_samples(
    samples: &mut [u8],
    stride: usize,
    bits_per_sample: u8,
    contribution: &PacketCodeBlockContribution,
    coefficients: &[i32],
    transfer: Option<HtReversibleCodeBlockTransfer>,
) -> Result<()> {
    let width = usize::from(contribution.width);
    let height = usize::from(contribution.height);
    let start_x = usize::try_from(contribution.x).map_err(|_| CodestreamError::SizeOverflow)?;
    let start_y = usize::try_from(contribution.y).map_err(|_| CodestreamError::SizeOverflow)?;
    let coefficient_count = width
        .checked_mul(height)
        .ok_or(CodestreamError::SizeOverflow)?;
    if coefficients.len() < coefficient_count {
        return Err(CodestreamError::SizeOverflow);
    }
    if height == 0 {
        return Ok(());
    }

    let bytes_per_sample = component_sample_byte_width(bits_per_sample)?;
    let sample_start = start_y
        .checked_mul(stride)
        .and_then(|offset| offset.checked_add(start_x))
        .ok_or(CodestreamError::SizeOverflow)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    let byte_stride = stride
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    let byte_start = sample_start
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    let byte_last_end = byte_start
        .checked_add(
            (height - 1)
                .checked_mul(byte_stride)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .and_then(|offset| offset.checked_add(row_bytes))
        .ok_or(CodestreamError::SizeOverflow)?;
    if byte_last_end > samples.len() {
        return Err(CodestreamError::SizeOverflow);
    }

    match (bits_per_sample, transfer) {
        (8, Some(transfer)) => {
            for (source, destination) in coefficients[..coefficient_count]
                .chunks_exact(width)
                .zip(samples[byte_start..].chunks_mut(byte_stride))
                .take(height)
            {
                for (sample, coefficient) in
                    destination[..width].iter_mut().zip(source.iter().copied())
                {
                    let coefficient =
                        openjph_reversible_transfer_decoded_coefficient(coefficient, transfer);
                    *sample = (coefficient + 128).clamp(0, 255) as u8;
                }
            }
        }
        (8, None) => {
            for (source, destination) in coefficients[..coefficient_count]
                .chunks_exact(width)
                .zip(samples[byte_start..].chunks_mut(byte_stride))
                .take(height)
            {
                for (sample, coefficient) in
                    destination[..width].iter_mut().zip(source.iter().copied())
                {
                    *sample = (coefficient + 128).clamp(0, 255) as u8;
                }
            }
        }
        (_, Some(transfer)) => {
            let offset = 1_i32 << (bits_per_sample - 1);
            let max_value = (1_i32 << bits_per_sample) - 1;
            for (source, destination) in coefficients[..coefficient_count]
                .chunks_exact(width)
                .zip(samples[byte_start..].chunks_mut(byte_stride))
                .take(height)
            {
                for (sample_bytes, coefficient) in destination[..row_bytes]
                    .chunks_exact_mut(2)
                    .zip(source.iter().copied())
                {
                    let coefficient =
                        openjph_reversible_transfer_decoded_coefficient(coefficient, transfer);
                    let sample = (coefficient + offset).clamp(0, max_value) as u16;
                    sample_bytes[0] = sample as u8;
                    sample_bytes[1] = (sample >> 8) as u8;
                }
            }
        }
        (_, None) => {
            let offset = 1_i32 << (bits_per_sample - 1);
            let max_value = (1_i32 << bits_per_sample) - 1;
            for (source, destination) in coefficients[..coefficient_count]
                .chunks_exact(width)
                .zip(samples[byte_start..].chunks_mut(byte_stride))
                .take(height)
            {
                for (sample_bytes, coefficient) in destination[..row_bytes]
                    .chunks_exact_mut(2)
                    .zip(source.iter().copied())
                {
                    let sample = (coefficient + offset).clamp(0, max_value) as u16;
                    sample_bytes[0] = sample as u8;
                    sample_bytes[1] = (sample >> 8) as u8;
                }
            }
        }
    }
    Ok(())
}

#[cfg(feature = "std")]
#[inline(never)]
fn place_signed_ht_code_block_samples(
    samples: &mut [u8],
    stride: usize,
    bits_per_sample: u8,
    contribution: &PacketCodeBlockContribution,
    coefficients: &[i32],
    transfer: Option<HtReversibleCodeBlockTransfer>,
) -> Result<()> {
    let width = usize::from(contribution.width);
    let height = usize::from(contribution.height);
    let start_x = usize::try_from(contribution.x).map_err(|_| CodestreamError::SizeOverflow)?;
    let start_y = usize::try_from(contribution.y).map_err(|_| CodestreamError::SizeOverflow)?;
    let coefficient_count = width
        .checked_mul(height)
        .ok_or(CodestreamError::SizeOverflow)?;
    if coefficients.len() < coefficient_count {
        return Err(CodestreamError::SizeOverflow);
    }
    if height == 0 {
        return Ok(());
    }

    let bytes_per_sample = component_sample_byte_width(bits_per_sample)?;
    let sample_start = start_y
        .checked_mul(stride)
        .and_then(|offset| offset.checked_add(start_x))
        .ok_or(CodestreamError::SizeOverflow)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    let byte_stride = stride
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    let byte_start = sample_start
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    let byte_last_end = byte_start
        .checked_add(
            (height - 1)
                .checked_mul(byte_stride)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .and_then(|offset| offset.checked_add(row_bytes))
        .ok_or(CodestreamError::SizeOverflow)?;
    if byte_last_end > samples.len() {
        return Err(CodestreamError::SizeOverflow);
    }

    place_preflighted_signed_ht_code_block_samples(
        samples,
        byte_start,
        byte_stride,
        row_bytes,
        width,
        height,
        bits_per_sample,
        coefficients,
        transfer,
    )
}

#[cfg(feature = "std")]
#[allow(clippy::too_many_arguments)]
fn place_preflighted_signed_ht_code_block_samples(
    samples: &mut [u8],
    byte_start: usize,
    byte_stride: usize,
    row_bytes: usize,
    width: usize,
    height: usize,
    bits_per_sample: u8,
    coefficients: &[i32],
    transfer: Option<HtReversibleCodeBlockTransfer>,
) -> Result<()> {
    let min_value = -(1_i32 << (bits_per_sample - 1));
    let max_value = (1_i32 << (bits_per_sample - 1)) - 1;

    match (bits_per_sample, transfer) {
        (8, Some(transfer)) => {
            for (source, destination) in coefficients
                .chunks_exact(width)
                .zip(samples[byte_start..].chunks_mut(byte_stride))
                .take(height)
            {
                for (sample, coefficient) in
                    destination[..width].iter_mut().zip(source.iter().copied())
                {
                    let coefficient =
                        openjph_reversible_transfer_decoded_coefficient(coefficient, transfer);
                    *sample = coefficient.clamp(min_value, max_value) as u8;
                }
            }
        }
        (8, None) => {
            for (source, destination) in coefficients
                .chunks_exact(width)
                .zip(samples[byte_start..].chunks_mut(byte_stride))
                .take(height)
            {
                for (sample, coefficient) in
                    destination[..width].iter_mut().zip(source.iter().copied())
                {
                    *sample = coefficient.clamp(min_value, max_value) as u8;
                }
            }
        }
        (_, Some(transfer)) => {
            for (source, destination) in coefficients
                .chunks_exact(width)
                .zip(samples[byte_start..].chunks_mut(byte_stride))
                .take(height)
            {
                for (sample_bytes, coefficient) in destination[..row_bytes]
                    .chunks_exact_mut(2)
                    .zip(source.iter().copied())
                {
                    let coefficient =
                        openjph_reversible_transfer_decoded_coefficient(coefficient, transfer);
                    let sample = coefficient.clamp(min_value, max_value) as u16;
                    sample_bytes[0] = sample as u8;
                    sample_bytes[1] = (sample >> 8) as u8;
                }
            }
        }
        (_, None) => {
            for (source, destination) in coefficients
                .chunks_exact(width)
                .zip(samples[byte_start..].chunks_mut(byte_stride))
                .take(height)
            {
                for (sample_bytes, coefficient) in destination[..row_bytes]
                    .chunks_exact_mut(2)
                    .zip(source.iter().copied())
                {
                    let sample = coefficient.clamp(min_value, max_value) as u16;
                    sample_bytes[0] = sample as u8;
                    sample_bytes[1] = (sample >> 8) as u8;
                }
            }
        }
    }
    Ok(())
}

fn inverse_reversible_5_3_levels_with_scratch(
    plane: &mut [i32],
    stride: usize,
    width: u32,
    height: u32,
    decomposition_levels: u8,
    scratch: &mut [i32],
) -> Result<()> {
    inverse_reversible_5_3_levels_with_scratch_profiled(
        plane,
        stride,
        width,
        height,
        decomposition_levels,
        scratch,
        false,
    )
    .map(|_| ())
}

#[allow(clippy::too_many_arguments)]
fn inverse_reversible_5_3_levels_with_scratch_profiled(
    plane: &mut [i32],
    stride: usize,
    width: u32,
    height: u32,
    decomposition_levels: u8,
    scratch: &mut [i32],
    collect_stage_timings: bool,
) -> Result<transform::WindowSynthesisStageTimings> {
    let mut stages = transform::WindowSynthesisStageTimings::default();
    for resolution in 1..=decomposition_levels {
        let (level_width, level_height) =
            resolution_dimensions(width, height, decomposition_levels, resolution)?;
        let level_width =
            usize::try_from(level_width).map_err(|_| CodestreamError::SizeOverflow)?;
        let level_height =
            usize::try_from(level_height).map_err(|_| CodestreamError::SizeOverflow)?;
        let config = transform::Reversible53Config {
            width: level_width,
            height: level_height,
            stride,
            edges: transform::Reversible53Edges::from_tile_origin(0, 0, level_width, level_height),
            sample_range: transform::ComponentSampleRange::signed(32),
        };
        let level = transform::inverse_reversible_5_3_bounded_with_stage_timings(
            plane,
            config,
            scratch,
            collect_stage_timings,
        )
        .map_err(|_| {
            unsupported(
                None,
                None,
                UnsupportedConstruct::Transform,
                "inverse reversible 5/3 reconstruction failed for profile-scoped native Part 1 decode",
            )
        })?;
        stages.horizontal_ns = stages.horizontal_ns.saturating_add(level.horizontal_ns);
        stages.vertical_ns = stages.vertical_ns.saturating_add(level.vertical_ns);
        stages.level_preparation_ns = stages
            .level_preparation_ns
            .saturating_add(level.level_preparation_ns);
    }
    Ok(stages)
}

